        add_action('wp_ajax_sffc_crm_admin_archive_post_to_hr', [$this, 'ajax_archive_post_to_hr']);
        add_action('wp_ajax_sffc_crm_admin_bulk_action', [$this, 'ajax_bulk_action']);
        add_action('wp_ajax_sffc_crm_admin_quick_edit', [$this, 'ajax_quick_edit']);
        add_action('wp_ajax_sffc_crm_extract_keywords', [$this, 'ajax_extract_keywords']);
        add_action('wp_ajax_sffc_crm_get_keywords', [$this, 'ajax_get_keywords']);
        add_action('wp_ajax_sffc_crm_bulk_extract_keywords', [$this, 'ajax_bulk_extract_keywords']);
