    /**
     * Initialize groups admin early
     */
    private function init_groups_admin()
    {
        require_once SFFC_PLUGIN_DIR . 'includes/crm/admin/class-crm-admin-groups.php';
        $this->groups_admin = new SFFC_CRM_Admin_Groups();
    }

    /**
     * Initialize Company Prep admin helper and AJAX handlers
     */
    private function init_company_prep_admin()
    {
        $helper_path = SFFC_PLUGIN_DIR . 'includes/crm/admin/class-crm-admin-company-prep.php';

        if (!file_exists($helper_path)) {
            return;
        }

        require_once $helper_path;

        if (class_exists('SFFC_CRM_Admin_Company_Prep')) {
            $this->company_prep_admin = SFFC_CRM_Admin_Company_Prep::get_instance();
        }
    }

    private function ensure_default_post_group()
    {
        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';

        $group_model = new SFFC_CRM_Post_Group();
        $default_group = $group_model->get_by_slug('senna-community');

        if (!empty($default_group['id'])) {
            return (int) $default_group['id'];
        }

        $created_group_id = $group_model->create([
            'name' => __('MENA Careers Community', 'senna-finance'),
            'slug' => 'senna-community',
            'description' => __('Default community feed group for recruiter-led roles.', 'senna-finance'),
            'display_order' => 0,
            'is_active' => 1,
        ]);

        return $created_group_id ? (int) $created_group_id : 0;
    }

    private function ensure_crm_auto_post_group($name, $slug, $description = '', $display_order = 50)
    {
        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';

        $group_model = new SFFC_CRM_Post_Group();
        $existing_group = $group_model->get_by_slug($slug);

        if (!empty($existing_group['id'])) {
            return (int) $existing_group['id'];
        }

        $created_group_id = $group_model->create([
            'name' => $name,
            'slug' => $slug,
            'description' => $description,
            'display_order' => $display_order,
            'is_active' => 1,
        ]);

        return $created_group_id ? (int) $created_group_id : 0;
    }

    private function determine_crm_auto_post_group(array $post_data)
    {
        $location = trim((string) ($post_data['location'] ?? ''));
        $location_city = trim((string) ($post_data['location_city'] ?? ''));
        $location_country = trim((string) ($post_data['location_country'] ?? ''));
        $role_title = trim((string) ($post_data['role_title'] ?? ''));
        $seniority = trim((string) ($post_data['seniority'] ?? ''));

        $location_cluster = $this->map_crm_post_group_location_cluster($location, $location_city, $location_country);
        $career_band = $this->map_crm_post_group_career_band($seniority, $role_title);

        if ($location_cluster === '' || $career_band === '') {
            return null;
        }

        $name = $location_cluster . ' ' . $career_band;
        $slug = sanitize_title($name);
        $description = sprintf(
            __('Auto-created group for %1$s roles in %2$s.', 'senna-finance'),
            strtolower($career_band),
            $location_cluster
        );

        return [
            'name' => $name,
            'slug' => $slug,
            'description' => $description,
            'display_order' => $this->get_crm_post_group_display_order($location_cluster, $career_band),
        ];
    }

    private function map_crm_post_group_location_cluster($location, $location_city = '', $location_country = '')
    {
        $combined = strtolower(trim(implode(' ', array_filter([$location_city, $location_country, $location]))));

        if ($combined === '') {
            return '';
        }

        $core_city_map = [
            'london' => 'London',
            'dubai' => 'Dubai',
            'riyadh' => 'Riyadh',
            'abu dhabi' => 'Abu Dhabi',
        ];

        foreach ($core_city_map as $needle => $label) {
            if (strpos($combined, $needle) !== false) {
                return $label;
            }
        }

        $private_equity_markers = [
            'uae',
            'united arab emirates',
            'saudi',
            'saudi arabia',
            'qatar',
            'doha',
            'oman',
            'muscat',
            'bahrain',
            'manama',
            'kuwait',
            'kuwait city',
            'egypt',
            'cairo',
            'gcc',
            'private_equity',
            'private equity',
            'abu dhabi',
            'riyadh',
            'jeddah',
            'dammam',
        ];
        foreach ($private_equity_markers as $marker) {
            if (strpos($combined, $marker) !== false) {
                return 'private equity';
            }
        }

        $uk_markers = ['united kingdom', 'uk', 'england', 'scotland', 'manchester', 'edinburgh'];
        foreach ($uk_markers as $marker) {
            if (strpos($combined, $marker) !== false) {
                return 'UK';
            }
        }

        $europe_markers = [
            'france',
            'paris',
            'spain',
            'madrid',
            'barcelona',
            'italy',
            'milan',
            'germany',
            'frankfurt',
            'munich',
            'berlin',
            'switzerland',
            'zurich',
            'geneva',
            'netherlands',
            'amsterdam',
            'portugal',
            'lisbon',
            'stockholm',
            'sweden',
            'luxembourg',
        ];
        foreach ($europe_markers as $marker) {
            if (strpos($combined, $marker) !== false) {
                return 'Europe';
            }
        }

        if (strpos($combined, 'new york') !== false || strpos($combined, 'united states') !== false || strpos($combined, 'usa') !== false) {
            return 'US';
        }

        if (strpos($combined, 'singapore') !== false || strpos($combined, 'hong kong') !== false || strpos($combined, 'india') !== false || strpos($combined, 'mumbai') !== false) {
            return 'Asia';
        }

        return 'Global';
    }

    private function map_crm_post_group_career_band($seniority, $role_title = '')
    {
        $seniority = trim((string) $seniority);
        $role_title = strtolower(trim((string) $role_title));

        if ($seniority === 'intern' || preg_match('/\b(intern(ship)?|off[- ]cycle|summer)\b/', $role_title)) {
            return 'Early Career Roles';
        }

        if (in_array($seniority, ['analyst', 'senior_analyst'], true) || preg_match('/\b(analyst|research analyst|investment analyst)\b/', $role_title)) {
            return 'Analyst Roles';
        }

        if (in_array($seniority, ['associate', 'senior_associate'], true) || preg_match('/\bassociate\b/', $role_title)) {
            return 'Associate Roles';
        }

        if (
            in_array($seniority, ['vp', 'senior_vp', 'director', 'md', 'partner', 'c_level', 'board'], true)
            || preg_match('/\b(vp|vice president|director|managing director|partner|principal|head|chief|president)\b/', $role_title)
        ) {
            return 'Senior Roles';
        }

        return 'Private Equity Roles';
    }

    private function get_crm_post_group_display_order($location_cluster, $career_band)
    {
        $location_order = [
            'Dubai' => 10,
            'Abu Dhabi' => 20,
            'Riyadh' => 30,
            'private equity' => 40,
            'London' => 60,
            'UK' => 70,
            'Europe' => 80,
            'US' => 90,
            'Asia' => 100,
            'Global' => 110,
        ];

        $band_order = [
            'Early Career Roles' => 1,
            'Analyst Roles' => 2,
            'Associate Roles' => 3,
            'Senior Roles' => 4,
            'Private Equity Roles' => 5,
        ];

        return (int) (($location_order[$location_cluster] ?? 100) + ($band_order[$career_band] ?? 5));
    }

