            <script>
                jQuery(document).ready(function($) {
                    $('#sffc-extract-requirements-btn').on('click', function() {
                        var $btn = $(this);
                        var $result = $('#sffc-extract-requirements-result');

                        $btn.prop('disabled', true).text('Processing...');
                        $result.hide();

                        $.ajax({
                            url: ajaxurl,
                            type: 'POST',
                            data: {
                                action: 'sffc_crm_bulk_extract_requirements',
                                limit: 50,
                                offset: 0
                            },
                            success: function(response) {
                                if (response.success) {
                                    $result.html('<p style="color: #16a34a; font-weight: bold;">✓ ' + response.data.message + '</p>' +
                                        '<pre>' + JSON.stringify(response.data.results, null, 2) + '</pre>').show();
                                } else {
                                    $result.html('<p style="color: #dc2626; font-weight: bold;">✗ Error: ' + response.data.message + '</p>').show();
                                }
                            },
                            error: function() {
                                $result.html('<p style="color: #dc2626; font-weight: bold;">✗ Request failed</p>').show();
                            },
                            complete: function() {
                                $btn.prop('disabled', false).text('Extract Requirements (Nationality)');
                            }
                        });
                    });
                });
            </script>

