    /**
     * Render pending posts table
     */
    private function render_pending_posts_table()
    {
        $post_model = new SFFC_CRM_Post();
        $pending = $post_model->get_pending_posts(10);

        if (empty($pending)) {
            echo '<p>' . esc_html__('No posts pending approval.', 'senna-finance') . '</p>';
            return;
        }
    ?>
        <table class="wp-list-table widefat fixed striped">
            <thead>
                <tr>
                    <th><?php esc_html_e('Role', 'senna-finance'); ?></th>
                    <th><?php esc_html_e('Recruiter', 'senna-finance'); ?></th>
                    <th><?php esc_html_e('Location', 'senna-finance'); ?></th>
                    <th><?php esc_html_e('Added', 'senna-finance'); ?></th>
                    <th><?php esc_html_e('Actions', 'senna-finance'); ?></th>
                </tr>
            </thead>
            <tbody>
                <?php foreach ($pending as $post): ?>
                    <tr>
                        <td>
                            <strong><?php echo esc_html($post['role_title']); ?></strong>
                            <?php if ($post['company']): ?>
                                <br><span class="description"><?php echo esc_html($post['company']); ?></span>
                            <?php endif; ?>
                        </td>
                        <td><?php echo esc_html($post['recruiter_name'] ?? 'Unknown'); ?></td>
                        <td><?php echo esc_html($post['location']); ?></td>
                        <td><?php echo esc_html(human_time_diff(strtotime($post['created_at'])) . ' ago'); ?></td>
                        <td>
                            <a href="<?php echo wp_nonce_url(admin_url('admin.php?page=sffc-crm-posts&action=approve&id=' . $post['id']), 'crm_approve_' . $post['id']); ?>" class="button button-small button-primary">
                                <?php esc_html_e('Approve', 'senna-finance'); ?>
                            </a>
                            <a href="<?php echo admin_url('admin.php?page=sffc-crm-posts&action=edit&id=' . $post['id']); ?>" class="button button-small">
                                <?php esc_html_e('Edit', 'senna-finance'); ?>
                            </a>
                            <a href="<?php echo wp_nonce_url(admin_url('admin.php?page=sffc-crm-posts&action=reject&id=' . $post['id']), 'crm_reject_' . $post['id']); ?>" class="button button-small" style="color: #dc2626;">
                                <?php esc_html_e('Reject', 'senna-finance'); ?>
                            </a>
                        </td>
                    </tr>
                <?php endforeach; ?>
            </tbody>
        </table>
    <?php
    }

    /**
     * Render posts management page
     */
    public function render_posts_page()
    {
        $post_model = new SFFC_CRM_Post();
        $filter = sanitize_text_field($_GET['filter'] ?? 'all');
        $page = max(1, intval($_GET['paged'] ?? 1));
        $per_page_options = [20, 50, 100, 200];
        $requested_per_page = max(1, intval($_GET['per_page'] ?? 20));
        $per_page = in_array($requested_per_page, $per_page_options, true) ? $requested_per_page : 20;
        $offset = ($page - 1) * $per_page;
        $recruiter_id = isset($_GET['recruiter_id']) ? intval($_GET['recruiter_id']) : 0;
        $search_term = sanitize_text_field(wp_unslash($_GET['s'] ?? ''));
        $role_title_filter = sanitize_text_field(wp_unslash($_GET['role_title'] ?? ''));
        $recruiter_filter = sanitize_text_field(wp_unslash($_GET['recruiter'] ?? ''));
        $location_filter = sanitize_text_field(wp_unslash($_GET['location'] ?? ''));
        $sector_filter = sanitize_key($_GET['sector'] ?? '');
        $status_filter = sanitize_key($_GET['status'] ?? '');

        $args = [
            'page' => $page,
            'per_page' => $per_page,
            'approved_only' => false,
        ];

        if ($recruiter_id) {
            $args['recruiter_id'] = $recruiter_id;
        }

        if ($search_term !== '') {
            $args['search'] = $search_term;
        }

        if ($role_title_filter !== '') {
            $args['role_title'] = $role_title_filter;
        }

        if ($recruiter_filter !== '') {
            $args['recruiter_name'] = $recruiter_filter;
        }

        if ($location_filter !== '') {
            $args['location'] = $location_filter;
        }

        if ($sector_filter !== '') {
            $args['sector'] = $sector_filter;
        }

        if ($status_filter !== '') {
            $args['post_status'] = $status_filter;
        }

        $base_args = [
            'page' => 'sffc-crm-posts',
            'per_page' => $per_page,
        ];

        if ($recruiter_id) {
            $base_args['recruiter_id'] = $recruiter_id;
        }

        if ($search_term !== '') {
            $base_args['s'] = $search_term;
        }

        if ($role_title_filter !== '') {
            $base_args['role_title'] = $role_title_filter;
        }

        if ($recruiter_filter !== '') {
            $base_args['recruiter'] = $recruiter_filter;
        }

        if ($location_filter !== '') {
            $base_args['location'] = $location_filter;
        }

        if ($sector_filter !== '') {
            $base_args['sector'] = $sector_filter;
        }

        if ($status_filter !== '') {
            $base_args['status'] = $status_filter;
        }

        if ($filter === 'pending') {
            $args['approved_only'] = false;
            global $wpdb;
            $where = "WHERE p.is_active = 1 AND p.admin_approved = 0";
            $params = [];

            if ($recruiter_id) {
                $where .= " AND p.recruiter_id = %d";
                $params[] = $recruiter_id;
            }

            if ($search_term !== '') {
                $where .= " AND (p.role_title LIKE %s OR p.content LIKE %s OR p.company LIKE %s OR r.name LIKE %s OR r.firm LIKE %s)";
                $like = '%' . $wpdb->esc_like($search_term) . '%';
                $params[] = $like;
                $params[] = $like;
                $params[] = $like;
                $params[] = $like;
                $params[] = $like;
            }

            if ($role_title_filter !== '') {
                $where .= " AND p.role_title LIKE %s";
                $params[] = '%' . $wpdb->esc_like($role_title_filter) . '%';
            }

            if ($recruiter_filter !== '') {
                $where .= " AND (r.name LIKE %s OR r.firm LIKE %s)";
                $like = '%' . $wpdb->esc_like($recruiter_filter) . '%';
                $params[] = $like;
                $params[] = $like;
            }

            if ($location_filter !== '') {
                $where .= " AND (p.location LIKE %s OR p.location_city LIKE %s OR p.location_country LIKE %s)";
                $like = '%' . $wpdb->esc_like($location_filter) . '%';
                $params[] = $like;
                $params[] = $like;
                $params[] = $like;
            }

            if ($sector_filter !== '') {
                $where .= " AND p.sector = %s";
                $params[] = $sector_filter;
            }

            if ($status_filter !== '') {
                if ($status_filter === 'open') {
                    $where .= " AND (p.post_status IS NULL OR p.post_status = 'open')";
                } else {
                    $where .= " AND p.post_status = %s";
                    $params[] = $status_filter;
                }
            }

            $params[] = $per_page;
            $params[] = $offset;

            $sql = "SELECT p.*, r.name as recruiter_name, r.firm as recruiter_firm
                    FROM {$wpdb->prefix}sffc_crm_posts p
                    LEFT JOIN {$wpdb->prefix}sffc_crm_recruiters r ON r.id = p.recruiter_id
                    {$where}
                    ORDER BY p.created_at DESC
                    LIMIT %d OFFSET %d";

            $posts = $wpdb->get_results($wpdb->prepare($sql, $params), ARRAY_A);
        } else {
            $posts = $post_model->get_feed($args);
        }

        $count_args = [
            'approved_only' => false,
            'pending_only' => $filter === 'pending',
        ];

        if ($recruiter_id) {
            $count_args['recruiter_id'] = $recruiter_id;
        }

        if ($search_term !== '') {
            $count_args['search'] = $search_term;
        }

        if ($role_title_filter !== '') {
            $count_args['role_title'] = $role_title_filter;
        }

        if ($recruiter_filter !== '') {
            $count_args['recruiter_name'] = $recruiter_filter;
        }

        if ($location_filter !== '') {
            $count_args['location'] = $location_filter;
        }

        if ($sector_filter !== '') {
            $count_args['sector'] = $sector_filter;
        }

        if ($status_filter !== '') {
            $count_args['post_status'] = $status_filter;
        }

        $total_posts = $post_model->get_feed_count($count_args);
        $total_pages = max(1, (int) ceil($total_posts / $per_page));
        $results_start = $total_posts ? $offset + 1 : 0;
        $results_end = min($offset + $per_page, $total_posts);

        $pagination_args = $base_args;
        if ($filter === 'pending') {
            $pagination_args['filter'] = 'pending';
        }

        $pagination_base = add_query_arg($pagination_args, admin_url('admin.php'));
        $pagination_links = '';

        if ($total_pages > 1) {
            $pagination_links = paginate_links([
                'base' => $pagination_base . '%_%',
                'format' => '&paged=%#%',
                'current' => $page,
                'total' => $total_pages,
                'prev_text' => __('« Previous', 'senna-finance'),
                'next_text' => __('Next »', 'senna-finance'),
            ]);
        }

        $all_link = add_query_arg($base_args, admin_url('admin.php'));
        $pending_link = add_query_arg(array_merge($base_args, ['filter' => 'pending']), admin_url('admin.php'));

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
        $group_model = new SFFC_CRM_Post_Group();
        $post_groups = $group_model->get_all([
            'is_active' => 1,
            'include_post_count' => false,
        ]);
        $filter_options = $post_model->get_filter_options();
        $sector_options = array_values(array_filter(array_map('strval', (array) ($filter_options['sectors'] ?? []))));
        $recruiter_suggestions = array_values(array_unique(array_filter(array_map('strval', array_merge(
            (array) ($filter_options['recruiters'] ?? []),
            (array) ($filter_options['firms'] ?? [])
        )))));
        natcasesort($recruiter_suggestions);
        $recruiter_suggestions = array_values($recruiter_suggestions);
        $status_options = [
            'open' => __('Open', 'senna-finance'),
            'closed' => __('Closed', 'senna-finance'),
        ];

        $bulk_group_notice = '';
        $bulk_group_notice_class = 'notice-success';
        $bulk_group_result = sanitize_key($_GET['bulk_group_result'] ?? '');

        if ($bulk_group_result) {
            if (in_array($bulk_group_result, ['added', 'removed'], true)) {
                $bulk_group_count = max(0, intval($_GET['bulk_group_count'] ?? 0));
                $notice_group_id = intval($_GET['bulk_group_id'] ?? 0);
                $notice_group_name = '';

                if ($notice_group_id) {
                    $notice_group = $group_model->get_by_id($notice_group_id);
                    if ($notice_group) {
                        $notice_group_name = $notice_group['name'];
                    }
                }

                $target_group_text = $notice_group_name
                    ? '"' . $notice_group_name . '"'
                    : __('the selected group', 'senna-finance');

                $template = $bulk_group_result === 'added'
                    ? __('%1$s posts added to %2$s.', 'senna-finance')
                    : __('%1$s posts removed from %2$s.', 'senna-finance');

                $bulk_group_notice = sprintf(
                    $template,
                    number_format_i18n($bulk_group_count),
                    $target_group_text
                );
            } elseif ($bulk_group_result === 'error') {
                $reason = sanitize_key($_GET['bulk_group_reason'] ?? '');
                $bulk_group_notice_class = 'notice-error';

                switch ($reason) {
                    case 'no_group':
                        $bulk_group_notice = __('Select a post group before running this action.', 'senna-finance');
                        break;
                    case 'no_posts':
                        $bulk_group_notice = __('Select at least one post before running this action.', 'senna-finance');
                        break;
                    default:
                        $bulk_group_notice = __('Bulk update could not be completed.', 'senna-finance');
                        break;
                }
            }
        }

    ?>
        <div class="wrap sffc-crm-admin">
            <h1>
                <?php esc_html_e('Manage Posts', 'senna-finance'); ?>
                <a href="<?php echo admin_url('admin.php?page=sffc-crm-add-post'); ?>" class="page-title-action">
                    <?php esc_html_e('Add New', 'senna-finance'); ?>
                </a>
            </h1>

            <?php if (!empty($bulk_group_notice)): ?>
                <div class="notice <?php echo esc_attr($bulk_group_notice_class); ?> is-dismissible">
                    <p><?php echo esc_html($bulk_group_notice); ?></p>
                </div>
            <?php endif; ?>

            <ul class="subsubsub">
                <li>
                    <a href="<?php echo esc_url($all_link); ?>" class="<?php echo esc_attr($filter === 'all' ? 'current' : ''); ?>">
                        <?php esc_html_e('All', 'senna-finance'); ?>
                    </a> |
                </li>
                <li>
                    <a href="<?php echo esc_url($pending_link); ?>" class="<?php echo esc_attr($filter === 'pending' ? 'current' : ''); ?>">
