                        <input type="search" id="sffc-crm-posts-search" name="s" class="regular-text" style="width:100%;" placeholder="<?php esc_attr_e('Search posts, company, recruiter', 'senna-finance'); ?>" value="<?php echo esc_attr($search_term); ?>">
