                        <input type="text" id="sffc-crm-posts-recruiter-filter" name="recruiter" class="regular-text" style="width:100%;" list="sffc-crm-posts-recruiter-suggestions" placeholder="<?php esc_attr_e('Recruiter or firm', 'senna-finance'); ?>" value="<?php echo esc_attr($recruiter_filter); ?>">
                        <?php if (!empty($recruiter_suggestions)): ?>
                            <datalist id="sffc-crm-posts-recruiter-suggestions">
