                                <?php $has_missing_brief_warning = $this->crm_post_content_contains_missing_brief_warning($post['content'] ?? ''); ?>
                                <tr class="<?php echo $has_missing_brief_warning ? 'sffc-crm-post-row--needs-rewrite' : ''; ?>" style="<?php echo $has_missing_brief_warning ? 'background:#fff7ed;' : ''; ?>">
