                                            <?php esc_html_e('Edit', 'senna-finance'); ?>
                                        </a>
                                        <button type="button"
                                            class="button button-small sffc-crm-archive-post"
                                            data-post-id="<?php echo esc_attr($post['id']); ?>"
                                            data-role-title="<?php echo esc_attr($post['role_title']); ?>"
                                            data-company-name="<?php echo esc_attr($post['company'] ?? ''); ?>">
