                    </tbody>
                </table>

                <?php if (!empty($pagination_links)): ?>
                    <div class="tablenav bottom">
                        <div class="tablenav-pages"><?php echo wp_kses_post($pagination_links); ?></div>
                    </div>
                <?php endif; ?>
            </form>
            <script>
                document.addEventListener('DOMContentLoaded', function() {
                    var applyButton = document.getElementById('sffc-crm-posts-per-page-apply');
                    var perPageSelect = document.getElementById('sffc-crm-posts-per-page');

                    if (!applyButton || !perPageSelect) {
                        return;
                    }

                    applyButton.addEventListener('click', function() {
                        var url = new URL(window.location.href);
                        url.searchParams.set('page', 'sffc-crm-posts');
                        url.searchParams.set('per_page', perPageSelect.value || '20');
                        url.searchParams.delete('paged');

                        var filter = applyButton.getAttribute('data-filter') || 'all';
                        var recruiterId = applyButton.getAttribute('data-recruiter-id') || '';
                        var search = applyButton.getAttribute('data-search') || '';
                        var roleTitle = applyButton.getAttribute('data-role-title') || '';
                        var recruiter = applyButton.getAttribute('data-recruiter') || '';
                        var location = applyButton.getAttribute('data-location') || '';
                        var sector = applyButton.getAttribute('data-sector') || '';
                        var status = applyButton.getAttribute('data-status') || '';

                        if (filter && filter !== 'all') {
                            url.searchParams.set('filter', filter);
                        } else {
                            url.searchParams.delete('filter');
                        }

                        if (recruiterId && recruiterId !== '0') {
                            url.searchParams.set('recruiter_id', recruiterId);
                        } else {
                            url.searchParams.delete('recruiter_id');
                        }

                        if (search) {
                            url.searchParams.set('s', search);
                        } else {
                            url.searchParams.delete('s');
                        }

                        if (roleTitle) {
                            url.searchParams.set('role_title', roleTitle);
                        } else {
                            url.searchParams.delete('role_title');
                        }

                        if (recruiter) {
                            url.searchParams.set('recruiter', recruiter);
                        } else {
                            url.searchParams.delete('recruiter');
                        }

                        if (location) {
                            url.searchParams.set('location', location);
                        } else {
                            url.searchParams.delete('location');
                        }

                        if (sector) {
                            url.searchParams.set('sector', sector);
                        } else {
                            url.searchParams.delete('sector');
                        }

                        if (status) {
                            url.searchParams.set('status', status);
                        } else {
                            url.searchParams.delete('status');
                        }

                        window.location.href = url.toString();
                    });
                });
            </script>
        </div>
    <?php
    }

    /**
     * Render groups page
     */
    public function render_groups_page()
    {
        $action = isset($_GET['action']) ? $_GET['action'] : 'list';

        if (in_array($action, ['new', 'edit'])) {
            $this->groups_admin->render_form_page();
        } else {
            $this->groups_admin->render_list_page();
        }
    }

