    public function render_campaigns_page()
    {
        global $wpdb;

        $this->ensure_linkedin_intro_queue_table();
        $this->add_campaign_request_columns();

        $status_labels = [
            'pending_review' => __('Pending review', 'senna-finance'),
            'approved' => __('Approved', 'senna-finance'),
            'sent' => __('Sent', 'senna-finance'),
            'awaiting_response' => __('Awaiting response', 'senna-finance'),
            'accepted' => __('Accepted', 'senna-finance'),
            'rejected' => __('Declined', 'senna-finance'),
            'expired' => __('Expired', 'senna-finance'),
        ];

        $save_notice = null;
        if (
            isset($_POST['sffc_crm_save_campaign_details'], $_POST['campaign_request_id'], $_POST['campaign_details_nonce'])
            && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['campaign_details_nonce'])), 'sffc_crm_save_campaign_details')
        ) {
            $request_id = absint($_POST['campaign_request_id']);
            $status = sanitize_key(wp_unslash($_POST['campaign_status'] ?? 'pending_review'));
            if (!isset($status_labels[$status])) {
                $status = 'pending_review';
            }

            $campaign_contacts = $this->sanitize_campaign_reached_recruiters($_POST['campaign_contacts'] ?? []);
            $campaign_admin_notes = sanitize_textarea_field(wp_unslash($_POST['campaign_admin_notes'] ?? ''));
            $primary_contact = $campaign_contacts[0] ?? [];

            $updated = $wpdb->update(
                $wpdb->prefix . 'sffc_crm_intro_requests',
                [
                    'status' => $status,
                    'campaign_admin_notes' => $campaign_admin_notes,
                    'reached_recruiters' => !empty($campaign_contacts) ? wp_json_encode($campaign_contacts) : null,
                    'recruiter_name' => (string) ($primary_contact['name'] ?? ''),
                    'recruiter_email' => (string) ($primary_contact['email'] ?? ''),
                    'recruiter_linkedin' => (string) ($primary_contact['linkedin'] ?? ''),
                    'company_name' => (string) (($primary_contact['company'] ?? '') !== '' ? $primary_contact['company'] : (wp_unslash($_POST['existing_company_name'] ?? ''))),
                    'updated_at' => current_time('mysql'),
                ],
                ['id' => $request_id],
                ['%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s'],
                ['%d']
            );

            $save_notice = $updated === false
                ? ['type' => 'error', 'message' => __('Unable to save campaign outreach details.', 'senna-finance')]
                : ['type' => 'success', 'message' => __('Campaign outreach details updated.', 'senna-finance')];
        }

        $requests = $wpdb->get_results(
            "SELECT ir.*, u.display_name, u.user_email
             FROM {$wpdb->prefix}sffc_crm_intro_requests ir
             LEFT JOIN {$wpdb->users} u ON u.ID = ir.user_id
             WHERE ir.request_type = 'campaign'
             ORDER BY ir.created_at DESC
             LIMIT 300",
            ARRAY_A
        );
    ?>
        <div class="wrap sffc-crm-admin">
            <h1><?php esc_html_e('Intro Campaigns', 'senna-finance'); ?></h1>
            <p><?php esc_html_e('Campaign briefs submitted from the Intros tab in the Finance Career Guidance are stored here for admin review and manual follow-up.', 'senna-finance'); ?></p>

            <?php if ($save_notice) : ?>
                <div class="notice notice-<?php echo esc_attr($save_notice['type']); ?> is-dismissible"><p><?php echo esc_html($save_notice['message']); ?></p></div>
            <?php endif; ?>

            <table class="wp-list-table widefat fixed striped">
                <thead>
                    <tr>
                        <th><?php esc_html_e('Candidate', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Campaign brief', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Stored CV', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Additional information', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Requested', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Status', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Recruiters reached', 'senna-finance'); ?></th>
                    </tr>
                </thead>
                <tbody>
                    <?php if (empty($requests)) : ?>
                        <tr>
                            <td colspan="7"><?php esc_html_e('No intro campaigns submitted yet.', 'senna-finance'); ?></td>
                        </tr>
                    <?php else : ?>
                        <?php foreach ($requests as $request) : ?>
                            <?php
                            $candidate_name = trim((string) ($request['display_name'] ?? ''));
                            if ($candidate_name === '') {
                                $candidate_name = sprintf(__('User #%d', 'senna-finance'), (int) ($request['user_id'] ?? 0));
                            }
                            $brief_bits = array_values(array_filter([
                                (string) ($request['target_role'] ?? ''),
                                (string) ($request['target_location'] ?? ''),
                                (string) ($request['target_seniority'] ?? ''),
                            ]));
                            $company_bits = array_values(array_filter([
                                (string) ($request['target_company'] ?? ''),
                                (string) ($request['target_sector'] ?? ''),
                            ]));
                            $stored_cv_url = trim((string) ($request['stored_cv_url'] ?? ''));
                            $stored_cv_label = trim((string) ($request['stored_cv_name'] ?? ''));
                            if ($stored_cv_label === '') {
                                $stored_cv_label = $stored_cv_url !== '' ? __('Open CV', 'senna-finance') : __('No CV attached', 'senna-finance');
                            }
                            $status_label = $status_labels[$request['status'] ?? 'pending_review'] ?? ucfirst(str_replace('_', ' ', (string) ($request['status'] ?? 'pending_review')));
                            $campaign_contacts = $this->parse_campaign_reached_recruiters((string) ($request['reached_recruiters'] ?? ''));
                            $contact_rows = max(3, count($campaign_contacts) + 1);
                            ?>
                            <tr>
                                <td>
                                    <strong><?php echo esc_html($candidate_name); ?></strong>
                                    <br><span class="description"><?php echo esc_html((string) ($request['user_email'] ?? '')); ?></span>
                                </td>
                                <td>
                                    <strong><?php echo esc_html(implode(' · ', $brief_bits)); ?></strong>
                                    <?php if (!empty($company_bits)) : ?>
                                        <br><span class="description"><?php echo esc_html(implode(' · ', $company_bits)); ?></span>
                                    <?php endif; ?>
                                </td>
                                <td>
                                    <?php if ($stored_cv_url !== '') : ?>
                                        <a href="<?php echo esc_url($stored_cv_url); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html($stored_cv_label); ?></a>
                                    <?php else : ?>
                                        <span class="description"><?php echo esc_html($stored_cv_label); ?></span>
                                    <?php endif; ?>
                                </td>
                                <td>
                                    <?php
                                    $context = trim((string) ($request['intro_context'] ?? ''));
