                                            <select name="campaign_status" style="width:100%;max-width:240px;">
                                                <?php foreach ($status_labels as $status_key => $status_option_label) : ?>
                                                    <option value="<?php echo esc_attr($status_key); ?>"<?php selected((string) ($request['status'] ?? 'pending_review'), $status_key); ?>><?php echo esc_html($status_option_label); ?></option>
                                                <?php endforeach; ?>
                                            </select>
                                        </p>

                                        <?php for ($i = 0; $i < $contact_rows; $i++) : ?>
                                            <?php $contact = $campaign_contacts[$i] ?? []; ?>
