                                                    <input type="url" name="campaign_contacts[<?php echo esc_attr((string) $i); ?>][avatar_url]" value="<?php echo esc_attr((string) ($contact['avatar_url'] ?? '')); ?>" placeholder="<?php esc_attr_e('Avatar URL', 'senna-finance'); ?>">
                                                    <input type="text" name="campaign_contacts[<?php echo esc_attr((string) $i); ?>][sent_at]" value="<?php echo esc_attr((string) ($contact['sent_at'] ?? '')); ?>" placeholder="<?php esc_attr_e('Outreach sent date / time', 'senna-finance'); ?>">
                                                    <input type="text" name="campaign_contacts[<?php echo esc_attr((string) $i); ?>][message_subject]" value="<?php echo esc_attr((string) ($contact['message_subject'] ?? '')); ?>" placeholder="<?php esc_attr_e('Email subject', 'senna-finance'); ?>">
