    }

    public function render_contact_capture_page()
    {
        if (!current_user_can('manage_options')) {
            return;
        }

        // Handle database table activation
        if (isset($_POST['sffc_activate_user_criteria_tables']) && wp_verify_nonce($_POST['database_activation_nonce'], 'sffc_activate_database_tables')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            require_once(ABSPATH . 'wp-admin/includes/upgrade.php');

            $schema = new SFFC_CRM_Database_Schema();
            $schema->create_tables();

            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('User Criteria Groups table activated successfully!', 'senna-finance') . '</p></div>';
        }

        // Handle settings save
        if (isset($_POST['sffc_save_contact_capture_settings']) && wp_verify_nonce($_POST['contact_capture_settings_nonce'], 'sffc_save_contact_capture_settings')) {
            update_option('sffc_contact_capture_redirect_url', sanitize_text_field($_POST['redirect_url'] ?? '/memberships/'));
            update_option('sffc_contact_capture_button_text', sanitize_text_field($_POST['button_text'] ?? 'Get Started'));
            update_option('sffc_contact_capture_button_color', sanitize_hex_color($_POST['button_color'] ?? '#0d353e'));
            update_option('sffc_contact_capture_field_border_color', sanitize_hex_color($_POST['field_border_color'] ?? '#E5E7EB'));

            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Settings saved successfully.', 'senna-finance') . '</p></div>';
        }

        // Get current settings
        $redirect_url = get_option('sffc_contact_capture_redirect_url', '/memberships/');
        $button_text = get_option('sffc_contact_capture_button_text', 'Get Started');
        $button_color = get_option('sffc_contact_capture_button_color', '#0d353e');
        $field_border_color = get_option('sffc_contact_capture_field_border_color', '#E5E7EB');

        // Get contacts list
        global $wpdb;
        $table_name = $wpdb->prefix . 'sffc_contact_capture';
        $contacts = [];
        $table_exists = $wpdb->get_var("SHOW TABLES LIKE '{$table_name}'") === $table_name;

        if ($table_exists) {
            $contacts = $wpdb->get_results("SELECT * FROM {$table_name} ORDER BY created_at DESC LIMIT 100");
        }

    ?>
        <div class="wrap">
            <h1><?php esc_html_e('CRM Settings', 'senna-finance'); ?></h1>

            <!-- Database Tables Section -->
            <h2><?php esc_html_e('Database Tables', 'senna-finance'); ?></h2>
            <p><?php esc_html_e('Activate or update database tables for new CRM features.', 'senna-finance'); ?></p>

            <?php
            global $wpdb;
            $user_criteria_table = $wpdb->prefix . 'sffc_crm_user_criteria_groups';
            $criteria_table_exists = $wpdb->get_var("SHOW TABLES LIKE '{$user_criteria_table}'") === $user_criteria_table;
            ?>

            <form method="post" action="" style="margin-bottom: 30px;">
                <?php wp_nonce_field('sffc_activate_database_tables', 'database_activation_nonce'); ?>
                <table class="form-table">
                    <tr>
                        <th scope="row">
                            <?php esc_html_e('User Criteria Groups', 'senna-finance'); ?>
                        </th>
                        <td>
                            <p>
