    public function render_hr_outreach_page()
    {
        if (!current_user_can('manage_options')) {
            return;
        }

        wp_enqueue_media();

        $model = new SFFC_CRM_HR_Outreach();
        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-contact-group.php';
        $contact_group_model = new SFFC_CRM_HR_Contact_Group();
        $contact_groups = $contact_group_model->get_all([
            'is_active' => null,
            'include_contact_count' => true,
        ]);
        $per_page = 20;
        $page = max(1, intval($_GET['paged'] ?? 1));
        $offset = ($page - 1) * $per_page;
        $hr_search_term = isset($_GET['sffc_hr_search']) ? sanitize_text_field(wp_unslash($_GET['sffc_hr_search'])) : '';
        $entries = $model->get_all([
            'limit' => $per_page,
            'offset' => $offset,
            'search' => $hr_search_term,
        ]);
        $total_entries = $model->count_all([
            'search' => $hr_search_term,
        ]);
        $results_start = $total_entries ? $offset + 1 : 0;
        $results_end = min($offset + $per_page, $total_entries);
        $total_pages = max(1, (int) ceil($total_entries / $per_page));
        $pagination_links = '';

        if ($total_pages > 1) {
            $page_url_args = ['page' => 'sffc-crm-hr-outreach'];
            if ($hr_search_term !== '') {
                $page_url_args['sffc_hr_search'] = $hr_search_term;
            }
            $page_url = add_query_arg($page_url_args, admin_url('admin.php'));
            $pagination_links = paginate_links([
                'base' => $page_url . '%_%',
                'format' => '&paged=%#%',
                'current' => $page,
                'total' => $total_pages,
                'prev_text' => __('« Previous', 'senna-finance'),
                'next_text' => __('Next »', 'senna-finance'),
            ]);
        }

        $edit_id = isset($_GET['id']) ? intval($_GET['id']) : 0;
        $editing_entry = $edit_id ? $model->get($edit_id) : null;
        $selected_contact_group_ids = $edit_id
            ? array_map('intval', wp_list_pluck($contact_group_model->get_groups_for_contact($edit_id), 'id'))
            : [];
        $team_contacts = $editing_entry['team_contacts'] ?? [];
        $program_types = $editing_entry['program_types'] ?? [];
        $industry = $editing_entry['industry'] ?? [];
        $process = $editing_entry['process'] ?? [];
        $skills = $editing_entry['skills'] ?? [];
        $default_skill_options = [
            'financial_analysis' => __('Financial Analysis', 'senna-finance'),
            'equity_research' => __('Equity Research', 'senna-finance'),
