                echo $template; ?>
            </script>

            <script>
                jQuery(function($) {
                    var teamTemplate = $('#sffc-hr-team-contact-template').html();
                    $('#sffc-add-team-contact').on('click', function(e) {
                        e.preventDefault();
                        var index = $('#sffc-hr-team-contacts .sffc-hr-team-card').length;
                        var html = teamTemplate.replace(/__index__/g, index);
                        $('#sffc-hr-team-contacts').append(html);
                    });

                    $(document).on('click', '.sffc-remove-team-contact', function(e) {
                        e.preventDefault();
                        if ($('#sffc-hr-team-contacts .sffc-hr-team-card').length === 1) {
                            $(this).closest('.sffc-hr-team-card').find('input').val('');
                            return;
                        }
                        $(this).closest('.sffc-hr-team-card').remove();
                    });

                    function setupMediaButton(buttonId, targetInput, previewSelector) {
                        var frame;
                        $(document).on('click', buttonId, function(e) {
                            e.preventDefault();
                            if (frame) {
                                frame.open();
                                return;
                            }
                            frame = wp.media({
                                title: '<?php esc_attr_e('Select Image', 'senna-finance'); ?>',
                                button: {
                                    text: '<?php esc_attr_e('Use this image', 'senna-finance'); ?>'
                                },
                                multiple: false
                            });
                            frame.on('select', function() {
                                var attachment = frame.state().get('selection').first().toJSON();
                                $(targetInput).val(attachment.url).trigger('change');
                                if (previewSelector) {
                                    $(previewSelector).html('<img src="' + attachment.url + '" alt="preview">');
                                }
                            });
                            frame.open();
                        });
                    }

                    setupMediaButton('#hr-upload-company-logo', '#hr_company_logo', '#hr-company-logo-preview');
                    setupMediaButton('#hr-upload-contact-photo', '#hr_contact_photo', '#hr-contact-photo-preview');

                    $('#hr-clear-company-logo').on('click', function(e) {
                        e.preventDefault();
                        $('#hr_company_logo').val('');
                        $('#hr-company-logo-preview').html('<span><?php echo esc_js(__('Logo Preview', 'senna-finance')); ?></span>');
                    });

                    $('#hr-clear-contact-photo').on('click', function(e) {
                        e.preventDefault();
                        $('#hr_contact_photo').val('');
                        $('#hr-contact-photo-preview').html('<span><?php echo esc_js(__('Photo Preview', 'senna-finance')); ?></span>');
                    });

                    $(document).on('change', '#hr_company_logo', function() {
                        var url = $(this).val();
                        if (url) {
                            $('#hr-company-logo-preview').html('<img src="' + url + '" alt="preview">');
                        }
                    });
                    $(document).on('change', '#hr_contact_photo', function() {
                        var url = $(this).val();
                        if (url) {
                            $('#hr-contact-photo-preview').html('<img src="' + url + '" alt="preview">');
                        }
                    });

                    initHrSkills();

                    function initHrSkills() {
                        var $blocks = $('[data-hr-skills]');
                        if (!$blocks.length) {
                            return;
                        }

                        $blocks.each(function() {
                            var $block = $(this);
                            var $pills = $block.find('[data-hr-skills-pills]');
                            var $input = $block.find('[data-hr-skills-input]');
                            var $hidden = $block.find('[data-hr-skills-hidden]');
                            var $menu = $block.find('[data-hr-skills-menu]');
                            var optionsRaw = $block.attr('data-hr-skill-options') || '{}';
                            var optionLabels = {};
                            try {
                                optionLabels = JSON.parse(optionsRaw) || {};
                            } catch (err) {}

                            function slugify(label) {
                                return label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
                            }

                            function formatLabel(slug, fallback) {
                                if (optionLabels.hasOwnProperty(slug)) {
                                    return optionLabels[slug];
                                }
                                var text = fallback || slug;
                                return text.replace(/[_-]+/g, ' ').replace(/\b\w/g, function(chr) {
                                    return chr.toUpperCase();
                                });
                            }

                            function currentValues() {
                                return $pills.find('.sffc-hr-skill-pill').map(function() {
                                    return $(this).data('value');
                                }).get();
                            }

                            function syncHidden() {
                                $hidden.val(currentValues().join(','));
                            }

                            function addSkill(rawValue, isPreset) {
                                var labelSource = (rawValue || '').trim();
                                if (!labelSource) {
                                    return;
                                }
                                var slug = isPreset ? rawValue : slugify(labelSource);
                                if (!slug) {
                                    return;
                                }
                                var existing = currentValues();
                                if (existing.indexOf(slug) !== -1) {
                                    $input.val('');
                                    return;
                                }
                                var labelText = formatLabel(slug, labelSource);
                                var pill = $('<span class="sffc-hr-skill-pill" data-value="' + slug + '">' + labelText + '<button type="button" class="sffc-hr-skill-remove" aria-label="<?php echo esc_js(__('Remove skill', 'senna-finance')); ?>">&times;</button></span>');
                                $pills.append(pill);
                                syncHidden();
                                $input.val('');
                            }

                            $pills.on('click', '.sffc-hr-skill-remove', function(e) {
                                e.preventDefault();
                                $(this).closest('.sffc-hr-skill-pill').remove();
                                syncHidden();
                            });

                            $input.on('keydown', function(e) {
                                if (e.key === 'Enter' || e.key === ',') {
                                    e.preventDefault();
                                    addSkill($(this).val(), false);
                                }
                            });

                            $input.on('blur', function() {
                                addSkill($(this).val(), false);
                            });

                            $menu.on('click', '[data-skill-value]', function(e) {
                                e.preventDefault();
                                var val = $(this).data('skillValue');
                                addSkill(val, true);
                            });

                            syncHidden();
                        });
                    }
                });
            </script>

            <style>
