    public function render_company_prep_page()
    {
        if (!current_user_can('manage_options')) {
            wp_die(__('Access denied', 'senna-finance'));
        }

        wp_enqueue_media();

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-company-prep.php';
        $model = new SFFC_CRM_Company_Prep();

        $action = isset($_GET['action']) ? sanitize_text_field($_GET['action']) : 'list';
        $company_id = isset($_GET['id']) ? intval($_GET['id']) : 0;

        if (in_array($action, ['edit', 'new', 'requests', 'library', 'qa'], true) && !$this->company_prep_admin) {
            wp_die(__('Company Prep module is unavailable. Please reinstall the CRM Company Prep helper.', 'senna-finance'));
        }

        // Handle form submission
        if (($action === 'edit' || $action === 'new') && $this->company_prep_admin) {
            $company = $company_id ? $model->get($company_id) : null;
            $this->company_prep_admin->render_form($company);
            return;
        }

        // Handle requests view
        if ($action === 'requests' && $this->company_prep_admin) {
            $this->company_prep_admin->render_requests();
            return;
        }

        if ($action === 'library' && $this->company_prep_admin) {
            $this->company_prep_admin->render_library();
            return;
        }

        if ($action === 'qa' && $this->company_prep_admin) {
            $this->company_prep_admin->render_expert_qa_page();
            return;
        }

        // List view
        $companies = $model->get_all();
        $requests = $model->get_requests(['status' => 'pending']);
        $pending_count = count($requests);

    ?>
