            <?php if (isset($_GET['deleted'])): ?>
                <div class="notice notice-success is-dismissible">
                    <p><?php esc_html_e('Company deleted successfully!', 'senna-finance'); ?></p>
                </div>
            <?php endif; ?>

            <ul class="subsubsub">
                <li>
                    <a href="<?php echo admin_url('admin.php?page=sffc-crm-company-prep'); ?>" class="<?php echo $action === 'list' ? 'current' : ''; ?>">
                        <?php esc_html_e('All Companies', 'senna-finance'); ?>
                    </a> |
                </li>
                <li>
                    <a href="<?php echo admin_url('admin.php?page=sffc-crm-company-prep&action=requests'); ?>" class="<?php echo $action === 'requests' ? 'current' : ''; ?>">
                        <?php esc_html_e('Requests', 'senna-finance'); ?>
