    public function render_newsletters_page()
    {
        if (!current_user_can('manage_options')) {
            wp_die(__('Access denied', 'senna-finance'));
        }

        wp_enqueue_media();

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_newsletters';
        $subscriptions_table = $wpdb->prefix . 'sffc_crm_newsletter_subscriptions';
        $table_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;
        $subscriptions_table_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $subscriptions_table)) === $subscriptions_table;
        $action = isset($_GET['action']) ? sanitize_key($_GET['action']) : 'list';
        $newsletter_id = isset($_GET['id']) ? absint($_GET['id']) : 0;
        $newsletter = null;

        if ($table_exists && $newsletter_id) {
            $newsletter = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $newsletter_id), ARRAY_A);
        }

        if (in_array($action, ['new', 'edit'], true)) {
            $this->render_newsletter_form($newsletter);
            return;
        }

        $newsletters = ($table_exists && $subscriptions_table_exists) ? $wpdb->get_results(
            "SELECT n.*, COUNT(CASE WHEN s.status = 'subscribed' THEN 1 END) AS subscriber_count
             FROM {$table} n
             LEFT JOIN {$subscriptions_table} s ON s.newsletter_id = n.id
             GROUP BY n.id
             ORDER BY n.display_order ASC, n.title ASC",
            ARRAY_A
        ) : ($table_exists ? $wpdb->get_results(
            "SELECT *, 0 AS subscriber_count
             FROM {$table}
             ORDER BY display_order ASC, title ASC",
            ARRAY_A
        ) : []);
    ?>
        <div class="wrap sffc-crm-admin">
            <h1>
                <?php esc_html_e('Newsletters', 'senna-finance'); ?>
                <a href="<?php echo esc_url(admin_url('admin.php?page=sffc-crm-newsletters&action=new')); ?>" class="page-title-action">
                    <?php esc_html_e('Add Newsletter', 'senna-finance'); ?>
                </a>
            </h1>

            <?php if (!$table_exists || !$subscriptions_table_exists): ?>
                <div class="notice notice-warning">
                    <p><?php esc_html_e('Newsletter tables are missing. Run Update Database Schema in CRM Settings before editing newsletters.', 'senna-finance'); ?></p>
                </div>
            <?php endif; ?>

            <?php if (isset($_GET['created']) || isset($_GET['updated']) || isset($_GET['deleted'])): ?>
                <div class="notice notice-success is-dismissible">
                    <p><?php esc_html_e('Newsletter settings updated.', 'senna-finance'); ?></p>
                </div>
            <?php endif; ?>

            <table class="wp-list-table widefat fixed striped">
                <thead>
                    <tr>
                        <th><?php esc_html_e('Newsletter', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Frequency', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Subscribers', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Status', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Actions', 'senna-finance'); ?></th>
                    </tr>
                </thead>
                <tbody>
                    <?php if (empty($newsletters)): ?>
                        <tr>
                            <td colspan="5"><?php esc_html_e('No newsletters created yet.', 'senna-finance'); ?></td>
                        </tr>
                    <?php else: ?>
                        <?php foreach ($newsletters as $item): ?>
                            <?php
                            $edit_url = admin_url('admin.php?page=sffc-crm-newsletters&action=edit&id=' . absint($item['id']));
                            $delete_url = wp_nonce_url(admin_url('admin.php?page=sffc-crm-newsletters&action=delete_newsletter&id=' . absint($item['id'])), 'sffc_crm_delete_newsletter_' . absint($item['id']));
                            ?>
                            <tr>
                                <td>
                                    <strong><?php echo esc_html($item['title']); ?></strong>
                                    <p class="description"><?php echo esc_html(wp_trim_words((string) ($item['description'] ?? ''), 18)); ?></p>
                                </td>
                                <td><?php echo esc_html((string) ($item['frequency'] ?? '')); ?></td>
                                <td><?php echo esc_html((string) (int) ($item['subscriber_count'] ?? 0)); ?></td>
                                <td><?php echo !empty($item['is_active']) ? esc_html__('Active', 'senna-finance') : esc_html__('Hidden', 'senna-finance'); ?></td>
                                <td>
                                    <a href="<?php echo esc_url($edit_url); ?>"><?php esc_html_e('Edit', 'senna-finance'); ?></a>
                                    |
                                    <a href="<?php echo esc_url($delete_url); ?>" onclick="return confirm('<?php echo esc_js(__('Delete this newsletter?', 'senna-finance')); ?>');"><?php esc_html_e('Delete', 'senna-finance'); ?></a>
                                </td>
                            </tr>
                        <?php endforeach; ?>
                    <?php endif; ?>
                </tbody>
            </table>
        </div>
    <?php
