    /**
     * Render Application Materials delivery page
     */
    public function render_materials_page()
    {
        if (!current_user_can('manage_options')) {
            wp_die(__('You do not have permission to access this page.'));
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_intro_requests';

        // Handle material delivery
        if (isset($_POST['deliver_material']) && check_admin_referer('deliver_material')) {
            $app_id = absint($_POST['app_id']);
            $material_type = sanitize_key($_POST['material_type']);
            $material_url = esc_url_raw($_POST['material_url']);

            $update_data = ['materials_status' => 'delivered'];
            if ($material_type === 'cover_letter') {
                $update_data['cover_letter_url'] = $material_url;
            } elseif ($material_type === 'resume') {
                $update_data['resume_url'] = $material_url;
            }

            $wpdb->update($table, $update_data, ['id' => $app_id]);
            echo '<div class="notice notice-success"><p>Material delivered successfully!</p></div>';
        }

        // Get all applications with material requests
        $applications = $wpdb->get_results("
            SELECT * FROM {$table}
            WHERE status = 'applied'
            ORDER BY created_at DESC
        ", ARRAY_A);

    ?>
        <div class="wrap">
            <h1><?php esc_html_e('Application Materials', 'senna-finance'); ?></h1>
            <p><?php esc_html_e('Upload and deliver materials to users who expressed interest in roles.', 'senna-finance'); ?></p>

            <table class="wp-list-table widefat fixed striped">
                <thead>
                    <tr>
                        <th><?php esc_html_e('User', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Role', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Company', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Applied', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Materials Status', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Actions', 'senna-finance'); ?></th>
                    </tr>
                </thead>
                <tbody>
                    <?php if (empty($applications)): ?>
                        <tr>
                            <td colspan="6"><?php esc_html_e('No applications found.', 'senna-finance'); ?></td>
                        </tr>
                    <?php else: ?>
                        <?php foreach ($applications as $app): ?>
                            <?php
                            $user = get_userdata($app['user_id']);
                            $user_name = $user ? $user->display_name : 'User #' . $app['user_id'];
                            $user_email = $user ? $user->user_email : '';
                            ?>
                            <tr>
                                <td>
                                    <strong><?php echo esc_html($user_name); ?></strong><br>
                                    <small><?php echo esc_html($user_email); ?></small>
                                </td>
                                <td><?php echo esc_html($app['role_title']); ?></td>
                                <td><?php echo esc_html($app['company_name']); ?></td>
                                <td><?php echo esc_html(wp_date(get_option('date_format'), strtotime($app['created_at']))); ?></td>
                                <td>
                                    <?php
                                    $status = $app['materials_status'] ?? 'not_requested';
                                    $status_colors = [
                                        'not_requested' => '#999',
                                        'pending' => '#f59e0b',
                                        'delivered' => '#22c55e'
                                    ];
                                    $color = $status_colors[$status] ?? '#999';
                                    ?>
                                    <span style="color: <?php echo $color; ?>; font-weight: 600;">
                                        <?php echo esc_html(ucfirst(str_replace('_', ' ', $status))); ?>
                                    </span>
                                </td>
                                <td>
                                    <button type="button" class="button button-small" onclick="openMaterialForm(<?php echo $app['id']; ?>, '<?php echo esc_js($user_name); ?>', '<?php echo esc_js($app['role_title']); ?>')">
                                        <?php esc_html_e('Deliver Materials', 'senna-finance'); ?>
                                    </button>
                                </td>
                            </tr>
                        <?php endforeach; ?>
                    <?php endif; ?>
                </tbody>
            </table>
        </div>

        <!-- Material Delivery Modal -->
        <div id="materialDeliveryModal" style="display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 100000;">
            <div style="max-width: 500px; margin: 100px auto; background: #fff; padding: 30px; border-radius: 8px;">
                <h2><?php esc_html_e('Deliver Materials', 'senna-finance'); ?></h2>
                <form method="post">
                    <?php wp_nonce_field('deliver_material'); ?>
                    <input type="hidden" name="app_id" id="deliveryAppId">

                    <p><strong id="deliveryUserName"></strong> - <span id="deliveryRoleTitle"></span></p>

                    <p>
                        <label>
                            <?php esc_html_e('Material Type:', 'senna-finance'); ?><br>
                            <select name="material_type" required style="width: 100%; padding: 8px;">
                                <option value="cover_letter"><?php esc_html_e('Cover Letter', 'senna-finance'); ?></option>
                                <option value="resume"><?php esc_html_e('Tailored Resume', 'senna-finance'); ?></option>
                            </select>
                        </label>
                    </p>

                    <p>
                        <label>
                            <?php esc_html_e('Material URL (upload to Media Library first):', 'senna-finance'); ?><br>
                            <input type="url" name="material_url" required style="width: 100%; padding: 8px;">
                        </label>
                    </p>

                    <p>
                        <button type="submit" name="deliver_material" class="button button-primary">
                            <?php esc_html_e('Deliver', 'senna-finance'); ?>
                        </button>
                        <button type="button" class="button" onclick="closeMaterialForm()">
                            <?php esc_html_e('Cancel', 'senna-finance'); ?>
                        </button>
                    </p>
                </form>
            </div>
        </div>

        <script>
            function openMaterialForm(appId, userName, roleTitle) {
                document.getElementById('deliveryAppId').value = appId;
                document.getElementById('deliveryUserName').textContent = userName;
                document.getElementById('deliveryRoleTitle').textContent = roleTitle;
                document.getElementById('materialDeliveryModal').style.display = 'block';
            }

            function closeMaterialForm() {
                document.getElementById('materialDeliveryModal').style.display = 'none';
            }
        </script>
    <?php
    }

    public function render_application_packs_page()
    {
        if (!current_user_can('manage_options')) {
            wp_die(__('Access denied', 'senna-finance'));
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_application_packs';
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($table))) === $table;
        if (!$table_exists) {
            echo '<div class="wrap"><h1>' . esc_html__('Application Packs', 'senna-finance') . '</h1><div class="notice notice-warning"><p>' . esc_html__('Application Pack table is missing. Create it from MENA Careers Recruiter Outreach -> Settings before using this section.', 'senna-finance') . '</p></div></div>';
            return;
        }

        $requests = $wpdb->get_results("SELECT * FROM {$table} ORDER BY created_at DESC, id DESC LIMIT 200", ARRAY_A);
        $status_labels = [
            'requested' => __('Requested', 'senna-finance'),
            'preparing' => __('Preparing', 'senna-finance'),
            'delivered' => __('Delivered', 'senna-finance'),
            'cancelled' => __('Cancelled', 'senna-finance'),
        ];
    ?>
        <div class="wrap">
            <h1><?php esc_html_e('Application Packs', 'senna-finance'); ?></h1>
            <p><?php esc_html_e('Review role-specific application pack requests from the recruiter console.', 'senna-finance'); ?></p>

            <table class="wp-list-table widefat fixed striped">
                <thead>
                    <tr>
                        <th><?php esc_html_e('Candidate', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Role', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Company', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Recruiter', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Pack Items', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Status', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Requested', 'senna-finance'); ?></th>
                    </tr>
                </thead>
                <tbody>
                    <?php if (empty($requests)): ?>
                        <tr>
                            <td colspan="7"><?php esc_html_e('No application pack requests yet.', 'senna-finance'); ?></td>
                        </tr>
                    <?php else: ?>
                        <?php foreach ($requests as $request): ?>
                            <?php
                            $items = json_decode($request['pack_items'] ?? '[]', true);
                            if (!is_array($items)) {
                                $items = [];
                            }
                            ?>
                            <tr>
                                <td>
                                    <strong><?php echo esc_html($request['user_name'] ?: __('Guest User', 'senna-finance')); ?></strong><br>
                                    <small><?php echo esc_html($request['user_email']); ?></small>
                                </td>
                                <td><?php echo esc_html($request['role_title']); ?></td>
                                <td><?php echo esc_html($request['company_name']); ?></td>
                                <td>
                                    <?php echo esc_html($request['recruiter_name'] ?: __('Hiring Team', 'senna-finance')); ?><br>
                                    <small><?php echo esc_html($request['recruiter_email']); ?></small>
                                </td>
                                <td><?php echo esc_html(implode(', ', $items)); ?></td>
                                <td><strong><?php echo esc_html($status_labels[$request['status']] ?? ucfirst((string) $request['status'])); ?></strong></td>
                                <td><?php echo esc_html(!empty($request['created_at']) ? wp_date(get_option('date_format') . ' ' . get_option('time_format'), strtotime($request['created_at'])) : ''); ?></td>
                            </tr>
                        <?php endforeach; ?>
                    <?php endif; ?>
                </tbody>
            </table>
        </div>
    <?php
    }

    /**
     * Render Applicants log
     */
    public function render_applicants_page()
    {
        if (!current_user_can('manage_options')) {
            wp_die(__('Access denied', 'senna-finance'));
        }

        $applicant_model = new SFFC_CRM_Applicant();
        $search = isset($_GET['s']) ? sanitize_text_field(wp_unslash($_GET['s'])) : '';
        $paged = isset($_GET['paged']) ? max(1, intval($_GET['paged'])) : 1;
        $per_page = 25;

        $args = [
            'paged' => $paged,
            'per_page' => $per_page,
            'search' => $search,
        ];

        $applicants = $applicant_model->get_applicants($args);
        $total = $applicant_model->count_applicants($args);
        $total_pages = max(1, ceil($total / $per_page));

        $base_url = admin_url('admin.php?page=sffc-crm-applicants');
        if ($search) {
            $base_url = add_query_arg('s', rawurlencode($search), $base_url);
        }

    ?>
        <div class="wrap sffc-crm-admin">
            <h1><?php esc_html_e('Applicants', 'senna-finance'); ?></h1>

            <form method="get" class="sffc-crm-search-form">
                <input type="hidden" name="page" value="sffc-crm-applicants" />
                <p class="search-box">
                    <label class="screen-reader-text" for="applicant-search-input"><?php esc_html_e('Search applicants', 'senna-finance'); ?></label>
                    <input type="search" id="applicant-search-input" name="s" value="<?php echo esc_attr($search); ?>" />
                    <input type="submit" class="button" value="<?php esc_attr_e('Search Applicants', 'senna-finance'); ?>">
                </p>
            </form>

            <table class="wp-list-table widefat fixed striped">
                <thead>
                    <tr>
                        <th><?php esc_html_e('Applicant', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Role & Company', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Source', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Recruiter ID', 'senna-finance'); ?></th>
                        <th><?php esc_html_e('Captured', 'senna-finance'); ?></th>
                    </tr>
                </thead>
                <tbody>
                    <?php if (empty($applicants)) : ?>
                        <tr>
                            <td colspan="5"><?php esc_html_e('No applicants logged yet.', 'senna-finance'); ?></td>
                        </tr>
                    <?php else : ?>
                        <?php foreach ($applicants as $applicant) :
                            $materials = !empty($applicant['materials']) ? json_decode($applicant['materials'], true) : [];
                        ?>
                            <tr>
                                <td>
                                    <strong><?php echo esc_html(trim($applicant['first_name'] . ' ' . $applicant['last_name'])); ?></strong>
                                    <br>
                                    <a href="mailto:<?php echo esc_attr($applicant['email']); ?>" class="description"><?php echo esc_html($applicant['email']); ?></a>
                                    <?php if (!empty($materials)) : ?>
                                        <br><span class="description"><?php echo esc_html(implode(', ', $materials)); ?></span>
                                    <?php endif; ?>
                                </td>
                                <td>
                                    <strong><?php echo esc_html($applicant['job_title'] ?: __('Unknown Role', 'senna-finance')); ?></strong>
                                    <?php if (!empty($applicant['company'])) : ?>
                                        <br><span class="description"><?php echo esc_html($applicant['company']); ?></span>
                                    <?php endif; ?>
                                </td>
                                <td>
                                    <?php echo esc_html(ucfirst($applicant['source'] ?: 'web')); ?>
                                </td>
                                <td>
                                    <?php echo $applicant['recruiter_id'] ? esc_html($applicant['recruiter_id']) : '&mdash;'; ?>
                                </td>
                                <td>
                                    <?php echo esc_html(date_i18n(get_option('date_format') . ' ' . get_option('time_format'), strtotime($applicant['created_at']))); ?>
                                </td>
                            </tr>
                        <?php endforeach; ?>
                    <?php endif; ?>
                </tbody>
            </table>

            <?php
            $pagination = paginate_links([
                'base' => esc_url_raw(add_query_arg('paged', '%#%', $base_url)),
                'format' => '',
                'current' => $paged,
                'total' => $total_pages,
                'prev_text' => __('&laquo;', 'senna-finance'),
                'next_text' => __('&raquo;', 'senna-finance'),
            ]);

            if ($pagination) {
                echo '<div class="tablenav"><div class="tablenav-pages">' . wp_kses_post($pagination) . '</div></div>';
            }
            ?>
        </div>
    <?php
    }

    public function render_applications_page()
    {
        if (!current_user_can('manage_options')) {
            wp_die(__('Access denied', 'senna-finance'));
        }

        $this->ensure_job_applications_table();
        $this->handle_application_tracking_posts();

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_job_applications';
        $search = isset($_GET['s']) ? sanitize_text_field(wp_unslash($_GET['s'])) : '';
        $workflow_filter = isset($_GET['workflow_type']) ? sanitize_key(wp_unslash($_GET['workflow_type'])) : '';
        $stage_filter = isset($_GET['stage']) ? sanitize_key(wp_unslash($_GET['stage'])) : '';
        $user_filter = isset($_GET['user_id']) ? absint($_GET['user_id']) : 0;
        $recruiter_filter = isset($_GET['recruiter_id']) ? absint($_GET['recruiter_id']) : 0;
        $view = isset($_GET['view']) ? sanitize_key(wp_unslash($_GET['view'])) : '';
        $edit_application_id = isset($_GET['application_id']) ? absint($_GET['application_id']) : 0;
        $duplicate_application_id = isset($_GET['duplicate_application_id']) ? absint($_GET['duplicate_application_id']) : 0;
        $paged = isset($_GET['paged']) ? max(1, intval($_GET['paged'])) : 1;
        $per_page = 25;
        $offset = ($paged - 1) * $per_page;

        $where_sql = '1=1';
        $where_params = [];
        if ($search !== '') {
            $like = '%' . $wpdb->esc_like($search) . '%';
            $where_sql .= " AND (job_title LIKE %s OR company_name LIKE %s OR recruiter_name LIKE %s OR recruiter_email LIKE %s)";
            $where_params = [$like, $like, $like, $like];
        }
        $workflow_options = $this->get_application_admin_workflow_options();
        if ($workflow_filter !== '' && isset($workflow_options[$workflow_filter])) {
            $where_sql .= ' AND workflow_type = %s';
            $where_params[] = $workflow_filter;
        }

        $status_options = $this->get_application_admin_status_options();
        if ($stage_filter !== '' && isset($status_options[$stage_filter])) {
            $where_sql .= ' AND stage = %s';
            $where_params[] = $stage_filter;
        }

        if ($user_filter > 0) {
            $where_sql .= ' AND user_id = %d';
            $where_params[] = $user_filter;
        }

        if ($recruiter_filter > 0) {
            $where_sql .= ' AND recruiter_id = %d';
            $where_params[] = $recruiter_filter;
        }

        $total_sql = "SELECT COUNT(*) FROM {$table} WHERE {$where_sql}";
        $items_sql = "SELECT ja.*, u.display_name, u.user_email
            FROM {$table} ja
            LEFT JOIN {$wpdb->users} u ON u.ID = ja.user_id
            WHERE {$where_sql}
            ORDER BY ja.applied_date DESC, ja.id DESC
            LIMIT %d OFFSET %d";

        $total = (int) $wpdb->get_var(!empty($where_params) ? $wpdb->prepare($total_sql, ...$where_params) : $total_sql);
        $query_params = array_merge($where_params, [$per_page, $offset]);
        $applications = $wpdb->get_results($wpdb->prepare($items_sql, ...$query_params), ARRAY_A) ?: [];
        $total_pages = max(1, (int) ceil($total / $per_page));

        $summary_rows = $wpdb->get_results(
            "SELECT workflow_type, stage, COUNT(*) AS total
             FROM {$table}
             GROUP BY workflow_type, stage",
            ARRAY_A
        ) ?: [];
        $total_intro = 0;
        $total_application = 0;
        $queued_total = 0;
        $submitted_total = 0;
        foreach ($summary_rows as $summary_row) {
            $summary_workflow = sanitize_key((string) ($summary_row['workflow_type'] ?? 'application'));
            $summary_stage = sanitize_key((string) ($summary_row['stage'] ?? 'queued'));
            $summary_total = (int) ($summary_row['total'] ?? 0);
            if ($summary_workflow === 'send_intro') {
                $total_intro += $summary_total;
            } else {
                $total_application += $summary_total;
            }
            if (in_array($summary_stage, ['queued', 'pending_review', 'preparing', 'approved'], true)) {
                $queued_total += $summary_total;
            }
            if (in_array($summary_stage, ['submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted'], true)) {
                $submitted_total += $summary_total;
            }
        }

        $base_url = admin_url('admin.php?page=sffc-crm-applications');
        $preserved_args = [];
        if ($search !== '') {
            $preserved_args['s'] = $search;
        }
        if ($workflow_filter !== '') {
            $preserved_args['workflow_type'] = $workflow_filter;
        }
        if ($stage_filter !== '') {
            $preserved_args['stage'] = $stage_filter;
        }
        if ($user_filter > 0) {
            $preserved_args['user_id'] = $user_filter;
        }
        if ($recruiter_filter > 0) {
            $preserved_args['recruiter_id'] = $recruiter_filter;
        }
        if (!empty($preserved_args)) {
            $base_url = add_query_arg($preserved_args, $base_url);
        }

        $users_for_dropdown = $this->get_application_admin_users_for_dropdown();
        $posts_for_dropdown = $this->get_application_admin_posts_for_dropdown();
        $recruiters_for_dropdown = $this->get_application_admin_hr_outreach_dropdown();

        $editing_record = [];
        if ($edit_application_id > 0) {
            $editing_record = $this->get_application_admin_record($edit_application_id);
        } elseif ($duplicate_application_id > 0) {
            $editing_record = $this->get_application_admin_record($duplicate_application_id);
            unset($editing_record['id']);
        }
        $show_editor = in_array($view, ['new', 'edit'], true) || !empty($editing_record);
        $editor_defaults = $this->get_application_admin_form_defaults($editing_record);
        $notice = sanitize_key((string) ($_GET['crm_notice'] ?? ''));
        $form_heading = $edit_application_id > 0
            ? __('Edit Application Record', 'senna-finance')
            : ($duplicate_application_id > 0 ? __('Duplicate Application Record', 'senna-finance') : __('Add New Application or Intro', 'senna-finance'));
    ?>
        <div class="wrap sffc-crm-admin">
            <h1><?php esc_html_e('Applications', 'senna-finance'); ?></h1>
            <p style="max-width:980px; color:#475569; margin-top:8px;">
                <?php esc_html_e('Manage both smart applications and recruiter intros from one backend queue. Create records on behalf of members, attach documents, preserve recruiter and post snapshots, and track user-visible delivery states in one place.', 'senna-finance'); ?>
            </p>

            <?php if ($notice === 'saved') : ?>
                <div class="notice notice-success is-dismissible"><p><?php esc_html_e('Application record saved.', 'senna-finance'); ?></p></div>
            <?php elseif ($notice === 'deleted') : ?>
                <div class="notice notice-success is-dismissible"><p><?php esc_html_e('Application record deleted.', 'senna-finance'); ?></p></div>
            <?php elseif ($notice === 'bulk-updated') : ?>
                <div class="notice notice-success is-dismissible"><p><?php esc_html_e('Selected application records updated.', 'senna-finance'); ?></p></div>
            <?php elseif ($notice === 'not-found') : ?>
