        <script>
            document.addEventListener('DOMContentLoaded', function() {
                var selectAll = document.getElementById('sffc-crm-applications-select-all');
                if (selectAll) {
                    selectAll.addEventListener('change', function() {
                        document.querySelectorAll('input[name="application_ids[]"][form="sffc-crm-applications-bulk-form"]').forEach(function(input) {
                            input.checked = selectAll.checked;
                        });
                    });
                }

                var userSelect = document.getElementById('crm-application-user');
                var postSelect = document.getElementById('crm-application-post');
                var recruiterSelect = document.getElementById('crm-application-recruiter');
                var workflowSelect = document.getElementById('crm-application-workflow');
                var sourceActionSelect = document.getElementById('crm-application-source-action');

                var setFieldValue = function(id, value) {
                    var field = document.getElementById(id);
                    if (!field || typeof value === 'undefined' || value === null || value === '') {
                        return;
                    }
                    field.value = value;
                };

                var syncSourceAction = function() {
                    if (!workflowSelect || !sourceActionSelect) {
                        return;
                    }

                    var currentValue = sourceActionSelect.value || '';
                    var applicationDefaults = ['admin_application', 'admin_send_intro'];
                    if (applicationDefaults.indexOf(currentValue) === -1) {
                        return;
                    }

                    sourceActionSelect.value = workflowSelect.value === 'send_intro' ? 'admin_send_intro' : 'admin_application';
                };

                if (postSelect) {
                    postSelect.addEventListener('change', function() {
                        var option = postSelect.options[postSelect.selectedIndex];
                        if (!option) {
                            return;
                        }

                        setFieldValue('crm-application-role', option.dataset.roleTitle || '');
                        setFieldValue('crm-application-company', option.dataset.companyName || '');
                        setFieldValue('crm-application-location', option.dataset.location || '');
                        setFieldValue('crm-application-url', option.dataset.applicationUrl || option.dataset.sourceUrl || '');
                    });
                }

                if (userSelect) {
                    userSelect.addEventListener('change', function() {
                        var option = userSelect.options[userSelect.selectedIndex];
                        if (!option) {
                            return;
                        }

                        var storedCvUrl = option.dataset.storedCvUrl || '';
                        var storedCvName = option.dataset.storedCvName || '';
                        setFieldValue('crm-application-stored-cv-url', storedCvUrl);
                        setFieldValue('crm-application-stored-cv-name', storedCvName);
                        setFieldValue('crm-application-resume-url', storedCvUrl);
                    });
                }

                if (recruiterSelect) {
                    recruiterSelect.addEventListener('change', function() {
                        var option = recruiterSelect.options[recruiterSelect.selectedIndex];
                        if (!option) {
                            return;
                        }

                        setFieldValue('crm-application-recruiter-name', option.dataset.name || '');
                        setFieldValue('crm-application-recruiter-title', option.dataset.title || '');
                        setFieldValue('crm-application-recruiter-email', option.dataset.email || '');
                        setFieldValue('crm-application-recruiter-linkedin', option.dataset.linkedin || '');
                        setFieldValue('crm-application-recruiter-avatar', option.dataset.avatarUrl || '');
                        setFieldValue('crm-application-recruiter-location', option.dataset.location || '');
                        setFieldValue('crm-application-recruiter-regions', option.dataset.regions || '');
                        setFieldValue('crm-application-company', option.dataset.companyName || '');
                    });
                }

                if (workflowSelect) {
                    workflowSelect.addEventListener('change', syncSourceAction);
                }
            });
        </script>
    <?php
    }

    private function ensure_job_applications_table()
    {
        global $wpdb;

        $table_name = $wpdb->prefix . 'sffc_job_applications';
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name;
        if ($table_exists) {
            $this->ensure_job_applications_table_columns();
            $this->ensure_job_applications_table_indexes();
            return;
        }

        $charset_collate = $wpdb->get_charset_collate();
        $sql = "CREATE TABLE {$table_name} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            job_id bigint(20) NOT NULL,
            source_post_id bigint(20) DEFAULT 0,
            workflow_type varchar(50) DEFAULT 'application',
            stage varchar(50) NOT NULL DEFAULT 'applied',
            applied_date datetime DEFAULT CURRENT_TIMESTAMP,
            stage_updated datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP,
            notes text,
            source varchar(100),
            source_action varchar(100) DEFAULT NULL,
            company_name varchar(200),
            job_title varchar(200),
            location varchar(200),
            recruiter_id bigint(20) DEFAULT 0,
            recruiter_name varchar(255) DEFAULT NULL,
            recruiter_title varchar(255) DEFAULT NULL,
            recruiter_email varchar(255) DEFAULT NULL,
            recruiter_linkedin text DEFAULT NULL,
            recruiter_avatar_url text DEFAULT NULL,
            recruiter_location varchar(255) DEFAULT NULL,
            recruiter_regions text DEFAULT NULL,
            stored_cv_url text DEFAULT NULL,
            stored_cv_name varchar(255) DEFAULT NULL,
            message_subject text DEFAULT NULL,
            message_body longtext DEFAULT NULL,
            attachment_urls longtext DEFAULT NULL,
            application_url text DEFAULT NULL,
            submitted_at datetime DEFAULT NULL,
            confirmation_sent_at datetime DEFAULT NULL,
            resume_sent_at datetime DEFAULT NULL,
            cover_letter_sent_at datetime DEFAULT NULL,
            resume_url text DEFAULT NULL,
            cover_letter_url text DEFAULT NULL,
            admin_message longtext DEFAULT NULL,
            post_snapshot longtext DEFAULT NULL,
            recruiter_snapshot longtext DEFAULT NULL,
            salary_min int(11),
            salary_max int(11),
            PRIMARY KEY (id),
            KEY idx_user (user_id),
            KEY idx_job (job_id),
            KEY idx_stage (stage),
            KEY idx_workflow_type (workflow_type),
            KEY idx_date (applied_date),
            UNIQUE KEY unique_user_job_workflow_recruiter (user_id, job_id, workflow_type, recruiter_id)
        ) {$charset_collate};";

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';
        dbDelta($sql);
        $this->ensure_job_applications_table_columns();
        $this->ensure_job_applications_table_indexes();
    }

    private function ensure_intro_request_application_columns()
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_intro_requests';

        $columns_to_add = [
            'tracking_status' => "ADD COLUMN `tracking_status` varchar(50) DEFAULT 'queued'",
            'materials_status' => "ADD COLUMN `materials_status` varchar(50) DEFAULT 'not_requested'",
            'resume_url' => "ADD COLUMN `resume_url` text DEFAULT NULL",
            'cover_letter_url' => "ADD COLUMN `cover_letter_url` text DEFAULT NULL",
            'submitted_at' => "ADD COLUMN `submitted_at` datetime DEFAULT NULL",
            'confirmation_sent_at' => "ADD COLUMN `confirmation_sent_at` datetime DEFAULT NULL",
            'resume_sent_at' => "ADD COLUMN `resume_sent_at` datetime DEFAULT NULL",
            'cover_letter_sent_at' => "ADD COLUMN `cover_letter_sent_at` datetime DEFAULT NULL",
        ];

        foreach ($columns_to_add as $column_name => $alter_sql) {
            $column_exists = $wpdb->get_results($wpdb->prepare(
                "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                 WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s",
                DB_NAME,
                $table,
                $column_name
            ));

            if (empty($column_exists)) {
                $wpdb->query("ALTER TABLE `{$table}` {$alter_sql}");
            }
        }
    }

    private function handle_application_tracking_posts()
    {
        if (!current_user_can('manage_options')) {
            return;
        }

        if (isset($_POST['sffc_crm_delete_application_record']) && wp_verify_nonce($_POST['crm_application_delete_nonce'] ?? '', 'sffc_crm_delete_application_record')) {
            global $wpdb;
            $this->ensure_job_applications_table();
            $application_id = absint($_POST['application_id'] ?? 0);
            if ($application_id > 0) {
                $wpdb->delete($wpdb->prefix . 'sffc_job_applications', ['id' => $application_id], ['%d']);
            }
            wp_safe_redirect($this->get_application_admin_redirect_url(['crm_notice' => 'deleted']));
            exit;
        }

        if (isset($_POST['sffc_crm_save_application_record']) && wp_verify_nonce($_POST['crm_application_record_nonce'] ?? '', 'sffc_crm_save_application_record')) {
            global $wpdb;
            $this->ensure_job_applications_table();

            $application_id = absint($_POST['application_id'] ?? 0);
            $user_id = absint($_POST['user_id'] ?? 0);
            $source_post_id = absint($_POST['source_post_id'] ?? 0);
            $workflow_type = sanitize_key($_POST['workflow_type'] ?? 'application');
            if (!in_array($workflow_type, ['application', 'send_intro'], true)) {
                $workflow_type = 'application';
            }

            $allowed_statuses = array_keys($this->get_application_admin_status_options());
            $stage = sanitize_key($_POST['stage'] ?? 'queued');
            if (!in_array($stage, $allowed_statuses, true)) {
                $stage = 'queued';
            }

            $source_action = sanitize_key($_POST['source_action'] ?? ($workflow_type === 'send_intro' ? 'admin_send_intro' : 'admin_application'));
            $job_title = sanitize_text_field($_POST['job_title'] ?? '');
            $company_name = sanitize_text_field($_POST['company_name'] ?? '');
            $location = sanitize_text_field($_POST['location'] ?? '');
            $application_url = esc_url_raw($_POST['application_url'] ?? '');
            $recruiter_id = absint($_POST['recruiter_id'] ?? 0);
            $recruiter_name = sanitize_text_field($_POST['recruiter_name'] ?? '');
            $recruiter_title = sanitize_text_field($_POST['recruiter_title'] ?? '');
            $recruiter_email = sanitize_email($_POST['recruiter_email'] ?? '');
            $recruiter_linkedin = esc_url_raw($_POST['recruiter_linkedin'] ?? '');
            $recruiter_avatar_url = esc_url_raw($_POST['recruiter_avatar_url'] ?? '');
            $recruiter_location = sanitize_text_field($_POST['recruiter_location'] ?? '');
            $recruiter_regions = sanitize_text_field($_POST['recruiter_regions'] ?? '');
            $stored_cv_url = esc_url_raw($_POST['stored_cv_url'] ?? '');
            $stored_cv_name = sanitize_text_field($_POST['stored_cv_name'] ?? '');
            $resume_url = esc_url_raw($_POST['resume_url'] ?? '');
            $cover_letter_url = esc_url_raw($_POST['cover_letter_url'] ?? '');
            $message_subject = sanitize_text_field($_POST['message_subject'] ?? '');
            $message_body = sanitize_textarea_field($_POST['message_body'] ?? '');
            $notes = sanitize_textarea_field($_POST['notes'] ?? '');
            $admin_message = sanitize_textarea_field($_POST['admin_message'] ?? '');
            $attachment_urls = trim((string) wp_unslash($_POST['attachment_urls'] ?? ''));
            $salary_min = isset($_POST['salary_min']) && $_POST['salary_min'] !== '' ? (int) $_POST['salary_min'] : null;
            $salary_max = isset($_POST['salary_max']) && $_POST['salary_max'] !== '' ? (int) $_POST['salary_max'] : null;
            $submitted_at_raw = sanitize_text_field($_POST['submitted_at'] ?? '');
            $submitted_at = $submitted_at_raw !== '' ? gmdate('Y-m-d H:i:s', strtotime($submitted_at_raw)) : null;
            $now = current_time('mysql');

            if ($user_id <= 0 || $job_title === '' || $company_name === '') {
                wp_safe_redirect($this->get_application_admin_redirect_url([
                    'crm_notice' => 'not-found',
                    'view' => $application_id > 0 ? 'edit' : 'new',
                    'application_id' => $application_id > 0 ? $application_id : null,
                ]));
                exit;
            }

            $post_snapshot = $this->build_application_admin_post_snapshot($source_post_id, [
                'role_title' => $job_title,
                'company_name' => $company_name,
                'location' => $location,
                'application_url' => $application_url,
            ]);
            $recruiter_snapshot = $this->build_application_admin_recruiter_snapshot($recruiter_id, [
                'name' => $recruiter_name,
                'title' => $recruiter_title,
                'company_name' => $company_name,
                'email' => $recruiter_email,
                'linkedin' => $recruiter_linkedin,
                'avatar_url' => $recruiter_avatar_url,
                'location' => $recruiter_location,
                'regions' => $recruiter_regions,
            ]);

            $job_title = trim((string) ($post_snapshot['role_title'] ?? '')) ?: $job_title;
            $company_name = trim((string) ($recruiter_snapshot['company_name'] ?? '')) ?: (trim((string) ($post_snapshot['company_name'] ?? '')) ?: $company_name);
            $location = trim((string) ($post_snapshot['location'] ?? '')) ?: $location;
            $recruiter_name = trim((string) ($recruiter_snapshot['name'] ?? '')) ?: $recruiter_name;
            $recruiter_title = trim((string) ($recruiter_snapshot['title'] ?? '')) ?: $recruiter_title;
            $recruiter_email = sanitize_email((string) ($recruiter_snapshot['email'] ?? '')) ?: $recruiter_email;
            $recruiter_linkedin = esc_url_raw((string) ($recruiter_snapshot['linkedin'] ?? '')) ?: $recruiter_linkedin;
            $recruiter_avatar_url = esc_url_raw((string) ($recruiter_snapshot['avatar_url'] ?? '')) ?: $recruiter_avatar_url;
            $recruiter_location = trim((string) ($recruiter_snapshot['location'] ?? '')) ?: $recruiter_location;
            $recruiter_regions = trim((string) ($recruiter_snapshot['regions'] ?? '')) ?: $recruiter_regions;
            $application_url = esc_url_raw((string) ($post_snapshot['application_url'] ?? '')) ?: $application_url;

            $job_id = $source_post_id > 0 ? $source_post_id : 0;
            if ($workflow_type === 'send_intro') {
                $job_id = $this->get_send_intro_application_job_id_admin($source_post_id, $recruiter_id, $source_action);
            } elseif ($job_id <= 0) {
                $job_id = 800000000 + abs((int) sprintf('%u', crc32(implode('|', [$job_title, $company_name, $location, $workflow_type]))));
            }

            $existing = null;
            if ($application_id > 0) {
                $existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sffc_job_applications WHERE id = %d", $application_id), ARRAY_A);
                if (!$existing) {
                    wp_safe_redirect($this->get_application_admin_redirect_url(['crm_notice' => 'not-found']));
                    exit;
                }
            }

            $row = [
                'user_id' => $user_id,
                'job_id' => $job_id,
                'source_post_id' => $source_post_id,
                'workflow_type' => $workflow_type,
                'stage' => $stage,
                'applied_date' => $submitted_at ?: ($existing['applied_date'] ?? $now),
                'updated_at' => $now,
                'notes' => $notes,
                'source' => 'admin',
                'source_action' => $source_action,
                'company_name' => $company_name,
                'job_title' => $job_title,
                'location' => $location,
                'recruiter_id' => $recruiter_id,
                'recruiter_name' => $recruiter_name,
                'recruiter_title' => $recruiter_title,
                'recruiter_email' => $recruiter_email,
                'recruiter_linkedin' => $recruiter_linkedin,
                'recruiter_avatar_url' => $recruiter_avatar_url,
                'recruiter_location' => $recruiter_location,
                'recruiter_regions' => $recruiter_regions,
                'stored_cv_url' => $stored_cv_url,
                'stored_cv_name' => $stored_cv_name,
                'message_subject' => $message_subject,
                'message_body' => $message_body,
                'attachment_urls' => $attachment_urls,
                'application_url' => $application_url,
                'submitted_at' => $submitted_at,
                'resume_url' => $resume_url,
                'cover_letter_url' => $cover_letter_url,
                'admin_message' => $admin_message,
                'post_snapshot' => wp_json_encode($post_snapshot),
                'recruiter_snapshot' => wp_json_encode($recruiter_snapshot),
                'salary_min' => $salary_min,
                'salary_max' => $salary_max,
                'confirmation_sent_at' => !empty($_POST['confirmation_sent']) ? ($existing['confirmation_sent_at'] ?? $now) : null,
                'resume_sent_at' => !empty($_POST['resume_sent']) ? ($existing['resume_sent_at'] ?? $now) : null,
                'cover_letter_sent_at' => !empty($_POST['cover_letter_sent']) ? ($existing['cover_letter_sent_at'] ?? $now) : null,
            ];

            if ($existing) {
                $save_result = $wpdb->update($wpdb->prefix . 'sffc_job_applications', $row, ['id' => $application_id]);
                $saved_id = $application_id;
            } else {
                $matched_existing_id = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT id FROM {$wpdb->prefix}sffc_job_applications
                     WHERE user_id = %d AND job_id = %d AND workflow_type = %s AND recruiter_id = %d
                     ORDER BY id DESC LIMIT 1",
                    $user_id,
                    $job_id,
                    $workflow_type,
                    $recruiter_id
                ));

                if ($matched_existing_id > 0) {
                    $save_result = $wpdb->update($wpdb->prefix . 'sffc_job_applications', $row, ['id' => $matched_existing_id]);
                    $saved_id = $matched_existing_id;
                } else {
                    $row['created_at'] = $now;
                    $save_result = $wpdb->insert($wpdb->prefix . 'sffc_job_applications', $row);
                    $saved_id = (int) $wpdb->insert_id;
                }
            }

            if ($save_result === false || $saved_id <= 0) {
                wp_safe_redirect($this->get_application_admin_redirect_url([
                    'crm_notice' => 'not-found',
                    'view' => $application_id > 0 ? 'edit' : 'new',
                    'application_id' => $application_id > 0 ? $application_id : null,
                ]));
                exit;
            }

            wp_safe_redirect($this->get_application_admin_redirect_url([
                'crm_notice' => 'saved',
                'view' => 'edit',
                'application_id' => $saved_id,
            ]));
            exit;
        }

        if (isset($_POST['sffc_crm_bulk_update_applications']) && wp_verify_nonce($_POST['crm_application_bulk_nonce'] ?? '', 'sffc_crm_bulk_update_applications')) {
            global $wpdb;
            $this->ensure_job_applications_table();

            $table = $wpdb->prefix . 'sffc_job_applications';
            $application_ids = array_values(array_filter(array_map('absint', (array) ($_POST['application_ids'] ?? []))));
            $bulk_status = sanitize_key($_POST['bulk_application_status'] ?? '');
            $bulk_comment = sanitize_textarea_field($_POST['bulk_admin_message'] ?? '');
            $allowed_statuses = ['queued', 'pending_review', 'preparing', 'approved', 'submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted', 'rejected', 'expired', 'cancelled'];
            $now = current_time('mysql');
            $updated_count = 0;

            if (!empty($application_ids)) {
                foreach ($application_ids as $application_id) {
                    $existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $application_id), ARRAY_A);
                    if (!$existing) {
                        continue;
                    }

                    $update_data = ['updated_at' => $now];
                    if ($bulk_status && in_array($bulk_status, $allowed_statuses, true)) {
                        $update_data['stage'] = $bulk_status;
                        if (in_array($bulk_status, ['submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted', 'rejected'], true) && empty($existing['submitted_at'])) {
                            $update_data['submitted_at'] = $now;
                        }
                    }
                    if (!empty($_POST['bulk_confirmation_sent']) && empty($existing['confirmation_sent_at'])) {
                        $update_data['confirmation_sent_at'] = $now;
                    }
                    if (!empty($_POST['bulk_resume_sent']) && empty($existing['resume_sent_at'])) {
                        $update_data['resume_sent_at'] = $now;
                    }
                    if (!empty($_POST['bulk_cover_letter_sent']) && empty($existing['cover_letter_sent_at'])) {
                        $update_data['cover_letter_sent_at'] = $now;
                    }
                    if ($bulk_comment !== '') {
                        $update_data['admin_message'] = $bulk_comment;
                    }

                    if (count($update_data) > 1 && $wpdb->update($table, $update_data, ['id' => $application_id]) !== false) {
                        $updated_count++;
                    }
                }
            }

            wp_safe_redirect($this->get_application_admin_redirect_url([
                'crm_notice' => $updated_count > 0 ? 'bulk-updated' : null,
            ]));
            exit;
        }
    }

