    private function ensure_job_applications_table_indexes()
    {
        global $wpdb;

        $table = $wpdb->prefix . 'sffc_job_applications';
        $indexes = $wpdb->get_results("SHOW INDEX FROM `{$table}`", ARRAY_A) ?: [];
        $index_names = [];
        foreach ($indexes as $index) {
            $index_names[(string) ($index['Key_name'] ?? '')] = true;
        }

        if (!empty($index_names['unique_user_job']) && empty($index_names['unique_user_job_workflow_recruiter'])) {
            $wpdb->query("ALTER TABLE `{$table}` DROP INDEX `unique_user_job`");
            $index_names['unique_user_job'] = false;
        }

        if (empty($index_names['unique_user_job_workflow_recruiter'])) {
            $wpdb->query("ALTER TABLE `{$table}` ADD UNIQUE KEY `unique_user_job_workflow_recruiter` (`user_id`, `job_id`, `workflow_type`, `recruiter_id`)");
        }
    }

    private function get_application_admin_redirect_url(array $extra_args = [])
    {
        $args = ['page' => 'sffc-crm-applications'];
        foreach (['s', 'workflow_type', 'stage', 'user_id', 'recruiter_id', 'paged'] as $key) {
            if (!isset($_REQUEST[$key])) {
                continue;
            }
            $value = wp_unslash($_REQUEST[$key]);
            if ($value === '' || $value === '0') {
                continue;
            }
            $args[$key] = is_scalar($value) ? $value : '';
        }

        foreach ($extra_args as $key => $value) {
            if ($value === null || $value === '') {
                continue;
            }
            $args[$key] = $value;
        }

        return add_query_arg($args, admin_url('admin.php'));
    }

