    private function get_application_admin_users_for_dropdown()
    {
        $users = get_users([
            'orderby' => 'display_name',
            'order' => 'ASC',
            'number' => 250,
            'fields' => ['ID', 'display_name', 'user_email'],
        ]);

        return array_map(static function ($user) {
            $documents = get_user_meta((int) $user->ID, 'sffc_crm_documents', true);
            $stored_cv_url = '';
            $stored_cv_name = '';
            if (is_array($documents) && !empty($documents)) {
                $documents = array_reverse($documents);
                foreach ($documents as $document) {
                    if (!is_array($document)) {
                        continue;
                    }
                    if (($document['document_type'] ?? '') === 'resume_cv' && !empty($document['url'])) {
                        $stored_cv_url = esc_url_raw((string) ($document['url'] ?? ''));
                        $stored_cv_name = sanitize_text_field((string) ($document['name'] ?? ''));
                        break;
                    }
                }
            }

            return [
                'ID' => (int) $user->ID,
                'display_name' => (string) $user->display_name,
                'user_email' => (string) $user->user_email,
                'stored_cv_url' => $stored_cv_url,
                'stored_cv_name' => $stored_cv_name,
            ];
        }, (array) $users);
    }

