    private function build_application_admin_post_snapshot($post_id, array $overrides = [])
    {
        global $wpdb;

        $snapshot = [
            'crm_post_id' => (int) $post_id,
            'role_title' => trim((string) ($overrides['role_title'] ?? '')),
            'company_name' => trim((string) ($overrides['company_name'] ?? '')),
            'location' => trim((string) ($overrides['location'] ?? '')),
            'application_url' => esc_url_raw((string) ($overrides['application_url'] ?? '')),
            'source_url' => '',
        ];

        $post_id = (int) $post_id;
        if ($post_id <= 0) {
            return $snapshot;
        }

        $table = $wpdb->prefix . 'sffc_crm_posts';
        $post = $wpdb->get_row(
            $wpdb->prepare("SELECT id, role_title, company, location, location_city, location_country, application_url, source_url FROM {$table} WHERE id = %d LIMIT 1", $post_id),
            ARRAY_A
        );

        if (!$post) {
            return $snapshot;
        }

        $snapshot['role_title'] = trim((string) ($post['role_title'] ?? '')) ?: $snapshot['role_title'];
        $snapshot['company_name'] = trim((string) ($post['company'] ?? '')) ?: $snapshot['company_name'];
        $snapshot['location'] = trim((string) ($post['location'] ?? ''));
        if ($snapshot['location'] === '') {
            $snapshot['location'] = trim(implode(', ', array_filter([
                trim((string) ($post['location_city'] ?? '')),
                trim((string) ($post['location_country'] ?? '')),
            ])));
        }
        $snapshot['application_url'] = esc_url_raw((string) ($post['application_url'] ?? '')) ?: $snapshot['application_url'];
        $snapshot['source_url'] = esc_url_raw((string) ($post['source_url'] ?? ''));

        return $snapshot;
    }

