    private function format_application_admin_datetime_local($value)
    {
        $value = trim((string) $value);
        if ($value === '') {
            return '';
        }

        $timestamp = strtotime($value);
        if (!$timestamp) {
            return '';
        }

        return wp_date('Y-m-d\TH:i', $timestamp);
    }

    private function get_send_intro_application_job_id_admin($crm_post_id, $recruiter_id, $source_action)
    {
        $seed = implode('|', [
            (int) $crm_post_id,
            (int) $recruiter_id,
            sanitize_key((string) $source_action),
            'send_intro',
        ]);

        return 700000000 + abs((int) sprintf('%u', crc32($seed)));
    }

    private function repair_application_tracker_columns()
    {
        $this->ensure_linkedin_intro_queue_table();

        $queue_result = $this->add_application_queue_columns();
        $message_result = $this->add_intro_request_columns();
        $materials_result = $this->add_application_materials_columns();

        return [
            'added' => array_values(array_unique(array_merge(
                $queue_result['added'] ?? [],
                $message_result['added'] ?? [],
                $materials_result['added'] ?? []
            ))),
            'errors' => array_values(array_unique(array_merge(
                $queue_result['errors'] ?? [],
                $message_result['errors'] ?? [],
                $materials_result['errors'] ?? []
            ))),
        ];
    }

    private function add_application_materials_columns()
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_intro_requests';

        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
        if (!$table_exists) {
            return [
                'added' => [],
                'errors' => [__('Application tracker table does not exist.', 'senna-finance')],
            ];
        }

        $columns_to_add = [
            'tracking_status' => "ALTER TABLE `{$table}` ADD COLUMN `tracking_status` varchar(50) DEFAULT 'queued'",
            'materials_requested' => "ALTER TABLE `{$table}` ADD COLUMN `materials_requested` text DEFAULT NULL",
            'materials_status' => "ALTER TABLE `{$table}` ADD COLUMN `materials_status` varchar(50) DEFAULT 'not_requested'",
            'cover_letter_url' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_url` text DEFAULT NULL",
            'resume_url' => "ALTER TABLE `{$table}` ADD COLUMN `resume_url` text DEFAULT NULL",
            'email_template' => "ALTER TABLE `{$table}` ADD COLUMN `email_template` text DEFAULT NULL",
            'confirmation_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `confirmation_sent_at` datetime DEFAULT NULL",
            'resume_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `resume_sent_at` datetime DEFAULT NULL",
            'cover_letter_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_sent_at` datetime DEFAULT NULL",
        ];

        $added = [];
        $errors = [];
        $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");

        foreach ($columns_to_add as $column_name => $sql) {
            if (in_array($column_name, $existing_columns, true)) {
                continue;
            }

            $result = $wpdb->query($sql);
            if ($result === false) {
                $errors[] = $column_name . ': ' . $wpdb->last_error;
                continue;
            }

            $added[] = $column_name;
            $existing_columns[] = $column_name;
        }

        return [
            'added' => $added,
            'errors' => $errors,
        ];
    }

