    private function get_recruiters_for_admin_dropdown()
    {
        global $wpdb;

        $cache_key = 'sffc_crm_admin_recruiter_dropdown_v1';
        $cached = wp_cache_get($cache_key, 'sffc_crm');
        if (is_array($cached)) {
            return $cached;
        }

        $recruiters = get_transient($cache_key);
        if (is_array($recruiters)) {
            wp_cache_set($cache_key, $recruiters, 'sffc_crm', 5 * MINUTE_IN_SECONDS);
            return $recruiters;
        }

        $recruiters = $wpdb->get_results(
            "SELECT id, name, title, firm, photo_url, email, phone, linkedin_url, default_company, default_company_logo
             FROM {$wpdb->prefix}sffc_crm_recruiters
             ORDER BY name",
            ARRAY_A
        ) ?: [];

        set_transient($cache_key, $recruiters, 5 * MINUTE_IN_SECONDS);
        wp_cache_set($cache_key, $recruiters, 'sffc_crm', 5 * MINUTE_IN_SECONDS);

        return $recruiters;
    }

