                        <script>
                            (function() {
                                document.addEventListener('click', function(event) {
                                    var button = event.target.closest('.sffc-crm-copy-share-link');
                                    if (!button) {
                                        return;
                                    }

                                    var target = document.getElementById(button.getAttribute('data-copy-target'));
                                    if (!target) {
                                        return;
                                    }

                                    target.select();
                                    target.setSelectionRange(0, target.value.length);

                                    function markCopied() {
                                        var original = button.textContent;
                                        button.textContent = '<?php echo esc_js(__('Copied', 'senna-finance')); ?>';
                                        setTimeout(function() {
                                            button.textContent = original;
                                        }, 1400);
                                    }

                                    if (navigator.clipboard && navigator.clipboard.writeText) {
                                        navigator.clipboard.writeText(target.value).then(markCopied).catch(function() {
                                            document.execCommand('copy');
                                            markCopied();
                                        });
                                    } else {
                                        document.execCommand('copy');
                                        markCopied();
                                    }
                                });
                            })();
                        </script>
