                    <?php foreach ($display_knockout_questions as $index => $question):
                        $question_id = !empty($question['id']) ? sanitize_key($question['id']) : sanitize_key('ko_' . uniqid());
                        $question_prompt = isset($question['prompt']) ? $question['prompt'] : ($question['question'] ?? '');
                        $question_prompt = is_string($question_prompt) ? $question_prompt : '';
                        $question_type = isset($question['type']) ? $question['type'] : 'yes_no';
                        $question_type = array_key_exists($question_type, $knockout_types) ? $question_type : 'yes_no';
                        $question_ideal = isset($question['ideal_answer']) ? $question['ideal_answer'] : ($question['desired_response'] ?? '');
                        $question_helper = isset($question['helper_text']) ? $question['helper_text'] : '';
                        $question_weight = isset($question['weight']) ? intval($question['weight']) : 1;
                        $question_weight = max(1, min(5, $question_weight));
                        $question_modes = isset($question['modes']) && is_array($question['modes']) ? $question['modes'] : ['recruiter'];
                        $question_options = '';
                        if (!empty($question['options'])) {
                            if (is_array($question['options'])) {
                                $question_options = implode(', ', array_filter(array_map('trim', $question['options'])));
                            } elseif (is_string($question['options'])) {
                                $question_options = $question['options'];
                            }
