                                <span class="sffc-crm-duration-detection-hint__badge" id="sffc-crm-duration-detection-badge"></span>
                                <span class="sffc-crm-duration-detection-hint__text" id="sffc-crm-duration-detection-text"></span>
                            </div>
                        </td>
                    </tr>
                </table>

                <p class="submit">
                    <button type="submit" name="crm_save_post" class="button button-primary button-large">
                        <?php echo $post_id ? esc_html__('Update Post', 'senna-finance') : esc_html__('Create Post', 'senna-finance'); ?>
                    </button>
                </p>
            </form>
        </div>

        <script>
            jQuery(document).ready(function($) {
                var frame;
                var companyLogoFrame;
                var $companyLogoInput = $('#company_logo');
                var $companyLogoPreview = $('.sffc-crm-company-logo-preview');

                $(document).on('click', '.sffc-crm-preset-button', function(e) {
                    e.preventDefault();

                    var field = String($(this).data('targetField') || '').trim();
                    var value = String($(this).data('targetValue') || '').trim();
                    var $target = field ? $('#' + field) : $();

                    if (!$target.length || !value) {
                        return;
                    }

                    $target.val(value).trigger('change');
                    $(this).closest('.sffc-crm-preset-buttons').find('.sffc-crm-preset-button').removeClass('button-primary').addClass('button');
                    $(this).removeClass('button').addClass('button-primary');
                });

                function renderCompanyLogoPreview(url) {
                    if (!$companyLogoPreview.length) {
                        return;
                    }

                    if (url) {
                        $companyLogoPreview.html('<img src="' + url + '" style="width:100%;height:100%;object-fit:contain;" alt="<?php esc_attr_e('Company logo preview', 'senna-finance'); ?>">');
                    } else {
                        $companyLogoPreview.html('<span style="font-size:12px;color:#94a3b8;text-align:center;padding:4px;display:block;">' + '<?php echo esc_js(__('No logo', 'senna-finance')); ?>' + '</span>');
                    }
                }

                function setCompanyLogo(url) {
                    $companyLogoInput.val(url || '');
                    renderCompanyLogoPreview(url || '');
                }

                function buildApplicationMailto(rawValue) {
                    var value = String(rawValue || '').trim();
                    var roleTitle = String($('#role_title').val() || '').trim();
                    var email = '';
                    var questionIndex;
                    var emailMatch;

                    if (!value) {
                        return '';
                    }

                    if (value.toLowerCase().indexOf('mailto:') === 0) {
                        value = value.slice(7);
                    }

                    questionIndex = value.indexOf('?');
                    if (questionIndex > -1) {
                        value = value.slice(0, questionIndex);
                    }

                    value = value.trim();
                    emailMatch = value.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
                    if (!emailMatch || !emailMatch[0]) {
                        return '';
                    }

                    email = String(emailMatch[0]).trim();
                    if (!roleTitle) {
                        roleTitle = '<?php echo esc_js(__('Application', 'senna-finance')); ?>';
                    }

                    return 'mailto:' + email + '?subject=' + encodeURIComponent(roleTitle);
                }

                renderCompanyLogoPreview($companyLogoInput.val());

                $companyLogoInput.on('change input', function() {
                    renderCompanyLogoPreview($(this).val());
                });

                $('#paste-company-logo').on('click', function(e) {
                    e.preventDefault();
                    $('#company-logo-url-input').slideDown(200);
                    $('#company_logo_url_input').focus();
                });

                $('#cancel-company-logo-url').on('click', function(e) {
                    e.preventDefault();
                    $('#company-logo-url-input').slideUp(200);
                    $('#company_logo_url_input').val('');
                });

                $('#apply-company-logo-url').on('click', function(e) {
                    e.preventDefault();
                    var url = $('#company_logo_url_input').val().trim();
                    if (!url) {
                        return;
                    }

                    if (url.match(/^https?:\/\/.+\.(jpg|jpeg|png|gif|svg|webp)(\?.*)?$/i) || url.match(/^https?:\/\/.+/i)) {
                        setCompanyLogo(url);
                        $('#company-logo-url-input').slideUp(200);
                        $('#company_logo_url_input').val('');
                    } else {
                        alert('<?php esc_attr_e('Please enter a valid image URL', 'senna-finance'); ?>');
                    }
                });

                $('#company_logo_url_input').on('keypress', function(e) {
                    if (e.which === 13) {
                        e.preventDefault();
                        $('#apply-company-logo-url').trigger('click');
                    }
                });

                $('#upload-company-logo').on('click', function(e) {
                    e.preventDefault();

                    if (companyLogoFrame) {
                        companyLogoFrame.open();
                        return;
                    }

                    companyLogoFrame = wp.media({
                        title: '<?php esc_attr_e('Select Company Logo', 'senna-finance'); ?>',
                        button: {
                            text: '<?php esc_attr_e('Use this logo', 'senna-finance'); ?>'
                        },
                        multiple: false,
                        library: {
                            type: 'image'
                        }
                    });

                    companyLogoFrame.on('select', function() {
                        var attachment = companyLogoFrame.state().get('selection').first().toJSON();
                        setCompanyLogo(attachment.url);
                    });

                    companyLogoFrame.open();
                });

                $('#clear-company-logo').on('click', function(e) {
                    e.preventDefault();
                    setCompanyLogo('');
                    $('#company-logo-url-input').slideUp(200);
                    $('#company_logo_url_input').val('');
                });

                $('#format-application-mailto').on('click', function(e) {
                    e.preventDefault();

                    var formatted = buildApplicationMailto($('#application_url').val());
                    if (!formatted) {
                        alert('<?php echo esc_js(__('Enter a valid email address or mailto value first.', 'senna-finance')); ?>');
                        return;
                    }

                    $('#application_url').val(formatted);
                });

                function toggleSourcePlatformCustomField() {
                    var isOther = $('#source_platform').val() === 'Other';
                    $('#source_platform_custom_wrap').toggle(isOther);
                    if (!isOther) {
                        $('#source_platform_custom').val('');
                    }
                }

                $('#source_platform').on('change', toggleSourcePlatformCustomField);
                toggleSourcePlatformCustomField();

                var $extraMaterialsList = $('.sffc-crm-extra-materials-builder');
                var extraMaterialIndex = $extraMaterialsList.length ?
                    Number($extraMaterialsList.attr('data-count') || $extraMaterialsList.children('.sffc-crm-extra-material-card').length || 0) :
                    0;
                var extraMaterialTemplate = $('#sffc-crm-extra-material-template').html() || '';

                $('#add-extra-material').on('click', function() {
                    if (!$extraMaterialsList.length || !extraMaterialTemplate) {
                        return;
                    }

                    var markup = extraMaterialTemplate.replace(/__index__/g, String(extraMaterialIndex));
                    $extraMaterialsList.append(markup);
                    extraMaterialIndex += 1;
                    $extraMaterialsList.attr('data-count', String(extraMaterialIndex));
                });

                $(document).on('click', '.sffc-crm-extra-material-remove', function() {
                    $(this).closest('.sffc-crm-extra-material-card').remove();
                });

                // Knock-out builder logic
                var $knockoutList = $('.sffc-crm-knockout-builder');
                var knockoutTemplate = $('#sffc-crm-knockout-template').html();
                var knockoutCount = parseInt($knockoutList.data('count'), 10) || $knockoutList.children('.sffc-crm-knockout-card').length || 0;

                function toggleKnockoutOptions($select) {
                    var showOptions = $select.val() === 'single_choice';
                    var $optionsField = $select.closest('.sffc-crm-knockout-card').find('.sffc-crm-knockout-options');
                    if (showOptions) {
                        $optionsField.slideDown(120);
                    } else {
                        $optionsField.slideUp(120);
                    }
                }

                $knockoutList.on('change', '.sffc-crm-knockout-type', function() {
                    toggleKnockoutOptions($(this));
                });

                $knockoutList.find('.sffc-crm-knockout-type').each(function() {
                    toggleKnockoutOptions($(this));
                });

                $('#add-knockout-question').on('click', function(e) {
                    e.preventDefault();
                    if (!knockoutTemplate) {
                        return;
                    }
                    var index = knockoutCount++;
                    var uid = 'ko_' + Date.now() + '_' + Math.floor(Math.random() * 1000);
                    var html = knockoutTemplate.replace(/__index__/g, index).replace(/__uid__/g, uid);
                    var $newCard = $(html);
                    $knockoutList.append($newCard);
                });

                $knockoutList.on('click', '.sffc-crm-knockout-remove', function(e) {
                    e.preventDefault();
                    var $card = $(this).closest('.sffc-crm-knockout-card');
                    var cardsRemaining = $knockoutList.children('.sffc-crm-knockout-card').length;
                    if (cardsRemaining <= 1) {
                        $card.find('input[type="text"], textarea').val('');
                        $card.find('select').val('yes_no');
                        $card.find('.sffc-crm-knockout-options').hide();
                        return;
                    }
                    $card.slideUp(150, function() {
                        $(this).remove();
                    });
                });
            });

            // Keywords Management
            jQuery(document).ready(function($) {
                var keywords = [];
                var isExtracting = false;
                var keywordMode = $('#post_keywords_mode').val() || 'auto';

                function setKeywordMode(mode) {
                    keywordMode = mode === 'manual' ? 'manual' : 'auto';
                    $('#post_keywords_mode').val(keywordMode);
                }

                // Load existing keywords if editing
                <?php if ($post_id): ?>
                    $.ajax({
                        url: ajaxurl,
                        type: 'POST',
                        data: {
                            action: 'sffc_crm_get_keywords',
                            post_id: <?php echo intval($post_id); ?>,
                            nonce: '<?php echo wp_create_nonce('sffc_crm_keywords'); ?>'
                        },
                        success: function(response) {
                            if (response.success && response.data.keywords) {
                                keywords = response.data.keywords;
                                setKeywordMode('auto');
                                renderKeywords();
                            }
                        }
                    });
                <?php endif; ?>

                // Render keywords as pills (single color - styled via CSS)
                function renderKeywords() {
                    var $container = $('#keywords-pills');
                    $container.empty();

                    keywords.forEach(function(kw, index) {
                        var $pill = $('<span class="crm-keyword-pill" data-index="' + index + '">')
                            .text(kw.label);

                        var $remove = $('<span class="remove-keyword">')
                            .html('&times;')
                            .on('click', function() {
                                removeKeyword(index);
                            });

                        $pill.append($remove);
                        $container.append($pill);
                    });

                    // Update hidden field
                    $('#post_keywords').val(JSON.stringify(keywords));
                    $('#post_keywords_mode').val(keywordMode);
                }

                // Remove keyword
                function removeKeyword(index) {
                    keywords.splice(index, 1);
                    setKeywordMode('manual');
                    renderKeywords();
                }

                // Extract keywords via AJAX
                function extractKeywords(force) {
                    if (isExtracting) return;

                    var description = $('#content').val();
                    if (!description || description.trim().length < 50) {
                        alert('<?php esc_html_e('Please enter at least 50 characters in the post content before extracting keywords.', 'senna-finance'); ?>');
                        return;
                    }

                    isExtracting = true;
                    var $regenerateBtn = $('#regenerate-keywords');
                    var originalText = $regenerateBtn.html();
                    $regenerateBtn.prop('disabled', true).html('⏳ <?php esc_html_e('Extracting...', 'senna-finance'); ?>');

                    $.ajax({
                        url: ajaxurl,
                        type: 'POST',
                        data: {
                            action: 'sffc_crm_extract_keywords',
                            description: description,
                            location: $('#location').val(),
                            role_title: $('#role_title').val(),
                            company: $('#company').val(),
                            sector: $('#sector').val(),
                            seniority: $('#seniority').val(),
                            experience_years: $('#experience_years').val(),
                            force: force ? 1 : 0,
                            post_id: <?php echo $post_id ? intval($post_id) : 'null'; ?>,
                            nonce: '<?php echo wp_create_nonce('sffc_crm_keywords'); ?>'
                        },
                        success: function(response) {
                            if (response.success && response.data.keywords) {
                                keywords = response.data.keywords;
                                setKeywordMode('auto');
                                renderKeywords();
                            } else {
                                alert(response.data.message || '<?php esc_html_e('Failed to extract keywords', 'senna-finance'); ?>');
                            }
                        },
                        error: function() {
                            alert('<?php esc_html_e('Error extracting keywords. Please try again.', 'senna-finance'); ?>');
                        },
                        complete: function() {
                            isExtracting = false;
                            $regenerateBtn.prop('disabled', false).html(originalText);
                        }
                    });
                }

                // Auto-extract on description blur (only if no keywords yet)
                $('#content').on('blur', function() {
                    if (keywords.length === 0 && $(this).val().trim().length >= 50) {
                        extractKeywords(false);
                    }
                });

                // Regenerate button
                $('#regenerate-keywords').on('click', function() {
                    extractKeywords(true);
                });

                function getAutofillPayload() {
                    return {
                        source_url: $('#source_url').val(),
                        application_url: $('#application_url').val(),
                        company_logo: $('#company_logo').val(),
                        role_title: $('#role_title').val(),
                        company: $('#company').val(),
                        location: $('#location').val(),
                        sector: $('#sector').val(),
                        seniority: $('#seniority').val(),
                        experience_years: $('#experience_years').val(),
                        response_label: $('#response_label').val(),
                        response_badge: $('#response_badge').val(),
                        opening_date: $('#opening_date').val(),
                        closing_date: $('#closing_date').val(),
                        starting_date: $('#starting_date').val(),
                        duration: $('#duration').val(),
                        content: $('#content').val()
                    };
                }

                function applyAutofillSuggestions(suggestions) {
                    if (suggestions.role_title) {
                        $('#role_title').val(suggestions.role_title);
                    }
                    if (suggestions.company) {
                        $('#company').val(suggestions.company);
                    }
                    if (suggestions.location) {
                        $('#location').val(suggestions.location);
                    }
                    if (suggestions.sector) {
                        $('#sector').val(suggestions.sector);
                    }
                    if (suggestions.seniority) {
                        $('#seniority').val(suggestions.seniority);
                    }
                    if (suggestions.experience_years) {
                        $('#experience_years').val(suggestions.experience_years);
                    }
                    if (suggestions.response_label) {
                        $('#response_label').val(suggestions.response_label);
                    }
                    if (suggestions.response_badge) {
                        $('#response_badge').val(suggestions.response_badge);
                    }
                    if (suggestions.jobseeker_notes) {
                        $('#jobseeker_notes').val(suggestions.jobseeker_notes);
                    }
                    if (suggestions.opening_date) {
                        $('#opening_date').val(suggestions.opening_date);
                    }
                    if (suggestions.closing_date) {
                        $('#closing_date').val(suggestions.closing_date);
                    }
                    if (suggestions.starting_date) {
                        $('#starting_date').val(suggestions.starting_date);
                    }
                    if (suggestions.duration) {
                        $('#duration').val(suggestions.duration);
                    }
                    if (suggestions.company_logo) {
                        setCompanyLogo(suggestions.company_logo);
                    }
                    if (Array.isArray(suggestions.keywords) && suggestions.keywords.length) {
                        keywords = suggestions.keywords;
                        setKeywordMode('auto');
                        renderKeywords();
                    }

                    if (Array.isArray(suggestions.application_process)) {
                        $('input[name="application_process[]"]').prop('checked', false);
                        suggestions.application_process.forEach(function(value) {
                            $('input[name="application_process[]"][value="' + value + '"]').prop('checked', true);
                        });
                    }
                    applyInternshipProcessDefaults($('#seniority').val());

                    updateRoleTitleDetectionHint(suggestions.role_title_detection || null);
                    updateCompanyDetectionHint(suggestions.company_detection || null);
                    updateSectorDetectionHint(suggestions.sector_detection || null);
                    updateSeniorityDetectionHint(suggestions.seniority_detection || null);
                    updateExperienceDetectionHint(suggestions.experience_detection || null);
                    updateOpeningDateDetectionHint(suggestions.opening_date_detection || null);
                    updateClosingDateDetectionHint(suggestions.closing_date_detection || null);
                    updateStartingDateDetectionHint(suggestions.starting_date_detection || null);
                    updateDurationDetectionHint(suggestions.duration_detection || null);
                }

                function updateRoleTitleDetectionHint(roleDetection) {
                    var $wrap = $('#sffc-crm-role-detection-hint');
                    var $badge = $('#sffc-crm-role-detection-badge');
                    var $text = $('#sffc-crm-role-detection-text');

                    if (!roleDetection || !roleDetection.role_title) {
                        $wrap.hide();
                        $badge.removeClass('is-high is-medium is-low').text('');
                        $text.text('');
                        return;
                    }

                    var level = roleDetection.confidence_level || 'medium';
                    var badgeText = roleDetection.confidence_label || '<?php echo esc_js(__('Detected', 'senna-finance')); ?>';
                    var reasons = Array.isArray(roleDetection.reasons) ? roleDetection.reasons.filter(Boolean) : [];
                    var message = roleDetection.message || '';

                    $badge.removeClass('is-high is-medium is-low').addClass('is-' + level).text(badgeText);

                    if (!message) {
                        message = '<?php echo esc_js(__('Detected role title:', 'senna-finance')); ?>' + ' ' + roleDetection.role_title;
                    }

                    if (reasons.length) {
                        message += ' ' + reasons.join(' · ');
                    }

                    $text.text(message);
                    $wrap.show();
                }

                function updateCompanyDetectionHint(companyDetection) {
                    var $wrap = $('#sffc-crm-company-detection-hint');
                    var $badge = $('#sffc-crm-company-detection-badge');
                    var $text = $('#sffc-crm-company-detection-text');

                    if (!companyDetection || !companyDetection.company) {
                        $wrap.hide();
                        $badge.removeClass('is-high is-medium is-low').text('');
                        $text.text('');
                        return;
                    }

                    var level = companyDetection.confidence_level || 'medium';
                    var badgeText = companyDetection.confidence_label || '<?php echo esc_js(__('Detected', 'senna-finance')); ?>';
                    var reasons = Array.isArray(companyDetection.reasons) ? companyDetection.reasons.filter(Boolean) : [];
                    var message = companyDetection.message || '';

                    $badge.removeClass('is-high is-medium is-low').addClass('is-' + level).text(badgeText);

                    if (!message) {
                        message = '<?php echo esc_js(__('Detected company:', 'senna-finance')); ?>' + ' ' + companyDetection.company;
                    }

                    if (reasons.length) {
                        message += ' ' + reasons.join(' · ');
                    }

                    $text.text(message);
                    $wrap.show();
                }

                function updateSectorDetectionHint(sectorDetection) {
                    updateGenericDetectionHint(
                        sectorDetection,
                        '#sffc-crm-sector-detection-hint',
                        '#sffc-crm-sector-detection-badge',
                        '#sffc-crm-sector-detection-text',
                        '<?php echo esc_js(__('Detected sector:', 'senna-finance')); ?>',
                        'sector_label'
                    );
                }

                function updateSeniorityDetectionHint(seniorityDetection) {
                    updateGenericDetectionHint(
                        seniorityDetection,
                        '#sffc-crm-seniority-detection-hint',
                        '#sffc-crm-seniority-detection-badge',
                        '#sffc-crm-seniority-detection-text',
                        '<?php echo esc_js(__('Detected seniority:', 'senna-finance')); ?>',
                        'seniority_label'
                    );
                }

                function updateExperienceDetectionHint(experienceDetection) {
                    updateGenericDetectionHint(
                        experienceDetection,
                        '#sffc-crm-experience-detection-hint',
                        '#sffc-crm-experience-detection-badge',
                        '#sffc-crm-experience-detection-text',
                        '<?php echo esc_js(__('Detected experience:', 'senna-finance')); ?>',
                        'experience_years'
                    );
                }

                function updateOpeningDateDetectionHint(openingDateDetection) {
                    updateGenericDetectionHint(
                        openingDateDetection,
                        '#sffc-crm-opening-date-detection-hint',
                        '#sffc-crm-opening-date-detection-badge',
                        '#sffc-crm-opening-date-detection-text',
                        '<?php echo esc_js(__('Detected opening date:', 'senna-finance')); ?>',
                        'opening_date'
                    );
                }

                function updateClosingDateDetectionHint(closingDateDetection) {
                    updateGenericDetectionHint(
                        closingDateDetection,
                        '#sffc-crm-closing-date-detection-hint',
                        '#sffc-crm-closing-date-detection-badge',
                        '#sffc-crm-closing-date-detection-text',
                        '<?php echo esc_js(__('Detected closing date:', 'senna-finance')); ?>',
                        'closing_date'
                    );
                }

                function updateStartingDateDetectionHint(startingDateDetection) {
                    updateGenericDetectionHint(
                        startingDateDetection,
                        '#sffc-crm-starting-date-detection-hint',
                        '#sffc-crm-starting-date-detection-badge',
                        '#sffc-crm-starting-date-detection-text',
                        '<?php echo esc_js(__('Detected starting date:', 'senna-finance')); ?>',
                        'starting_date'
                    );
                }

                function updateDurationDetectionHint(durationDetection) {
                    updateGenericDetectionHint(
                        durationDetection,
                        '#sffc-crm-duration-detection-hint',
                        '#sffc-crm-duration-detection-badge',
                        '#sffc-crm-duration-detection-text',
                        '<?php echo esc_js(__('Detected duration:', 'senna-finance')); ?>',
                        'duration'
                    );
                }

                function updateGenericDetectionHint(payload, wrapSelector, badgeSelector, textSelector, fallbackPrefix, valueKey) {
                    var $wrap = $(wrapSelector);
                    var $badge = $(badgeSelector);
                    var $text = $(textSelector);

                    if (!payload || !payload[valueKey]) {
                        $wrap.hide();
                        $badge.removeClass('is-high is-medium is-low').text('');
                        $text.text('');
                        return;
                    }

                    var level = payload.confidence_level || 'medium';
                    var badgeText = payload.confidence_label || '<?php echo esc_js(__('Detected', 'senna-finance')); ?>';
                    var reasons = Array.isArray(payload.reasons) ? payload.reasons.filter(Boolean) : [];
                    var message = payload.message || (fallbackPrefix + ' ' + payload[valueKey]);

                    if (reasons.length) {
                        message += ' ' + reasons.join(' · ');
                    }

                    $badge.removeClass('is-high is-medium is-low').addClass('is-' + level).text(badgeText);
                    $text.text(message);
                    $wrap.show();
                }

                function runAutofill($button, onComplete, mode) {
                    var $status = $('#sffc-crm-autofill-status');
                    var content = $('#content').val().trim();
                    mode = mode || 'rules';

                    if (content.length < 50 && !$('#source_url').val().trim() && !$('#application_url').val().trim()) {
                        alert('<?php esc_html_e('Paste at least 50 characters of the job description or add a source URL before auto-filling the role fields.', 'senna-finance'); ?>');
                        if (typeof onComplete === 'function') {
                            onComplete(false);
                        }
                        return;
                    }

                    $status.text(mode === 'claude' ?
                        '<?php echo esc_js(__('Claude is inferring the role fields from the job description...', 'senna-finance')); ?>' :
                        '<?php echo esc_js(__('Scanning the role and populating the form…', 'senna-finance')); ?>');

                    $.ajax({
                        url: ajaxurl,
                        type: 'POST',
                        data: $.extend({
                            action: mode === 'claude' ? 'sffc_crm_autofill_post_fields_with_claude' : 'sffc_crm_autofill_post_fields',
                            nonce: '<?php echo wp_create_nonce('sffc_crm_post_autofill'); ?>'
                        }, getAutofillPayload()),
                        success: function(response) {
                            if (!response.success || !response.data) {
                                alert((response.data && response.data.message) || '<?php esc_html_e('Failed to auto-fill the role fields.', 'senna-finance'); ?>');
                                if (typeof onComplete === 'function') {
                                    onComplete(false);
                                }
                                return;
                            }

                            applyAutofillSuggestions(response.data.suggestions || {});
                            $status.text(response.data.message || '<?php esc_html_e('Role fields updated from the source link or pasted job description.', 'senna-finance'); ?>');
                            if (typeof onComplete === 'function') {
                                onComplete(true);
                            }
                        },
                        error: function(xhr) {
                            var message = (xhr.responseJSON && xhr.responseJSON.data && xhr.responseJSON.data.message) ?
                                xhr.responseJSON.data.message :
                                '<?php esc_html_e('Error auto-filling the role fields. Please try again.', 'senna-finance'); ?>';
                            alert(message);
                            if (typeof onComplete === 'function') {
                                onComplete(false);
                            }
                        },
                        complete: function() {
                            if ($button) {
                                $button.prop('disabled', false);
                            }
                        }
                    });
                }

                function runRewrite($button, thenAutofill, autofillMode, rewriteMode) {
                    var $status = $('#sffc-crm-autofill-status');
                    var content = $('#content').val().trim();
                    var originalText = $button.data('sffcOriginalText') || $button.text();
                    autofillMode = autofillMode || 'rules';
                    rewriteMode = rewriteMode || 'claude';
                    $button.data('sffcOriginalText', originalText);

                    if (content.length < 50) {
                        alert(rewriteMode === 'claude' ?
                            '<?php echo esc_js(__('Paste at least 50 characters of the job description before asking Claude to rewrite it.', 'senna-finance')); ?>' :
                            '<?php echo esc_js(__('Paste at least 50 characters of the job description before asking Senna to structure it.', 'senna-finance')); ?>'
                        );
                        $button.prop('disabled', false).text(originalText);
                        return;
                    }

                    $status.text(rewriteMode === 'claude' ?
                        '<?php echo esc_js(__('Claude is rewriting the job description for the platform...', 'senna-finance')); ?>' :
                        '<?php echo esc_js(__('Senna is structuring the job description for the platform...', 'senna-finance')); ?>'
                    );

                    $.ajax({
                        url: ajaxurl,
                        type: 'POST',
                        data: $.extend({
                            action: 'sffc_crm_rewrite_post_content',
                            nonce: '<?php echo wp_create_nonce('sffc_crm_post_rewrite'); ?>',
                            processor: rewriteMode
                        }, getAutofillPayload()),
                        success: function(response) {
                            if (!response.success || !response.data) {
                                alert((response.data && response.data.message) || (rewriteMode === 'claude' ?
                                    '<?php echo esc_js(__('Claude could not rewrite the job description.', 'senna-finance')); ?>' :
                                    '<?php echo esc_js(__('Senna could not structure the job description.', 'senna-finance')); ?>'
                                ));
                                if (thenAutofill) {
                                    $button.prop('disabled', false).text(originalText);
                                }
                                return;
                            }

                            if (response.data.content) {
                                $('#content').val(response.data.content);
                            }

                            $status.text(response.data.message || '<?php esc_html_e('Job description rewritten for the platform.', 'senna-finance'); ?>');

                            if (thenAutofill) {
                                runAutofill($button, function(success) {
                                    $button.prop('disabled', false).text(originalText);
                                }, autofillMode);
                            }
                        },
                        error: function(xhr) {
                            var message = (xhr.responseJSON && xhr.responseJSON.data && xhr.responseJSON.data.message) ?
                                xhr.responseJSON.data.message :
                                '<?php esc_html_e('Error rewriting the job description. Please try again.', 'senna-finance'); ?>';
                            alert(message);
                            if (thenAutofill) {
                                $button.prop('disabled', false).text(originalText);
                            }
                        },
                        complete: function() {
                            if (!thenAutofill) {
                                $button.prop('disabled', false).text(originalText);
                            }
                        }
                    });
                }

                $('#sffc-crm-autofill-post').on('click', function() {
                    var $button = $(this);
                    $button.prop('disabled', true).text('<?php echo esc_js(__('Auto-filling...', 'senna-finance')); ?>');
                    runAutofill($button, function() {
                        $button.prop('disabled', false).text('<?php echo esc_js(__('Auto-fill from job description', 'senna-finance')); ?>');
                    }, 'rules');
                });

                $('#sffc-crm-autofill-post-claude').on('click', function() {
                    var $button = $(this);
                    $button.prop('disabled', true).text('<?php echo esc_js(__('Claude Auto-fill...', 'senna-finance')); ?>');
                    runAutofill($button, function() {
                        $button.prop('disabled', false).text('<?php echo esc_js(__('Auto-fill with Claude', 'senna-finance')); ?>');
                    }, 'claude');
                });

                $('#sffc-crm-fetch-source-autofill').on('click', function() {
                    var $button = $(this);
                    var sourceUrl = $('#source_url').val().trim();
                    var applicationUrl = $('#application_url').val().trim();

                    if (!sourceUrl && !applicationUrl) {
                        alert('<?php echo esc_js(__('Add a source URL or application URL first.', 'senna-finance')); ?>');
                        return;
                    }

                    $button.prop('disabled', true).text('<?php echo esc_js(__('Fetching...', 'senna-finance')); ?>');
                    runAutofill($button, function() {
                        $button.prop('disabled', false).text('<?php echo esc_js(__('Fetch Source + Auto-fill', 'senna-finance')); ?>');
                    }, 'claude');
                });

                $('#sffc-crm-test-embed-link').on('click', function() {
                    var $button = $(this);
                    var url = ($('#application_url').val() || $('#source_url').val() || '').trim();
                    var provider = ($('#source_platform').val() || $('#source_platform_custom').val() || '').trim();
                    var $panel = $('#sffc-crm-embed-test');
                    var $status = $('#sffc-crm-embed-test-status');
                    var $copy = $('#sffc-crm-embed-test-copy');
                    var $frame = $('#sffc-crm-embed-test-frame');
                    var nonce = $('input[name="sffc_crm_admin_nonce"]').first().val() || '';

                    if (!url) {
                        alert('<?php echo esc_js(__('Add an application URL first.', 'senna-finance')); ?>');
                        return;
                    }

                    $panel.addClass('is-active');
                    $status.removeClass('is-embeddable is-likely is-blocked is-unknown is-default').addClass('is-unknown').text('<?php echo esc_js(__('Testing...', 'senna-finance')); ?>');
                    $copy.text('<?php echo esc_js(__('Checking response headers and loading the iframe preview.', 'senna-finance')); ?>');
                    $frame.attr('src', url);
                    $button.prop('disabled', true).text('<?php echo esc_js(__('Testing Embed...', 'senna-finance')); ?>');

                    $.post(ajaxurl, {
                        action: 'sffc_crm_test_embed_url',
                        nonce: nonce,
                        url: url,
                        provider: provider
                    }).done(function(response) {
                        var data = response && response.success ? response.data || {} : {};
                        var statusClass = data.class || 'is-unknown';
                        $status.removeClass('is-embeddable is-likely is-blocked is-unknown is-default').addClass(statusClass).text(data.label || '<?php echo esc_js(__('Embed unknown', 'senna-finance')); ?>');
                        $copy.text(data.detail || '<?php echo esc_js(__('Use the preview below to confirm whether the page visibly loads inside an iframe.', 'senna-finance')); ?>');
                    }).fail(function() {
                        $status.removeClass('is-embeddable is-likely is-blocked is-unknown is-default').addClass('is-unknown').text('<?php echo esc_js(__('Embed unknown', 'senna-finance')); ?>');
                        $copy.text('<?php echo esc_js(__('The header check failed. Use the iframe preview below as the visual test.', 'senna-finance')); ?>');
                    }).always(function() {
                        $button.prop('disabled', false).text('<?php echo esc_js(__('Test Embed', 'senna-finance')); ?>');
                    });
                });

                $('#sffc-crm-rewrite-post').on('click', function() {
                    var $button = $(this);
                    $button.data('sffcOriginalText', $button.text());
                    $button.prop('disabled', true).text('<?php echo esc_js(__('Rewriting...', 'senna-finance')); ?>');
                    runRewrite($button, false, 'claude', 'claude');
                });

                $('#sffc-crm-rewrite-autofill-post-senna').on('click', function() {
                    var $button = $(this);
                    $button.data('sffcOriginalText', $button.text());
                    $button.prop('disabled', true).text('<?php echo esc_js(__('Senna rewriting + auto-filling...', 'senna-finance')); ?>');
                    runRewrite($button, true, 'rules', 'senna');
                });

                $('#sffc-crm-rewrite-autofill-post').on('click', function() {
                    var $button = $(this);
                    $button.data('sffcOriginalText', $button.text());
                    $button.prop('disabled', true).text('<?php echo esc_js(__('Rewriting + Auto-filling...', 'senna-finance')); ?>');
                    runRewrite($button, true, 'claude', 'claude');
                });

                function applyLegacyExecutionProcessDefaults(seniority) {
                    var defaultProcessSteps = [
                        'application',
                        'cv',
                        'cover_letter',
                        'video_interview',
                        'technical_tests',
                        'case_study',
                        'interview_rounds'
                    ];

                    if (String(seniority || '') !== 'intern') {
                        return;
                    }

                    defaultProcessSteps.forEach(function(value) {
                        $('input[name="application_process[]"][value="' + value + '"]').prop('checked', true);
                    });
                }

                $('#seniority').on('change', function() {
                    applyLegacyExecutionProcessDefaults($(this).val());
                });

                applyLegacyExecutionProcessDefaults($('#seniority').val());

                // Manual keyword input
                $('#keyword-input').on('keypress', function(e) {
                    if (e.which === 13) {
                        e.preventDefault();
                        var label = $(this).val().trim();
                        if (label) {
                            // Add as generic skill keyword
                            keywords.push({
                                label: label,
                                type: 'skill',
                                priority: 5
                            });
                            setKeywordMode('manual');
                            renderKeywords();
                            $(this).val('');
                        }
                    }
                });

                // Team Contacts functionality
                var teamContactIndex = <?php echo max(0, count($team_contacts)); ?>;

