                        '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px;">' +
                        '<input type="text" name="team_contacts[' + teamContactIndex + '][name]" placeholder="<?php esc_attr_e('Name (e.g., Portfolio Manager)', 'senna-finance'); ?>" class="regular-text">' +
                        '<input type="text" name="team_contacts[' + teamContactIndex + '][title]" placeholder="<?php esc_attr_e('Title', 'senna-finance'); ?>" class="regular-text">' +
                        '</div>' +
                        '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px;">' +
                        '<input type="email" name="team_contacts[' + teamContactIndex + '][email]" placeholder="<?php esc_attr_e('Email', 'senna-finance'); ?>" class="regular-text">' +
                        '<input type="tel" name="team_contacts[' + teamContactIndex + '][phone]" placeholder="<?php esc_attr_e('Phone', 'senna-finance'); ?>" class="regular-text">' +
                        '</div>' +
                        '<div style="display: flex; gap: 10px; align-items: center;">' +
                        '<input type="url" name="team_contacts[' + teamContactIndex + '][linkedin]" placeholder="<?php esc_attr_e('LinkedIn URL', 'senna-finance'); ?>" class="regular-text" style="flex: 1;">' +
