            'headers' => [
                'Content-Type' => 'application/json',
                'x-api-key' => $api_key,
                'anthropic-version' => '2023-06-01',
            ],
            'body' => wp_json_encode($request_body),
        ]);

        if (is_wp_error($response)) {
            error_log('SFFC CRM Admin Claude Autofill Error: ' . $response->get_error_message());
            return [];
        }

        $status = wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);
        if ($status !== 200 || empty($body['content'][0]['text'])) {
            error_log('SFFC CRM Admin Claude Autofill Error: status ' . $status . ': ' . $this->get_crm_admin_claude_response_error_message($response));
            return [];
        }

        $text = trim((string) $body['content'][0]['text']);
        if ($text === '') {
            return [];
        }

        if (preg_match('/\{.*\}/s', $text, $matches)) {
            $text = $matches[0];
        }

        $decoded = json_decode($text, true);
        if (!is_array($decoded)) {
            error_log('SFFC CRM Admin Claude Autofill Error: invalid JSON');
            return [];
        }

        $result = [
            'role_title' => $this->normalize_crm_post_role_title_candidate((string) ($decoded['role_title'] ?? '')),
            'company' => $this->normalize_crm_post_company_candidate((string) ($decoded['company'] ?? ''), (string) ($decoded['role_title'] ?? '')),
            'location' => sanitize_text_field($decoded['location'] ?? ''),
            'sector' => in_array((string) ($decoded['sector'] ?? ''), $allowed_sectors, true) ? (string) $decoded['sector'] : '',
            'seniority' => in_array((string) ($decoded['seniority'] ?? ''), $allowed_seniority, true) ? (string) $decoded['seniority'] : '',
            'experience_years' => sanitize_text_field($decoded['experience_years'] ?? ''),
            'response_label' => sanitize_text_field($decoded['response_label'] ?? ''),
            'response_badge' => sanitize_text_field($decoded['response_badge'] ?? ''),
            'recruiter_display_name' => sanitize_text_field($decoded['recruiter_display_name'] ?? ''),
            'recruiter_display_company' => sanitize_text_field($decoded['recruiter_display_company'] ?? ''),
            'jobseeker_notes' => $this->normalize_crm_post_jobseeker_note((string) ($decoded['jobseeker_notes'] ?? '')),
            'opening_date' => $this->parse_crm_post_autofill_date((string) ($decoded['opening_date'] ?? '')),
            'closing_date' => $this->parse_crm_post_autofill_date((string) ($decoded['closing_date'] ?? '')),
            'starting_date' => $this->parse_crm_post_autofill_date((string) ($decoded['starting_date'] ?? '')),
            'duration' => sanitize_text_field($decoded['duration'] ?? ''),
            'application_process' => [],
        ];

        if (!empty($decoded['application_process']) && is_array($decoded['application_process'])) {
            $result['application_process'] = array_values(array_filter(array_map(
                static function ($value) use ($allowed_process) {
                    $value = sanitize_key((string) $value);
                    return in_array($value, $allowed_process, true) ? $value : '';
                },
                $decoded['application_process']
            )));
        }

        return array_filter($result, static function ($value) {
            return $value !== '' && $value !== [];
        });
    }

    private function sanitize_crm_post_public_content($content, $company, $sector, $role_title = '')
    {
        $content = trim((string) $content);
        if ($content === '') {
            return '';
        }

        $company = trim((string) $company);
        if ($company !== '') {
            $descriptor = $this->get_crm_post_company_descriptor($company, $sector, $content, $role_title);
            $quoted_company = preg_quote($company, '/');

            $patterns = [
                '/\b' . $quoted_company . '\'s\b/i',
                '/\b' . $quoted_company . '’s\b/i',
                '/\b' . $quoted_company . '\b/i',
            ];

            foreach ($patterns as $pattern) {
                $content = preg_replace($pattern, $descriptor, $content);
            }

            $generic_descriptor_patterns = [
                '/\ba leading finance firm\b/i',
                '/\ban? leading financial services firm\b/i',
                '/\ba top[- ]tier finance firm\b/i',
                '/\ba prestigious finance firm\b/i',
                '/\ba global finance firm\b/i',
                '/\ba leading investment firm\b/i',
                '/\ba leading private equity firm\b/i',
                '/\ba leading asset manager\b/i',
                '/\ba global leader in finance\b/i',
            ];

            foreach ($generic_descriptor_patterns as $pattern) {
                $content = preg_replace($pattern, $descriptor, $content);
            }
        }

        $content = $this->remove_crm_post_senna_intro_line($content);
        $content = $this->remove_crm_post_unwanted_sections($content);
        return $this->append_crm_post_senna_about_section($content);
    }

    private function remove_crm_post_senna_intro_line($content)
    {
        $content = trim((string) $content);
        if ($content === '') {
            return '';
        }

        $patterns = [
            '/^\s*<p>\s*<strong>\s*Posted on the MENA Careers Finance\s*&amp;\s*Finance Career Guidance\.\s*<\/strong>\s*<\/p>\s*/i',
            '/^\s*<p>\s*<strong>\s*Posted on the MENA Careers Finance\s*&\s*Finance Career Guidance\.\s*<\/strong>\s*<\/p>\s*/i',
            '/^\s*Posted on the MENA Careers Finance\s*&\s*Finance Career Guidance\.\s*/i',
            '/^\s*<p>\s*<strong>\s*Posted on the MENA Careers Finance\s*&amp;\s*Private Equity Community\.\s*<\/strong>\s*<\/p>\s*/i',
            '/^\s*<p>\s*<strong>\s*Posted on the MENA Careers Finance\s*&\s*Private Equity Community\.\s*<\/strong>\s*<\/p>\s*/i',
            '/^\s*Posted on the MENA Careers Finance\s*&\s*Private Equity Community\.\s*/i',
        ];

        foreach ($patterns as $pattern) {
            $content = preg_replace($pattern, '', $content);
        }

        return trim((string) $content);
    }

    private function append_crm_post_senna_about_section($content)
    {
        $content = trim((string) $content);
        if ($content === '') {
            return '';
        }

        $normalized_content = strtolower(wp_strip_all_tags($content));
        if (
            strpos($normalized_content, 'about senna') !== false
            || strpos($normalized_content, 'for more information, visit joinsenna.com') !== false
            || strpos($normalized_content, 'senna is a careers platform for professionals pursuing opportunities in private equity and finance') !== false
            || strpos($normalized_content, 'senna helps candidates explore relevant roles') !== false
            || strpos($normalized_content, 'senna is a community platform for professionals looking to build a career in private equity') !== false
            || strpos($normalized_content, 'senna is a careers platform focused on career guidance, planning, and stronger positioning for finance candidates') !== false
            || strpos($normalized_content, 'senna is a smart job search assistant for finance professionals') !== false
            || strpos($normalized_content, 'senna is a careers platform for finance candidates who want better opportunities and more strategic career guidance') !== false
        ) {
            return $content;
        }

        $about_section = '<h3>' . esc_html__('About MENA Careers', 'senna-finance') . '</h3>'
            . '<p>' . esc_html__('MENA Careers is a private equity career platform built for candidates who want better access to recruiters, live opportunities, and market insight. It helps members discover relevant private equity roles, find specialist recruiters, and navigate the search with sharper direction across Dubai, Abu Dhabi, Riyadh, Doha, London, and Singapore. MENA Careers is designed to make the private equity search more focused, more informed, and more effective. For more information, visit joinsenna.com.', 'senna-finance') . '</p>';

        return trim($content) . "\n\n" . $about_section;
    }

    private function remove_crm_post_unwanted_sections($content)
    {
        $content = trim((string) $content);
        if ($content === '') {
            return '';
        }

        $patterns = [
            '/<h3>\s*Overview\s*<\/h3>.*?(?=<h[1-3]\b|<h3>\s*About MENA Careers\s*<\/h3>|$)/is',
            '/<h3>\s*Why This Role Stands Out\s*<\/h3>.*?(?=<h[1-3]\b|<h3>\s*About MENA Careers\s*<\/h3>|$)/is',
            '/(?:^|\n)\s*Overview\s*\n.*?(?=(?:\n[A-Z][^\n]{0,120}\n)|(?:\nAbout MENA Careers\b)|$)/is',
            '/(?:^|\n)\s*Why This Role Stands Out\s*\n.*?(?=(?:\n[A-Z][^\n]{0,120}\n)|(?:\nAbout MENA Careers\b)|$)/is',
        ];

        foreach ($patterns as $pattern) {
            $content = preg_replace($pattern, '', $content);
        }

        $content = preg_replace("/\n{3,}/", "\n\n", (string) $content);

        return trim((string) $content);
    }

    private function get_crm_post_company_descriptor($company, $sector, $content, $role_title = '')
    {
        $company = trim((string) $company);
        $sector = sanitize_key((string) $sector);
        $content = (string) $content;
        $role_title = (string) $role_title;
        $text = strtolower(trim($company . ' ' . $content . ' ' . $role_title));
        $modifier = '';

        if (preg_match('/\bboutique\b/', $text)) {
            $modifier = 'boutique ';
        } elseif (preg_match('/\b(mid[- ]cap|mid cap|mid[- ]market|middle market|upper mid[- ]market)\b/', $text)) {
            $modifier = 'mid-cap ';
        } elseif (preg_match('/\b(global|international)\b/', $text)) {
            $modifier = 'global ';
        }

        if ($sector === '' || $sector === 'other') {
            $sector = $this->detect_crm_post_sector($role_title, $company, '', $content);
        }

        if ($sector === '') {
            $sector = $this->infer_crm_post_descriptor_sector($company, $content, $role_title);
        }

        $base = 'company';
        switch ($sector) {
            case 'buyout':
            case 'growth_equity':
            case 'secondaries':
            case 'fund_of_funds':
            case 'pe':
                $base = 'private equity firm';
                break;
            case 'portfolio_operations':
                $base = 'portfolio operations team';
                break;
            case 'capital_formation':
                $base = 'capital formation team';
                break;
            case 'private_real_estate':
                $base = 'real estate private equity firm';
                break;
            case 'private_infrastructure':
                $base = 'infrastructure private equity firm';
                break;
            case 'ib':
                $base = 'investment bank';
                break;
            case 'vc':
                $base = 'venture capital firm';
                break;
            case 'hedge_fund':
                $base = 'hedge fund';
                break;
            case 'asset_management':
                $base = 'asset manager';
                break;
            case 'private_credit':
                $base = 'private credit fund';
                break;
            case 'family_office':
                $base = 'family office';
                break;
            case 'consulting':
                $base = 'consulting firm';
                break;
            case 'corporate':
                $base = preg_match('/\b(corporate finance|fp&a|financial planning|strategic finance|corporate development)\b/', $text)
                    ? 'corporate finance team'
                    : 'company';
                break;
            case 'fintech':
                $base = 'fintech company';
                break;
            case 'real_estate':
                $base = 'real estate company';
                break;
            case 'infrastructure':
                $base = preg_match('/\b(investor|investment|fund|asset management|private equity)\b/', $text)
                    ? 'infrastructure investor'
                    : 'infrastructure company';
                break;
            case 'energy':
                $base = 'energy company';
                break;
            case 'healthcare':
                $base = 'healthcare company';
                break;
            case 'technology':
                $base = 'technology company';
                break;
            case 'government':
                $base = preg_match('/\b(sovereign wealth|investment authority|public investment|fund)\b/', $text)
                    ? 'sovereign investment platform'
                    : 'public sector organisation';
                break;
            case 'non_profit':
                $base = preg_match('/\b(impact investing|investment|fund)\b/', $text)
                    ? 'impact investment platform'
                    : 'non-profit organisation';
                break;
            case 'finance':
                $base = 'financial services firm';
                break;
        }

        return trim($modifier . $base);
    }

    private function infer_crm_post_descriptor_sector($company, $content, $role_title = '')
    {
        $text = strtolower(trim(wp_strip_all_tags((string) $company . ' ' . (string) $role_title . ' ' . (string) $content)));
        if ($text === '') {
            return '';
        }

        $patterns = [
            'private_real_estate' => '/\b(real estate private equity|property fund|real assets private equity)\b/',
            'private_infrastructure' => '/\b(infrastructure private equity|infrastructure equity|core infrastructure|digital infrastructure)\b/',
            'pe' => '/\b(private equity|buyout|buy-out|growth equity|portfolio company|deal team|deal execution|lbo)\b/',
            'ib' => '/\b(investment banking|mergers and acquisitions|m&a|capital markets|leveraged finance|restructuring)\b/',
            'vc' => '/\b(venture capital|seed stage|series a|early-stage investing|startup investment)\b/',
            'hedge_fund' => '/\b(hedge fund|long\/short|systematic trading|quantitative trading)\b/',
            'asset_management' => '/\b(asset management|investment management|portfolio management|fund management|aum)\b/',
            'private_credit' => '/\b(private credit|private debt|direct lending|credit investing|loan underwriting|unitranche|mezzanine)\b/',
            'family_office' => '/\bfamily office\b/',
            'consulting' => '/\b(consulting|strategy consulting|advisory firm|mckinsey|bain|bcg|deloitte|pwc|ey|kpmg)\b/',
            'fintech' => '/\b(fintech|payments|financial technology|open banking|blockchain|crypto)\b/',
            'real_estate' => '/\b(real estate|property developer|property development|built environment)\b/',
            'infrastructure' => '/\b(infrastructure|transport assets|utilities|project finance)\b/',
            'energy' => '/\b(energy|renewables|renewable|oil and gas|power sector|utilities)\b/',
            'healthcare' => '/\b(healthcare|life sciences|biotech|pharma|pharmaceutical|medtech|clinical|hospital)\b/',
            'technology' => '/\b(software|saas|technology company|tech company|cloud|data platform|artificial intelligence|machine learning|cybersecurity|product manager|software engineer)\b/',
            'government' => '/\b(government|public sector|ministry|regulator|sovereign wealth|investment authority)\b/',
            'non_profit' => '/\b(non-profit|nonprofit|ngo|charity|foundation)\b/',
            'finance' => '/\b(financial services|finance firm|banking|wealth management|investment firm|capital markets)\b/',
        ];

        foreach ($patterns as $sector => $pattern) {
            if (preg_match($pattern, $text)) {
                return $sector;
            }
        }

        return '';
    }

    private function handle_save_hr_outreach()
    {
        if (!current_user_can('manage_options')) {
            return;
        }

        $model = new SFFC_CRM_HR_Outreach();

        $team_contacts = [];
        if (!empty($_POST['team_contacts']['name'])) {
            $count = count($_POST['team_contacts']['name']);
            for ($i = 0; $i < $count; $i++) {
                $name = sanitize_text_field($_POST['team_contacts']['name'][$i] ?? '');
                if (!$name) {
                    continue;
                }
                $team_contacts[] = [
                    'name' => $name,
                    'title' => sanitize_text_field($_POST['team_contacts']['title'][$i] ?? ''),
                    'email' => sanitize_email($_POST['team_contacts']['email'][$i] ?? ''),
                    'phone' => sanitize_text_field($_POST['team_contacts']['phone'][$i] ?? ''),
                    'linkedin' => esc_url_raw($_POST['team_contacts']['linkedin'][$i] ?? ''),
                ];
            }
        }

        $skills_input = isset($_POST['skills']) ? wp_unslash($_POST['skills']) : '';
        if (is_array($skills_input)) {
            $skills_list = $skills_input;
        } else {
            $skills_list = array_filter(array_map('trim', preg_split('/[,
]/', (string) $skills_input)));
        }
        $skills_clean = array_values(array_filter(array_map('sanitize_key', $skills_list)));

        $data = [
            'id' => intval($_POST['entry_id'] ?? 0),
            'company_name' => sanitize_text_field($_POST['company_name'] ?? ''),
            'company_logo' => $this->normalize_company_logo_input($_POST['company_logo'] ?? ''),
            'company_url' => esc_url_raw($_POST['company_url'] ?? ''),
            'location' => sanitize_text_field($_POST['location'] ?? ''),
            'regions' => sanitize_text_field($_POST['regions'] ?? ''),
            'industry' => array_map('sanitize_key', $_POST['industry'] ?? []),
            'program_types' => array_map('sanitize_key', $_POST['program_types'] ?? []),
            'process' => array_map('sanitize_key', $_POST['process'] ?? []),
            'skills' => $skills_clean,
            'hire_analysts' => !empty($_POST['hire_analysts']) ? 1 : 0,
            'hire_associates' => !empty($_POST['hire_associates']) ? 1 : 0,
            'hire_seniors' => !empty($_POST['hire_seniors']) ? 1 : 0,
            'hire_private_equity_candidates' => !empty($_POST['hire_private_equity_candidates']) ? 1 : 0,
            'hire_expats' => !empty($_POST['hire_expats']) ? 1 : 0,
            'hire_cfa_holders' => !empty($_POST['hire_cfa_holders']) ? 1 : 0,
            'hire_mba' => !empty($_POST['hire_mba']) ? 1 : 0,
            'hire_visa_sponsorship' => !empty($_POST['hire_visa_sponsorship']) ? 1 : 0,
            'hire_arabic_speakers' => !empty($_POST['hire_arabic_speakers']) ? 1 : 0,
            'hire_bilingual' => !empty($_POST['hire_bilingual']) ? 1 : 0,
            'hire_trainee' => !empty($_POST['hire_trainee']) ? 1 : 0,
            'hire_placement' => !empty($_POST['hire_placement']) ? 1 : 0,
            'role_focus' => wp_kses_post($_POST['role_focus'] ?? ''),
            'last_hire_proof' => wp_kses_post($_POST['last_hire_proof'] ?? ''),
            'interview_questions_url' => esc_url_raw($_POST['interview_questions_url'] ?? ''),
            'cv_template_url' => esc_url_raw($_POST['cv_template_url'] ?? ''),
            'cover_letter_url' => esc_url_raw($_POST['cover_letter_url'] ?? ''),
            'company_intel_url' => esc_url_raw($_POST['company_intel_url'] ?? ''),
            'contact_name' => sanitize_text_field($_POST['contact_name'] ?? ''),
            'contact_title' => sanitize_text_field($_POST['contact_title'] ?? ''),
            'contact_email' => sanitize_email($_POST['contact_email'] ?? ''),
            'contact_phone' => sanitize_text_field($_POST['contact_phone'] ?? ''),
            'contact_linkedin' => esc_url_raw($_POST['contact_linkedin'] ?? ''),
            'contact_photo' => esc_url_raw($_POST['contact_photo'] ?? ''),
            'team_contacts' => $team_contacts,
            'notes' => wp_kses_post($_POST['notes'] ?? ''),
        ];

        $result = $model->save($data);

        if (is_wp_error($result)) {
            wp_die($result);
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-contact-group.php';
        $contact_group_model = new SFFC_CRM_HR_Contact_Group();
        $contact_group_ids = isset($_POST['contact_group_ids']) && is_array($_POST['contact_group_ids'])
            ? array_map('absint', $_POST['contact_group_ids'])
            : [];
        $contact_group_model->set_groups_for_contact((int) $result, $contact_group_ids);

        wp_redirect(add_query_arg('saved', '1', admin_url('admin.php?page=sffc-crm-hr-outreach')));
        exit;
    }

    private function sanitize_knockout_questions($raw_questions)
    {
        $clean_questions = [];
        if (empty($raw_questions) || !is_array($raw_questions)) {
            return $clean_questions;
        }

        $allowed_types = ['yes_no', 'single_choice', 'number', 'text'];

        foreach ($raw_questions as $question) {
            if (!is_array($question)) {
                continue;
            }

            $question = wp_unslash($question);

            $prompt = sanitize_text_field($question['prompt'] ?? '');
            if (!$prompt) {
                continue;
            }

            $type = sanitize_key($question['type'] ?? 'text');
            if (!in_array($type, $allowed_types, true)) {
                $type = 'text';
            }

            $ideal = sanitize_text_field($question['ideal_answer'] ?? '');
            $helper = sanitize_textarea_field($question['helper_text'] ?? '');
            $weight = intval($question['weight'] ?? 1);
            $weight = max(1, min(5, $weight));

            $options = [];
            if (!empty($question['options'])) {
                if (is_array($question['options'])) {
                    $options = array_values(array_filter(array_map('sanitize_text_field', $question['options'])));
                } elseif (is_string($question['options'])) {
                    $options = array_map('trim', explode(',', $question['options']));
                    $options = array_values(array_filter(array_map('sanitize_text_field', $options)));
                }
            }

            $modes = $question['modes'] ?? ['recruiter'];
            if (!is_array($modes)) {
                $modes = [$modes];
            }
            $modes = array_map(static function ($mode) {
                return sanitize_key($mode);
            }, $modes);
            $modes = array_values(array_intersect($modes, ['recruiter', 'smart_apply']));
            if (empty($modes)) {
                $modes = ['recruiter'];
            }

            $question_id = sanitize_key($question['id'] ?? '');
            if (!$question_id) {
                $question_id = sanitize_key('ko_' . uniqid('', true));
            }

            $clean_questions[] = [
                'id' => $question_id,
                'prompt' => $prompt,
                'type' => $type,
                'ideal_answer' => $ideal,
                'helper_text' => $helper,
                'weight' => $weight,
                'options' => $options,
                'modes' => $modes,
            ];
        }

        return array_values($clean_questions);
    }

    private function sanitize_crm_post_extra_materials($raw_materials)
    {
        $clean_materials = [];
        if (empty($raw_materials) || !is_array($raw_materials)) {
            return $clean_materials;
        }

        foreach ($raw_materials as $material) {
            if (!is_array($material)) {
                continue;
            }

            $material = wp_unslash($material);

            $label = sanitize_text_field($material['label'] ?? '');
            $url = esc_url_raw($material['url'] ?? '');
            $description = sanitize_textarea_field($material['description'] ?? '');
            $file_type = strtoupper(sanitize_text_field($material['file_type'] ?? ''));

            if ($label === '' || $url === '') {
                continue;
            }

            if ($file_type === '') {
                $path = wp_parse_url($url, PHP_URL_PATH);
                $extension = $path ? strtolower(pathinfo((string) $path, PATHINFO_EXTENSION)) : '';
                $file_type = $extension !== '' ? strtoupper($extension) : 'LINK';
            }

            $clean_materials[] = [
                'label' => $label,
                'url' => $url,
                'description' => $description,
                'file_type' => substr($file_type, 0, 12),
            ];
        }

        return array_values($clean_materials);
    }

    private function normalize_company_logo_input($value)
    {
        $value = trim((string) $value);
        if ($value === '') {
            return '';
        }

        if (stripos($value, 'data:') === 0) {
            return esc_url_raw($value);
        }

        if (!preg_match('#^https?://#i', $value)) {
            $value = preg_replace('#^(https?:)?//#i', '', $value);

            if (strpos($value, '/') === false && strpos($value, '.') !== false) {
                $value = 'https://logo.clearbit.com/' . $value;
            } else {
                $value = 'https://' . ltrim($value, '/');
            }
        }

        return esc_url_raw($value);
    }

    private function cache_crm_company_logo_url($logo_url, $company = '', $source_url = '')
    {
        $logo_url = $this->normalize_company_logo_input($logo_url);
        if ($logo_url === '' || stripos($logo_url, 'data:') === 0) {
            return $logo_url;
        }

        $host = strtolower((string) wp_parse_url($logo_url, PHP_URL_HOST));
        if ($host === '' || $host === 'media.joinsenna.com') {
            return $logo_url;
        }

        $existing_attachment_id = $this->find_cached_crm_company_logo_attachment($logo_url, $company);
        if ($existing_attachment_id > 0) {
            $cached_url = wp_get_attachment_url($existing_attachment_id);
            return $cached_url ? esc_url_raw($cached_url) : $logo_url;
        }

        if (!function_exists('download_url')) {
            require_once ABSPATH . 'wp-admin/includes/file.php';
        }
        if (!function_exists('media_handle_sideload')) {
            require_once ABSPATH . 'wp-admin/includes/media.php';
        }
        if (!function_exists('wp_read_image_metadata')) {
            require_once ABSPATH . 'wp-admin/includes/image.php';
        }

        $tmp = download_url($logo_url, 20);
        if (is_wp_error($tmp)) {
            error_log('SFFC CRM Logo Cache: Failed to download logo ' . $logo_url . ': ' . $tmp->get_error_message());
            return $logo_url;
        }

        $path = (string) wp_parse_url($logo_url, PHP_URL_PATH);
        $extension = strtolower(pathinfo($path, PATHINFO_EXTENSION));
        $allowed_extensions = ['jpg', 'jpeg', 'png', 'gif', 'webp'];
        if (!in_array($extension, $allowed_extensions, true)) {
            $extension = $this->detect_crm_company_logo_extension_from_file($tmp);
        }

        if (!in_array($extension, $allowed_extensions, true)) {
            @unlink($tmp);
            return $logo_url;
        }

        $company_key = sanitize_title($company);
        $filename_seed = $company_key !== '' ? $company_key : sanitize_title((string) wp_parse_url($logo_url, PHP_URL_HOST));
        if ($filename_seed === '') {
            $filename_seed = 'company-logo';
        }

        $file_array = [
            'name' => $filename_seed . '-logo.' . $extension,
            'tmp_name' => $tmp,
        ];

        $attachment_id = media_handle_sideload($file_array, 0, trim((string) $company) !== '' ? $company . ' logo' : 'Company logo');
        if (is_wp_error($attachment_id)) {
            @unlink($tmp);
            error_log('SFFC CRM Logo Cache: Failed to sideload logo ' . $logo_url . ': ' . $attachment_id->get_error_message());
            return $logo_url;
        }

        update_post_meta($attachment_id, '_sffc_company_logo_source_url', esc_url_raw($logo_url));
        update_post_meta($attachment_id, '_sffc_company_logo_source_hash', hash('sha256', strtolower($logo_url)));
        update_post_meta($attachment_id, '_sffc_company_logo_company_key', $company_key);
        if ($source_url !== '') {
            update_post_meta($attachment_id, '_sffc_company_logo_role_source_url', esc_url_raw($source_url));
        }

        $cached_url = wp_get_attachment_url($attachment_id);
        return $cached_url ? esc_url_raw($cached_url) : $logo_url;
    }

    private function find_cached_crm_company_logo_attachment($logo_url, $company = '')
    {
        $logo_url = esc_url_raw((string) $logo_url);
        if ($logo_url === '') {
            return 0;
        }

        $source_hash = hash('sha256', strtolower($logo_url));
        $attachment_ids = get_posts([
            'post_type' => 'attachment',
            'post_status' => 'inherit',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                'relation' => 'OR',
                [
                    'key' => '_sffc_company_logo_source_hash',
                    'value' => $source_hash,
                ],
                [
                    'key' => '_sffc_company_logo_source_url',
                    'value' => $logo_url,
                ],
            ],
            'no_found_rows' => true,
        ]);

        if (!empty($attachment_ids[0])) {
            return (int) $attachment_ids[0];
        }

        $company_key = sanitize_title($company);
        if ($company_key === '') {
            return 0;
        }

        $attachment_ids = get_posts([
            'post_type' => 'attachment',
            'post_status' => 'inherit',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'meta_query' => [
                [
                    'key' => '_sffc_company_logo_company_key',
                    'value' => $company_key,
                ],
            ],
            'no_found_rows' => true,
            'orderby' => 'ID',
            'order' => 'DESC',
        ]);

        return !empty($attachment_ids[0]) ? (int) $attachment_ids[0] : 0;
    }

    private function detect_crm_company_logo_extension_from_file($file_path)
    {
        if (!is_readable($file_path)) {
            return '';
        }

        $image_info = @getimagesize($file_path);
        $mime = is_array($image_info) ? strtolower((string) ($image_info['mime'] ?? '')) : '';
        $map = [
            'image/jpeg' => 'jpg',
            'image/png' => 'png',
            'image/gif' => 'gif',
            'image/webp' => 'webp',
        ];

        return $map[$mime] ?? '';
    }

    /**
     * Sync CRM post to sffc_recruiter_post CPT
     */
    private function sync_to_recruiter_post_cpt($crm_post_id, $post_data, $recruiter_data)
    {
        global $wpdb;

        $post_data = wp_parse_args($post_data, [
            'role_title' => '',
            'content' => '',
            'admin_approved' => 0,
            'company' => '',
            'location' => '',
            'sector' => '',
            'seniority' => '',
            'salary_text' => '',
            'application_url' => '',
            'is_featured' => 0,
            'company_logo' => '',
        ]);

        $recruiter_data = wp_parse_args($recruiter_data ?: [], [
            'name' => '',
            'title' => '',
            'firm' => '',
            'email' => '',
            'linkedin_url' => '',
            'photo_url' => '',
        ]);

        // Check if already linked
        $existing_wp_post_id = $wpdb->get_var($wpdb->prepare(
            "SELECT wp_post_id FROM {$wpdb->prefix}sffc_crm_posts WHERE id = %d",
            $crm_post_id
        ));

        $wp_post_data = [
            'post_title' => $post_data['role_title'],
            'post_content' => $post_data['content'],
            'post_status' => $post_data['admin_approved'] ? 'publish' : 'draft',
            'post_type' => 'sffc_recruiter_post',
        ];

        if ($existing_wp_post_id) {
            $wp_post_data['ID'] = $existing_wp_post_id;
            $wp_post_id = wp_update_post($wp_post_data);
        } else {
            $wp_post_id = wp_insert_post($wp_post_data);
        }

        if ($wp_post_id && !is_wp_error($wp_post_id)) {
            // Link WP post back to its CRM record so job-apply.php can find it instantly
            update_post_meta($wp_post_id, '_crm_post_id', $crm_post_id);

            // Update meta fields
            update_post_meta($wp_post_id, '_recruiter_name', $recruiter_data['name']);
            update_post_meta($wp_post_id, '_recruiter_title', $recruiter_data['title']);
            update_post_meta($wp_post_id, '_recruiter_company', $recruiter_data['firm']);
            update_post_meta($wp_post_id, '_recruiter_email', $recruiter_data['email']);
            update_post_meta($wp_post_id, '_recruiter_linkedin', $recruiter_data['linkedin_url']);

            // Handle recruiter image - download and attach if URL
            if (!empty($recruiter_data['photo_url'])) {
                $this->set_recruiter_image_from_url($wp_post_id, $recruiter_data['photo_url']);
            }

            update_post_meta($wp_post_id, '_job_title', $post_data['role_title']);
            update_post_meta($wp_post_id, '_company_name', $post_data['company']);
            update_post_meta($wp_post_id, '_job_location', $post_data['location']);
            if (!empty($post_data['company_logo'])) {
                update_post_meta($wp_post_id, '_company_logo', esc_url_raw($post_data['company_logo']));
            }
            update_post_meta($wp_post_id, '_is_featured', $post_data['is_featured'] ? '1' : '0');

            // Parse salary if available
            if (!empty($post_data['salary_text'])) {
                update_post_meta($wp_post_id, '_salary_display', $post_data['salary_text']);
            }

            // Set application URL if available
            if (!empty($post_data['application_url'])) {
                update_post_meta($wp_post_id, '_application_url', $post_data['application_url']);
            }

            // Set taxonomies
            // Set location taxonomy
            if (!empty($post_data['location'])) {
                wp_set_object_terms($wp_post_id, $post_data['location'], 'recruiter_post_location');
            }

            // Set industry/sector taxonomy
            if (!empty($post_data['sector'])) {
                wp_set_object_terms($wp_post_id, $post_data['sector'], 'recruiter_post_industry');
            }

            // Set post type taxonomy (default to "Active Role" if not specified)
            $post_type_term = 'Active Role';
            if (!empty($post_data['seniority'])) {
                // Map seniority to post type if applicable
                $post_type_term = $post_data['seniority'];
            }
            wp_set_object_terms($wp_post_id, $post_type_term, 'recruiter_post_type');

            // Store external image URL if photo_url is external
            if (!empty($recruiter_data['photo_url'])) {
                $upload_dir = wp_upload_dir();
                if (strpos($recruiter_data['photo_url'], $upload_dir['baseurl']) === false) {
                    // It's an external URL, store it
                    update_post_meta($wp_post_id, '_recruiter_image_url', $recruiter_data['photo_url']);
                }
            }

            return $wp_post_id;
        }

        return false;
    }

    /**
     * Ensure CRM posts can store a separate jobs mirror post ID.
     */
    private function ensure_jobs_post_sync_column()
    {
        static $column_ready = false;

        if ($column_ready) {
            return;
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_posts';
        $column = $wpdb->get_var($wpdb->prepare(
            "SHOW COLUMNS FROM {$table} LIKE %s",
            'jobs_post_id'
        ));

        if ($column !== 'jobs_post_id') {
            $wpdb->query("ALTER TABLE {$table} ADD COLUMN jobs_post_id bigint(20) DEFAULT NULL AFTER wp_post_id");
        }

        $column_ready = true;
    }

    /**
     * Create or update the mirrored jobs CPT post used by the LinkedIn XML feed.
     */
    private function sync_to_jobs_post_cpt($crm_post_id, $post_data = null)
    {
        $crm_post_id = (int) $crm_post_id;
        if ($crm_post_id <= 0) {
            return false;
        }

        $this->ensure_jobs_post_sync_column();

        if (!$post_data) {
            $post_model = new SFFC_CRM_Post();
            $post_data = $post_model->get($crm_post_id);
        }

        if (empty($post_data) || !is_array($post_data)) {
            error_log('SFFC CRM Jobs Sync: CRM post not found for sync: ' . $crm_post_id);
            return false;
        }

        $publish_to_jobs = !isset($post_data['publish_to_jobs']) || (int) $post_data['publish_to_jobs'] === 1;

        global $wpdb;

        $role_title = sanitize_text_field($post_data['role_title'] ?? '');
        $content = wp_kses_post($post_data['content'] ?? '');
        $content_snippet = wp_trim_words(wp_strip_all_tags($content), 55, '...');

        $company = sanitize_text_field($post_data['company'] ?? '');
        if ($company === '') {
            $company = sanitize_text_field($post_data['recruiter_display_company'] ?? '');
        }
        if ($company === '') {
            $company = sanitize_text_field($post_data['recruiter_firm'] ?? '');
        }

        $location = sanitize_text_field($post_data['location'] ?? '');
        $city = sanitize_text_field($post_data['location_city'] ?? '');
        $country = sanitize_text_field($post_data['location_country'] ?? '');
        if (($city === '' || $country === '') && $location !== '') {
            $location_parts = array_map('trim', explode(',', $location));
            if ($city === '' && !empty($location_parts[0])) {
                $city = sanitize_text_field($location_parts[0]);
            }
            if ($country === '' && count($location_parts) > 1) {
                $country = sanitize_text_field(end($location_parts));
            }
        }

        $application_url = esc_url_raw((string) ($post_data['application_url'] ?? ''));
        $jobs_application_url = $application_url;
        $auto_submit_schema = is_array($post_data['auto_submit_schema'] ?? null) ? $post_data['auto_submit_schema'] : [];
        $auto_submit_provider = sanitize_key((string) ($post_data['auto_submit_provider'] ?? ($auto_submit_schema['provider'] ?? '')));
        $auto_submit_supported = !empty($post_data['auto_submit_supported']) || !empty($auto_submit_schema);
        $auto_submit_schema_status = sanitize_key((string) ($post_data['auto_submit_schema_status'] ?? ''));
        $industry = $this->format_crm_jobs_industry_label(sanitize_text_field($post_data['sector'] ?? ''));
        $salary_text = sanitize_text_field($post_data['salary_text'] ?? '');
        $currency = $this->infer_crm_jobs_currency($post_data);
        $base_salary = $this->build_crm_jobs_base_salary($post_data);
        $employment_type = $this->derive_crm_jobs_employment_type($post_data);
        $postal_code = sanitize_text_field($post_data['postal_code'] ?? '');

        $country = $this->normalize_crm_jobs_country_label($country);

        $existing_jobs_post_id = (int) ($post_data['jobs_post_id'] ?? 0);
        if ($existing_jobs_post_id <= 0) {
            $existing_jobs_post_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT jobs_post_id FROM {$wpdb->prefix}sffc_crm_posts WHERE id = %d",
                $crm_post_id
            ));
        }

        if ($existing_jobs_post_id <= 0) {
            $existing_jobs_post_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT pm.post_id
                 FROM {$wpdb->postmeta} pm
                 INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id
                 WHERE pm.meta_key = %s
                   AND pm.meta_value = %s
                   AND p.post_type = %s
                 ORDER BY pm.meta_id DESC
                 LIMIT 1",
                '_crm_post_id',
                (string) $crm_post_id,
                'jobs'
            ));
        }

        if (!$publish_to_jobs) {
            if ($existing_jobs_post_id > 0) {
                $this->delete_jobs_post_cpt($crm_post_id, true);
            }

            $wpdb->update(
                $wpdb->prefix . 'sffc_crm_posts',
                ['jobs_post_id' => null],
                ['id' => $crm_post_id],
                ['%d'],
                ['%d']
            );

            return false;
        }

        $wp_post_data = [
            'post_title' => $role_title !== '' ? $role_title : sprintf(__('CRM Job %d', 'senna-finance'), $crm_post_id),
            'post_content' => $content,
            'post_excerpt' => $content_snippet,
            'post_status' => 'draft',
            'post_type' => 'jobs',
        ];

        $existing_post = $existing_jobs_post_id > 0 ? get_post($existing_jobs_post_id) : null;
        if ($existing_post instanceof WP_Post && $existing_post->post_type === 'jobs') {
            $wp_post_data['ID'] = $existing_jobs_post_id;
            if (!empty($existing_post->post_name)) {
                $wp_post_data['post_name'] = $existing_post->post_name;
            }
            $jobs_post_id = wp_update_post($wp_post_data, true);
        } else {
            $slug_seed = sanitize_title(trim($role_title . ' ' . $company));
            $wp_post_data['post_name'] = ($slug_seed !== '' ? $slug_seed : 'crm-job') . '-' . $crm_post_id;
            $jobs_post_id = wp_insert_post($wp_post_data, true);
        }

        if (is_wp_error($jobs_post_id) || !$jobs_post_id) {
            error_log('SFFC CRM Jobs Sync: Failed to sync jobs post for CRM ' . $crm_post_id . ': ' . (is_wp_error($jobs_post_id) ? $jobs_post_id->get_error_message() : 'unknown error'));
            return false;
        }

        $this->sync_jobs_meta_value($jobs_post_id, '_crm_post_id', $crm_post_id);
        $this->sync_jobs_meta_value($jobs_post_id, 'hiringOrganization', $company);
        $this->sync_jobs_meta_value($jobs_post_id, 'jobDescription', $content);
        $this->sync_jobs_meta_value($jobs_post_id, 'applicationLink', $jobs_application_url);
        $this->sync_jobs_meta_value($jobs_post_id, 'newapplicationLink', $jobs_application_url);
        $this->sync_jobs_meta_value($jobs_post_id, 'posterEmail', 'support.team@joinsenna.com');
        $this->sync_jobs_meta_value($jobs_post_id, 'addressLocality', $city);
        $this->sync_jobs_meta_value($jobs_post_id, 'addressCountry', $country);
        $this->sync_jobs_meta_value($jobs_post_id, 'industry', $industry);
        $this->sync_jobs_meta_value($jobs_post_id, 'postalCode', $postal_code);
        $this->sync_jobs_meta_value($jobs_post_id, 'baseSalary', $base_salary);
        $this->sync_jobs_meta_value($jobs_post_id, 'currency', $currency);

        delete_post_meta($jobs_post_id, 'employmentType');
        if ($employment_type !== '') {
            add_post_meta($jobs_post_id, 'employmentType', $employment_type);
        }

        // Mirror a few generic fields as well so the post is usable beyond the XML feed.
        $this->sync_jobs_meta_value($jobs_post_id, '_company_name', $company);
        $this->sync_jobs_meta_value($jobs_post_id, '_job_title', $role_title);
        $this->sync_jobs_meta_value($jobs_post_id, '_job_location', $location);
        $this->sync_jobs_meta_value($jobs_post_id, '_application_url', $jobs_application_url);
        $this->sync_jobs_meta_value($jobs_post_id, '_salary_display', $salary_text);
        $this->sync_jobs_meta_value($jobs_post_id, '_sffc_auto_submit_supported', $auto_submit_supported ? '1' : '');
        $this->sync_jobs_meta_value($jobs_post_id, '_sffc_auto_submit_provider', $auto_submit_provider);
        $this->sync_jobs_meta_value($jobs_post_id, '_sffc_auto_submit_schema_status', $auto_submit_schema_status);
        $this->sync_jobs_meta_value($jobs_post_id, '_sffc_auto_submit_schema', !empty($auto_submit_schema) ? wp_json_encode($auto_submit_schema) : '');
        $this->sync_jobs_meta_value($jobs_post_id, '_sffc_greenhouse_board_token', sanitize_text_field((string) ($auto_submit_schema['board_token'] ?? '')));
        $this->sync_jobs_meta_value($jobs_post_id, '_sffc_greenhouse_job_id', sanitize_text_field((string) ($auto_submit_schema['job_id'] ?? '')));
        $this->sync_jobs_meta_value($jobs_post_id, 'sffc_company', $company);
        $this->sync_jobs_meta_value($jobs_post_id, 'sffc_actual_company', $company);
        $this->sync_jobs_meta_value($jobs_post_id, 'sffc_location', $location);
        $this->sync_jobs_meta_value($jobs_post_id, 'sffc_salary_display', $salary_text !== '' ? $salary_text : $base_salary);
        $this->sync_jobs_meta_value($jobs_post_id, 'sffc_job_type', $employment_type);
        $this->sync_jobs_meta_value($jobs_post_id, 'sffc_application_url', $jobs_application_url);
        $this->sync_crm_jobs_post_categories($jobs_post_id, $post_data, $industry);

        $wpdb->update(
            $wpdb->prefix . 'sffc_crm_posts',
            ['jobs_post_id' => (int) $jobs_post_id],
            ['id' => $crm_post_id],
            ['%d'],
            ['%d']
        );

        if (class_exists('SFFC_CRM_Shortcodes')) {
            SFFC_CRM_Shortcodes::invalidate_cv_match_job_posts_cache((int) $jobs_post_id);
        }

        $this->trigger_cv_match_role_notifications($crm_post_id, (int) $jobs_post_id, $post_data);

        return (int) $jobs_post_id;
    }

    /**
     * Create dashboard notifications as soon as a newly synced CRM role matches user signals.
     */
    private function trigger_cv_match_role_notifications($crm_post_id, $jobs_post_id, array $post_data)
    {
        $crm_post_id = (int) $crm_post_id;
        $jobs_post_id = (int) $jobs_post_id;
        if ($crm_post_id <= 0 || $jobs_post_id <= 0) {
            return;
        }

        if ((int) ($post_data['is_active'] ?? 1) !== 1 || (int) ($post_data['admin_approved'] ?? 0) !== 1) {
            return;
        }

        $posted_timestamp = !empty($post_data['posted_at']) ? strtotime((string) $post_data['posted_at']) : current_time('timestamp');
        if ($posted_timestamp > 0 && $posted_timestamp < (current_time('timestamp') - (14 * DAY_IN_SECONDS))) {
            return;
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-alert.php';

        $alert_model = new SFFC_CRM_Alert();
        $candidate_user_ids = $this->get_cv_match_role_notification_candidate_user_ids();
        if (empty($candidate_user_ids)) {
            return;
        }

        $role_title = sanitize_text_field($post_data['role_title'] ?? __('New finance role', 'senna-finance'));
        $company = sanitize_text_field($post_data['company'] ?? $post_data['recruiter_display_company'] ?? $post_data['recruiter_firm'] ?? __('MENA Careers network', 'senna-finance'));
        $location = sanitize_text_field($post_data['location'] ?? '');
        $action_url = add_query_arg(
            [
                'tab' => 'mailbox',
                'role' => $jobs_post_id,
            ],
            home_url('/terminal/')
        );

        $message = $location !== ''
            ? sprintf(__('%1$s at %2$s was just added in %3$s.', 'senna-finance'), $role_title, $company, $location)
            : sprintf(__('%1$s at %2$s was just added to the platform.', 'senna-finance'), $role_title, $company);

        foreach ($candidate_user_ids as $user_id) {
            $user_id = (int) $user_id;
            if ($user_id <= 0 || !$this->does_cv_match_role_notification_match_user($user_id, $post_data)) {
                continue;
            }

            if ($this->has_cv_match_role_notification($user_id, $jobs_post_id, $crm_post_id)) {
                continue;
            }

            $created = $alert_model->create_notification($user_id, [
                'type' => 'dashboard_role_match',
                'title' => __('New matching finance role added', 'senna-finance'),
                'message' => $message,
                'data' => [
                    'post_id' => $jobs_post_id,
                    'crm_post_id' => $crm_post_id,
                    'role_title' => $role_title,
                    'company' => $company,
                ],
                'action_url' => $action_url,
            ]);

            if (!is_wp_error($created)) {
                $this->clear_cv_match_notification_caches($user_id);
            }
        }
    }

    private function get_cv_match_role_notification_candidate_user_ids()
    {
        global $wpdb;

        $meta_keys = [
            'sffc_cv_match_studio_preferred_industry',
            'sffc_crm_target_roles',
            'sffc_crm_target_locations',
            'sffc_crm_target_sectors',
            'sffc_crm_open_to_types',
        ];

        $placeholders = implode(',', array_fill(0, count($meta_keys), '%s'));
        $sql = $wpdb->prepare(
            "SELECT DISTINCT user_id
             FROM {$wpdb->usermeta}
             WHERE meta_key IN ({$placeholders})
               AND meta_value IS NOT NULL
               AND meta_value != ''
             LIMIT 1000",
            $meta_keys
        );

        return array_map('intval', (array) $wpdb->get_col($sql));
    }

    private function does_cv_match_role_notification_match_user($user_id, array $post_data)
    {
        $haystack = $this->build_cv_match_role_notification_haystack($post_data);
        if ($haystack === '') {
            return false;
        }

        $score = 0;
        $preferred_industry = $this->normalize_cv_match_role_notification_industry((string) get_user_meta($user_id, 'sffc_cv_match_studio_preferred_industry', true));
        if ($preferred_industry !== '' && $preferred_industry !== 'other') {
            $score += $this->count_cv_match_role_notification_terms($haystack, $this->get_cv_match_role_notification_industry_terms($preferred_industry)) > 0 ? 4 : 0;
        }

        foreach ($this->get_cv_match_role_notification_user_meta_list($user_id, 'sffc_crm_target_roles') as $target_role) {
            if ($this->term_exists_in_cv_match_role_notification_haystack($haystack, $target_role)) {
                $score += 3;
                break;
            }
        }

        foreach ($this->get_cv_match_role_notification_user_meta_list($user_id, 'sffc_crm_target_sectors') as $target_sector) {
            if ($this->term_exists_in_cv_match_role_notification_haystack($haystack, $target_sector)) {
                $score += 2;
                break;
            }
        }

        foreach ($this->get_cv_match_role_notification_user_meta_list($user_id, 'sffc_crm_target_locations') as $target_location) {
            if ($this->term_exists_in_cv_match_role_notification_haystack($haystack, $target_location)) {
                $score += 1;
                break;
            }
        }

        foreach ($this->get_cv_match_role_notification_user_meta_list($user_id, 'sffc_crm_open_to_types') as $open_to_type) {
            $open_to_type = sanitize_key($open_to_type);
            if ($open_to_type === 'internships' && preg_match('/\b(intern|internship|summer|off[\s-]?cycle|placement)\b/i', $haystack)) {
                $score += 2;
                break;
            }
            if ($open_to_type === 'graduate_roles' && preg_match('/\b(graduate|trainee|entry[\s-]?level)\b/i', $haystack)) {
                $score += 2;
                break;
            }
            if ($open_to_type === 'analyst_positions' && preg_match('/\b(analyst|junior|associate)\b/i', $haystack)) {
                $score += 2;
                break;
            }
        }

        return $score >= 3;
    }

    private function build_cv_match_role_notification_haystack(array $post_data)
    {
        $parts = [
            $post_data['role_title'] ?? '',
            $post_data['company'] ?? '',
            $post_data['recruiter_display_company'] ?? '',
            $post_data['recruiter_firm'] ?? '',
            $post_data['location'] ?? '',
            $post_data['location_city'] ?? '',
            $post_data['location_country'] ?? '',
            $post_data['sector'] ?? '',
            $post_data['industry'] ?? '',
            $post_data['seniority'] ?? '',
            $post_data['content_snippet'] ?? '',
            $post_data['content'] ?? '',
            $this->flatten_cv_match_role_notification_keywords($post_data['keywords'] ?? ''),
        ];

        $text = strtolower(wp_strip_all_tags(implode(' ', array_map('strval', $parts))));
        $text = str_replace(['_', '-', '/', '&'], [' ', ' ', ' ', ' and '], $text);
        $text = preg_replace('/\s+/', ' ', $text);

        return trim((string) $text);
    }

    private function flatten_cv_match_role_notification_keywords($keywords)
    {
        if (is_array($keywords)) {
            $terms = [];
            foreach ($keywords as $keyword) {
                if (is_array($keyword)) {
                    $terms[] = (string) ($keyword['label'] ?? $keyword['term'] ?? $keyword['keyword'] ?? $keyword['name'] ?? '');
                } else {
                    $terms[] = (string) $keyword;
                }
            }
            return implode(' ', $terms);
        }

        $keywords = (string) $keywords;
        $decoded = json_decode($keywords, true);
        if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
            return $this->flatten_cv_match_role_notification_keywords($decoded);
        }

        return $keywords;
    }

    private function get_cv_match_role_notification_user_meta_list($user_id, $meta_key)
    {
        $value = get_user_meta($user_id, $meta_key, true);
        if (is_array($value)) {
            return array_values(array_filter(array_map('trim', array_map('strval', $value))));
        }

        $value = trim((string) $value);
        if ($value === '') {
            return [];
        }

        $decoded = json_decode($value, true);
        if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
            return array_values(array_filter(array_map('trim', array_map('strval', $decoded))));
        }

        $maybe_serialized = maybe_unserialize($value);
        if (is_array($maybe_serialized)) {
            return array_values(array_filter(array_map('trim', array_map('strval', $maybe_serialized))));
        }

        return array_values(array_filter(array_map('trim', preg_split('/[,;\n]+/', $value) ?: [])));
    }

    private function normalize_cv_match_role_notification_industry($value)
    {
        $value = strtolower(trim((string) $value));
        $value = str_replace(['-', '/', '&'], [' ', ' ', ' and '], $value);
        $value = preg_replace('/\s+/', ' ', str_replace('_', ' ', (string) $value));
        $value = trim((string) $value);

        $map = [
            'ib' => 'investment_banking',
            'investment bank' => 'investment_banking',
            'investment banking' => 'investment_banking',
            'investment_banking' => 'investment_banking',
            'pe' => 'private_equity',
            'private equity' => 'private_equity',
            'private_equity' => 'private_equity',
            'am' => 'asset_management',
            'asset management' => 'asset_management',
            'asset mgmt' => 'asset_management',
            'asset mgt' => 'asset_management',
            'asset_management' => 'asset_management',
            'hedge fund' => 'hedge_fund',
            'hedge funds' => 'hedge_fund',
            'hedge_fund' => 'hedge_fund',
            'finance' => 'finance',
            'consulting' => 'consulting',
            'strategy consulting' => 'consulting',
            'other' => 'other',
        ];

        return (string) ($map[$value] ?? '');
    }

    private function get_cv_match_role_notification_industry_terms($industry = '')
    {
        $terms = [
            'investment_banking' => ['investment banking', 'investment bank', 'm&a', 'mergers and acquisitions', 'corporate finance', 'capital markets', 'leveraged finance', 'ibd', 'analyst'],
            'private_equity' => ['private equity', 'pe', 'buyout', 'portfolio company', 'deal sourcing', 'investment team', 'valuation', 'lbo'],
            'asset_management' => ['asset management', 'investment management', 'portfolio management', 'fund management', 'equity research', 'fixed income', 'markets'],
            'hedge_fund' => ['hedge fund', 'long short', 'public markets', 'trading', 'equities', 'macro', 'quant', 'portfolio'],
            'finance' => ['finance', 'financial analysis', 'corporate finance', 'excel', 'vba', 'accounting', 'treasury', 'risk', 'trading', 'p&l'],
            'consulting' => ['consulting', 'strategy', 'consultant', 'case study', 'market sizing', 'commercial due diligence', 'operations'],
        ];

        if ($industry !== '') {
            return $terms[$industry] ?? [];
        }

        return $terms;
    }

    private function count_cv_match_role_notification_terms($haystack, array $terms)
    {
        $matches = 0;
        foreach ($terms as $term) {
            if ($this->term_exists_in_cv_match_role_notification_haystack($haystack, $term)) {
                $matches++;
            }
        }

        return $matches;
    }

    private function term_exists_in_cv_match_role_notification_haystack($haystack, $term)
    {
        $term = strtolower(trim((string) $term));
        if ($term === '') {
            return false;
        }

        $term = str_replace(['_', '-', '/', '&'], [' ', ' ', ' ', ' and '], $term);
        $term = preg_replace('/\s+/', ' ', $term);
        $term = trim((string) $term);

        return $term !== '' && strpos((string) $haystack, $term) !== false;
    }

    private function has_cv_match_role_notification($user_id, $jobs_post_id, $crm_post_id)
    {
        global $wpdb;

        $table = $wpdb->prefix . 'sffc_crm_notifications';
        $since = gmdate('Y-m-d H:i:s', current_time('timestamp') - (7 * DAY_IN_SECONDS));
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT data FROM {$table}
             WHERE user_id = %d
               AND type = %s
               AND created_at >= %s
             ORDER BY id DESC
             LIMIT 50",
            (int) $user_id,
            'dashboard_role_match',
            $since
        ), ARRAY_A);

        foreach ((array) $rows as $row) {
            $data = !empty($row['data']) ? json_decode((string) $row['data'], true) : [];
            if ((string) ($data['post_id'] ?? '') === (string) $jobs_post_id || (string) ($data['crm_post_id'] ?? '') === (string) $crm_post_id) {
                return true;
            }
        }

        return false;
    }

    private function clear_cv_match_notification_caches($user_id)
    {
        $user_id = (int) $user_id;
        if ($user_id > 0) {
            delete_transient('sffc_crm_dash_topbar_counts_' . $user_id);
            delete_transient('sffc_crm_dash_inbox_' . $user_id . '_default');
            delete_transient('sffc_crm_dash_notifications_seed_' . $user_id);
        }

        global $wpdb;
        $like = $wpdb->esc_like('_transient_sffc_crm_dash_notifications_') . '%';
        $timeout_like = $wpdb->esc_like('_transient_timeout_sffc_crm_dash_notifications_') . '%';
        $wpdb->query($wpdb->prepare(
            "DELETE FROM {$wpdb->options} WHERE option_name LIKE %s OR option_name LIKE %s",
            $like,
            $timeout_like
        ));
    }

    public function handle_pregenerate_jobs_intel($jobs_post_id, $force = 0)
    {
        $jobs_post_id = (int) $jobs_post_id;
        if ($jobs_post_id <= 0) {
            return;
        }

        if (!class_exists('SFFC_CRM_Shortcodes')) {
            return;
        }

        $shortcodes = SFFC_CRM_Shortcodes::get_instance();
        if (method_exists($shortcodes, 'pregenerate_reddit_job_intel')) {
            $shortcodes->pregenerate_reddit_job_intel($jobs_post_id, !empty($force));
        }
    }

    /**
     * Remove the mirrored jobs CPT post for a CRM row.
     */
    private function delete_jobs_post_cpt($crm_post_id, $force_delete = false)
    {
        $crm_post_id = (int) $crm_post_id;
        if ($crm_post_id <= 0) {
            return false;
        }

        $this->ensure_jobs_post_sync_column();

        global $wpdb;
        $jobs_post_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT jobs_post_id FROM {$wpdb->prefix}sffc_crm_posts WHERE id = %d",
            $crm_post_id
        ));

        if ($jobs_post_id <= 0) {
            $jobs_post_id = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT pm.post_id
                 FROM {$wpdb->postmeta} pm
                 INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id
                 WHERE pm.meta_key = %s
                   AND pm.meta_value = %s
                   AND p.post_type = %s
                 ORDER BY pm.meta_id DESC
                 LIMIT 1",
                '_crm_post_id',
                (string) $crm_post_id,
                'jobs'
            ));
        }

        if ($jobs_post_id <= 0) {
            return true;
        }

        $deleted = $force_delete ? wp_delete_post($jobs_post_id, true) : wp_trash_post($jobs_post_id);
        if ($deleted) {
            if (class_exists('SFFC_CRM_Shortcodes')) {
                SFFC_CRM_Shortcodes::invalidate_cv_match_job_posts_cache((int) $jobs_post_id);
            }
            $wpdb->update(
                $wpdb->prefix . 'sffc_crm_posts',
                ['jobs_post_id' => null],
                ['id' => $crm_post_id],
                ['%d'],
                ['%d']
            );
            return true;
        }

        return false;
    }

    private function sync_jobs_meta_value($post_id, $meta_key, $value)
    {
        if ($value === null || $value === '') {
            delete_post_meta($post_id, $meta_key);
            return;
        }

        update_post_meta($post_id, $meta_key, $value);
    }

    private function crm_jobs_application_url_contains_email($value)
    {
        $value = trim((string) $value);
        if ($value === '') {
            return false;
        }

        $decoded = html_entity_decode(rawurldecode($value), ENT_QUOTES, 'UTF-8');
        if (stripos($decoded, 'mailto:') === 0) {
            return true;
        }

        return (bool) preg_match('/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i', $decoded);
    }

    private function sync_crm_jobs_post_categories($jobs_post_id, array $post_data, $fallback_industry = '')
    {
        $jobs_post_id = (int) $jobs_post_id;
        if ($jobs_post_id <= 0) {
            return;
        }

        $labels = $this->build_crm_jobs_category_labels($post_data, $fallback_industry);
        if (empty($labels)) {
            return;
        }

        $category_ids = [];
        foreach ($labels as $label) {
            $label = trim((string) $label);
            if ($label === '') {
                continue;
            }

            $term = get_term_by('name', $label, 'category');
            if (!$term || is_wp_error($term)) {
                $term_result = wp_insert_term($label, 'category');
                if (is_wp_error($term_result) || empty($term_result['term_id'])) {
                    continue;
                }
                $category_ids[] = (int) $term_result['term_id'];
                continue;
            }

            $category_ids[] = (int) $term->term_id;
        }

        $category_ids = array_values(array_unique(array_filter($category_ids)));
        if (!empty($category_ids)) {
            wp_set_post_categories($jobs_post_id, $category_ids, false);
        }
    }

    private function build_crm_jobs_category_labels(array $post_data, $fallback_industry = '')
    {
        $labels = [];
        $industry_values = $post_data['industry'] ?? [];

        if (!is_array($industry_values)) {
            $industry_values = $industry_values !== '' ? [$industry_values] : [];
        }

        foreach ($industry_values as $value) {
            $label = $this->format_crm_jobs_category_label($value);
            if ($label !== '') {
                $labels[] = $label;
            }
        }

        if (empty($labels) && !empty($post_data['sector'])) {
            $sector_label = $this->format_crm_jobs_industry_label((string) $post_data['sector']);
            if ($sector_label !== '') {
                $labels[] = $sector_label;
            }
        }

        if (empty($labels) && $fallback_industry !== '') {
            $labels[] = trim((string) $fallback_industry);
        }

        return array_values(array_unique(array_filter($labels)));
    }

