    private function build_crm_jobs_base_salary(array $post_data)
    {
        $salary_min = isset($post_data['salary_min']) ? (int) $post_data['salary_min'] : 0;
        $salary_max = isset($post_data['salary_max']) ? (int) $post_data['salary_max'] : 0;

        if ($salary_min > 0 || $salary_max > 0) {
            if ($salary_min <= 0) {
                $salary_min = $salary_max;
            }
            if ($salary_max <= 0) {
                $salary_max = $salary_min;
            }

            if ($salary_min >= 1000 || $salary_max >= 1000) {
                $low = (int) round($salary_min / 1000);
                $high = (int) round($salary_max / 1000);
                return $low === $high ? $low . 'k' : $low . 'k-' . $high . 'k';
            }

            return $salary_min === $salary_max ? (string) $salary_min : $salary_min . '-' . $salary_max;
        }

        $salary_text = sanitize_text_field($post_data['salary_text'] ?? '');
        if ($salary_text === '') {
            return '';
        }

        if (preg_match_all('/(\d[\d,]*)(?:\s*([kK]))?/', $salary_text, $matches, PREG_SET_ORDER)) {
            $parts = [];
            foreach (array_slice($matches, 0, 2) as $match) {
                $numeric_value = (int) str_replace(',', '', $match[1]);
                $suffix = !empty($match[2]) ? 'k' : '';

                if ($suffix === '' && $numeric_value >= 1000) {
                    $parts[] = (int) round($numeric_value / 1000) . 'k';
                } else {
                    $parts[] = $numeric_value . $suffix;
                }
            }

            if (!empty($parts)) {
                return implode('-', $parts);
            }
        }

        return '';
    }

    private function infer_crm_jobs_currency(array $post_data)
    {
        $currency = strtoupper(trim((string) ($post_data['salary_currency'] ?? '')));
        if ($currency !== '') {
            return $currency;
        }

        $salary_text = (string) ($post_data['salary_text'] ?? '');
        if (strpos($salary_text, '£') !== false) {
            return 'GBP';
        }
        if (strpos($salary_text, '€') !== false) {
            return 'EUR';
        }
        if (strpos($salary_text, 'AED') !== false) {
            return 'AED';
        }
        if (strpos($salary_text, '$') !== false) {
            return 'USD';
        }

        return 'USD';
    }

