    /**
     * Set recruiter image from URL
     */
    private function set_recruiter_image_from_url($post_id, $image_url)
    {
        // Check if it's already a local attachment URL
        $upload_dir = wp_upload_dir();
        if (strpos($image_url, $upload_dir['baseurl']) !== false) {
            // It's already a local image, find the attachment ID
            $attachment_id = attachment_url_to_postid($image_url);
            if ($attachment_id) {
                update_post_meta($post_id, '_recruiter_image_id', $attachment_id);
            }
        }
    }

    /**
     * Handle CSV import
     */
    private function handle_csv_import()
    {
        if (!isset($_FILES['import_file']) || $_FILES['import_file']['error'] !== UPLOAD_ERR_OK) {
            wp_redirect(add_query_arg('error', 'upload', admin_url('admin.php?page=sffc-crm-import')));
            exit;
        }

        $file = $_FILES['import_file']['tmp_name'];
        $auto_approve = isset($_POST['auto_approve']);
        $sync_to_cpt = isset($_POST['sync_to_cpt']);
        $should_sync = $sync_to_cpt || $auto_approve;
        global $wpdb;

        $handle = fopen($file, 'r');
        if (!$handle) {
            wp_redirect(add_query_arg('error', 'read', admin_url('admin.php?page=sffc-crm-import')));
            exit;
        }

        $headers = fgetcsv($handle);
        $headers = array_map('strtolower', $headers);
        $headers = array_map('trim', $headers);

        $post_model = new SFFC_CRM_Post();
        $recruiter_model = new SFFC_CRM_Recruiter();

        $imported = 0;
        $skipped = 0;

        while (($row = fgetcsv($handle)) !== false) {
            $data = array_combine($headers, $row);

            if (!$data) {
                $skipped++;
                continue;
            }

            if (empty($data['role_title']) || empty($data['content'])) {
                $skipped++;
                continue;
            }

            // Get or create recruiter
            $recruiter_fields = [
                'id' => !empty($data['recruiter_id']) ? intval($data['recruiter_id']) : null,
                'name' => isset($data['recruiter_name']) ? trim($data['recruiter_name']) : '',
                'firm' => isset($data['recruiter_firm']) ? trim($data['recruiter_firm']) : '',
                'title' => isset($data['recruiter_title']) ? trim($data['recruiter_title']) : '',
                'email' => isset($data['recruiter_email']) ? trim($data['recruiter_email']) : '',
                'linkedin_url' => isset($data['recruiter_linkedin']) ? trim($data['recruiter_linkedin']) : '',
                'photo_url' => isset($data['recruiter_photo_url']) ? trim($data['recruiter_photo_url']) : '',
            ];

            $recruiter_id = $this->resolve_recruiter_for_import($recruiter_model, $recruiter_fields);

            $location = $data['location'] ?? '';
            $location_parts = array_map('trim', explode(',', $location));

            $post_data = [
                'recruiter_id' => $recruiter_id,
                'role_title' => $data['role_title'],
                'company' => $data['company'] ?? '',
                'location' => $location,
                'location_city' => $location_parts[0] ?? '',
                'location_country' => $location_parts[1] ?? '',
                'sector' => $data['sector'] ?? '',
                'seniority' => $data['seniority'] ?? '',
                'experience_years' => $data['experience_years'] ?? '',
                'salary_text' => $data['salary_text'] ?? '',
                'content' => $data['content'],
                'source_url' => $data['source_url'] ?? '',
                'application_url' => $data['application_url'] ?? '',
                'is_featured' => !empty($data['is_featured']) ? 1 : 0,
                'source' => 'import',
                'admin_approved' => $auto_approve ? 1 : 0,
                'recruiter_display_name' => $data['recruiter_display_name'] ?? '',
                'recruiter_display_company' => $data['recruiter_display_company'] ?? '',
            ];

            $crm_post_id = $post_model->create($post_data);

            if (!$crm_post_id) {
                $skipped++;
                continue;
            }

            if ($should_sync) {
                $recruiter_profile = null;
                if ($recruiter_id) {
                    $recruiter_profile = $recruiter_model->get($recruiter_id);
                }

                if (!$recruiter_profile) {
                    $recruiter_profile = [
                        'name' => $recruiter_fields['name'] ?? '',
                        'title' => $recruiter_fields['title'] ?? '',
                        'firm' => $recruiter_fields['firm'] ?? '',
                        'email' => $recruiter_fields['email'] ?? '',
                        'linkedin_url' => $recruiter_fields['linkedin_url'] ?? '',
                        'photo_url' => $recruiter_fields['photo_url'] ?? '',
                    ];
                }

                $wp_post_id = $this->sync_to_recruiter_post_cpt($crm_post_id, $post_data, $recruiter_profile);

                if ($wp_post_id) {
                    $wpdb->update(
                        $wpdb->prefix . 'sffc_crm_posts',
                        ['wp_post_id' => $wp_post_id],
                        ['id' => $crm_post_id],
                        ['%d'],
                        ['%d']
                    );
                }
            }

            $this->sync_to_jobs_post_cpt($crm_post_id, $post_data);

            $imported++;
        }

        fclose($handle);

        wp_redirect(add_query_arg([
            'imported' => $imported,
            'skipped' => $skipped,
        ], admin_url('admin.php?page=sffc-crm-import')));
        exit;
    }

    /**
     * Resolve recruiter assignment for CSV import rows
     */
    private function resolve_recruiter_for_import($recruiter_model, array $fields)
    {
        global $wpdb;

        $fields = array_map(function ($value) {
            return is_string($value) ? trim($value) : $value;
        }, $fields);

        // Match or create by explicit ID first
        if (!empty($fields['id'])) {
            $existing = $recruiter_model->get($fields['id']);
            if ($existing) {
                $this->maybe_update_recruiter($recruiter_model, $existing['id'], $fields);
                return (int) $existing['id'];
            }

            if (!empty($fields['name'])) {
                $insert_data = $this->prepare_recruiter_insert_data($fields);
                $insert_data['id'] = $fields['id'];
                return $recruiter_model->create($insert_data);
            }
        }

        // Try to match by name + firm
        if (!empty($fields['name']) && !empty($fields['firm'])) {
            $existing_id = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$wpdb->prefix}sffc_crm_recruiters WHERE name = %s AND firm = %s",
                $fields['name'],
                $fields['firm']
            ));

            if ($existing_id) {
                $this->maybe_update_recruiter($recruiter_model, $existing_id, $fields);
                return (int) $existing_id;
            }
        }

        // Create a new recruiter if we have enough info
        if (!empty($fields['name'])) {
            $insert_data = $this->prepare_recruiter_insert_data($fields);
            if (!empty($insert_data)) {
                return $recruiter_model->create($insert_data);
            }
        }

        return null;
    }

    /**
     * Build array of recruiter fields for insert
     */
    private function prepare_recruiter_insert_data(array $fields)
    {
        $allowed = ['id', 'name', 'firm', 'title', 'email', 'linkedin_url', 'photo_url'];
        $insert = [];

        foreach ($allowed as $key) {
            if (isset($fields[$key]) && $fields[$key] !== '' && $fields[$key] !== null) {
                $insert[$key] = $fields[$key];
            }
        }

        if (!empty($insert)) {
            $insert['data_source'] = $insert['data_source'] ?? 'post_import';
        }

        return $insert;
    }

    /**
     * Update recruiter profile if new details provided in CSV
     */
    private function maybe_update_recruiter($recruiter_model, $recruiter_id, array $fields)
    {
        $update_fields = [];
        foreach (['name', 'firm', 'title', 'email', 'linkedin_url', 'photo_url'] as $key) {
            if (!empty($fields[$key])) {
                $update_fields[$key] = $fields[$key];
            }
        }

        if (!empty($update_fields)) {
            $recruiter_model->update($recruiter_id, $update_fields);
        }
    }

    /**
     * Map a CRM post + recruiter into HR Outreach record data
     */
    private function sync_saved_crm_post_recruiter_to_hr_outreach($post_id)
    {
        $post_id = (int) $post_id;
        if ($post_id <= 0) {
            return 0;
        }

        try {
            if (!class_exists('SFFC_CRM_HR_Outreach')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-outreach.php';
            }
            if (!class_exists('SFFC_CRM_Recruiter')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-recruiter.php';
            }

            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get($post_id);
            if (!$post) {
                return 0;
            }

            $recruiter = null;
            if (!empty($post['recruiter_id'])) {
                $recruiter_model = new SFFC_CRM_Recruiter();
                $recruiter = $recruiter_model->get((int) $post['recruiter_id']);
            }

            $hr_data = $this->map_post_to_hr_outreach_data($post, $recruiter);
            if (is_wp_error($hr_data)) {
                error_log('SFFC CRM Admin - HR outreach auto-sync skipped: ' . $hr_data->get_error_message());
                return 0;
            }
            $hr_data['source_context'] = 'active_recruiter';

            $hr_model = new SFFC_CRM_HR_Outreach();
            $existing_id = $this->locate_existing_hr_outreach_entry(
                $hr_data['company_name'],
                $hr_data['contact_email'],
                $hr_data['contact_name'],
                $hr_data['contact_linkedin'],
                false
            );

            if ($existing_id) {
                $existing_entry = $hr_model->get($existing_id);
                if ($existing_entry) {
                    $hr_data = $this->merge_hr_outreach_entry($existing_entry, $post, $hr_data);
                }
                $hr_data['id'] = $existing_id;
            }

            $result = $hr_model->save($hr_data);
            if (is_wp_error($result)) {
                error_log('SFFC CRM Admin - HR outreach auto-sync failed: ' . $result->get_error_message());
                return 0;
            }

            return (int) $result;
        } catch (Throwable $exception) {
            error_log('SFFC CRM Admin - HR outreach auto-sync exception: ' . $exception->getMessage());
            return 0;
        }
    }

    private function map_post_to_hr_outreach_data(array $post, $recruiter = null)
    {
        $recruiter = is_array($recruiter) ? $recruiter : [];
        $company_name = trim($post['company'] ?? '');

        if (!$company_name && !empty($post['recruiter_display_company'])) {
            $company_name = trim($post['recruiter_display_company']);
        }

        if (!$company_name && !empty($recruiter['default_company'])) {
            $company_name = trim($recruiter['default_company']);
        }

        if (!$company_name && !empty($recruiter['firm'])) {
            $company_name = trim($recruiter['firm']);
        }

        if (!$company_name) {
            $company_name = sprintf(__('CRM Post #%d', 'senna-finance'), $post['id']);
        }

        $contact_name = $recruiter['name'] ?? $post['recruiter_name'] ?? $post['recruiter_display_name'] ?? '';
        if (!$contact_name) {
            $contact_name = sprintf(__('%s Talent Team', 'senna-finance'), $company_name);
        }

        $contact_title = $recruiter['title'] ?? $post['recruiter_title'] ?? __('Talent Lead', 'senna-finance');
        $contact_email = $recruiter['email'] ?? $post['recruiter_email'] ?? '';
        $contact_phone = $recruiter['phone'] ?? '';
        $contact_linkedin = $recruiter['linkedin_url'] ?? $post['recruiter_linkedin'] ?? '';
        $contact_photo = $recruiter['photo_url'] ?? $post['recruiter_photo'] ?? '';

        $location = $post['location'] ?? '';
        if (!$location && !empty($post['location_city']) && !empty($post['location_country'])) {
            $location = $post['location_city'] . ', ' . $post['location_country'];
        } elseif (!$location && !empty($post['location_city'])) {
            $location = $post['location_city'];
        }

        $role_focus = '';
        if (!empty($post['content'])) {
            $role_focus = wp_trim_words(wp_strip_all_tags($post['content']), 55, '...');
        } elseif (!empty($post['role_title'])) {
            $role_focus = $post['role_title'];
        }

        $team_contacts = [];
        if (!empty($post['team_contacts']) && is_array($post['team_contacts'])) {
            foreach ($post['team_contacts'] as $team_contact) {
                if (empty($team_contact['name'])) {
                    continue;
                }
                $team_contacts[] = [
                    'name' => sanitize_text_field($team_contact['name']),
                    'title' => sanitize_text_field($team_contact['title'] ?? ''),
                    'email' => sanitize_email($team_contact['email'] ?? ''),
                    'phone' => sanitize_text_field($team_contact['phone'] ?? ''),
                    'linkedin' => esc_url_raw($team_contact['linkedin'] ?? ''),
                ];
            }
        }

        $notes = $this->build_hr_outreach_notes($post);
        $capture_note = $this->build_hr_capture_note($post);
        $last_hire_message = $this->build_last_hire_proof_message($post);
        $industry_terms = $this->infer_industries_from_post($post);
        $skill_terms = $this->build_hr_skill_tags($post);
        $program_types = $this->infer_program_types_from_post($post);
        $hiring_flags = $this->infer_hr_hiring_flags_from_post($post);
        $prep_urls = $this->map_post_prep_urls_for_hr_outreach($post);

        return [
            'company_name' => $company_name,
            'company_logo' => $post['company_logo'] ?? ($recruiter['default_company_logo'] ?? ''),
            'company_url' => $post['source_url'] ?? ($post['application_url'] ?? ''),
            'location' => $location,
            'regions' => $post['location_country'] ?? '',
            'industry' => $industry_terms,
            'program_types' => $program_types,
            'process' => $this->normalize_hr_process_terms($post['application_process'] ?? []),
            'skills' => $skill_terms,
            'hire_interns' => $hiring_flags['hire_interns'],
            'hire_graduates' => $hiring_flags['hire_graduates'],
            'hire_analysts' => $hiring_flags['hire_analysts'],
            'hire_associates' => $hiring_flags['hire_associates'],
            'hire_seniors' => $hiring_flags['hire_seniors'],
            'hire_private_equity_candidates' => $hiring_flags['hire_private_equity_candidates'],
            'hire_expats' => $hiring_flags['hire_expats'],
            'hire_cfa_holders' => $hiring_flags['hire_cfa_holders'],
            'hire_mba' => $hiring_flags['hire_mba'],
            'hire_visa_sponsorship' => $hiring_flags['hire_visa_sponsorship'],
            'hire_arabic_speakers' => $hiring_flags['hire_arabic_speakers'],
            'hire_bilingual' => $hiring_flags['hire_bilingual'],
            'hire_trainee' => $hiring_flags['hire_trainee'],
            'hire_placement' => $hiring_flags['hire_placement'],
            'role_focus' => $role_focus,
            'last_hire_proof' => $last_hire_message,
            'interview_questions_url' => $prep_urls['interview_questions_url'],
            'cv_template_url' => $prep_urls['cv_template_url'],
            'cover_letter_url' => $prep_urls['cover_letter_url'],
            'company_intel_url' => $post['company_intel_url'] ?? ($post['source_url'] ?? ''),
            'contact_name' => $contact_name,
            'contact_title' => $contact_title,
            'contact_email' => $contact_email,
            'contact_phone' => $contact_phone,
            'contact_linkedin' => $contact_linkedin,
            'contact_photo' => $contact_photo,
            'team_contacts' => $team_contacts,
            'notes' => $this->combine_notes_with_capture($notes, $capture_note),
            'source_context' => 'active_recruiter',
        ];
    }

    /**
     * Sanitize multi-value checkbox style inputs for HR outreach schema
     */
    private function sanitize_hr_multi_values($values)
    {
        $clean = [];

        foreach ((array) $values as $value) {
            if (is_array($value)) {
                if (isset($value['value'])) {
                    $value = $value['value'];
                } elseif (isset($value['label'])) {
                    $value = $value['label'];
                } else {
                    continue;
                }
            }

            if ($value === null || $value === '') {
                continue;
            }

            $key = sanitize_key($value);
            if ($key === '') {
                continue;
            }

            $clean[] = $key;
        }

        return array_values(array_unique($clean));
    }

    /**
     * Human-friendly log of what was archived and when
     */
    private function build_hr_capture_note(array $post)
    {
        $captured_on = !empty($post['posted_at'])
            ? date_i18n(get_option('date_format'), strtotime($post['posted_at']))
            : date_i18n(get_option('date_format'));

        return sprintf(
            __('Captured from CRM post #%1$d on %2$s.', 'senna-finance'),
            $post['id'],
            $captured_on
        );
    }

    /**
     * Format the hiring proof message for contacts captured from active CRM posts
     */
    private function build_last_hire_proof_message(array $post)
    {
        $role = !empty($post['role_title']) ? $post['role_title'] : __('Talent role', 'senna-finance');
        $raw_date = $post['posted_at'] ?? $post['created_at'] ?? current_time('mysql');
        $date_label = date_i18n('F Y', strtotime($raw_date));

        return sprintf(__('Active hiring signal: %1$s - %2$s', 'senna-finance'), $role, $date_label);
    }

    /**
     * Combine summary + capture note while avoiding blank newlines
     */
    private function combine_notes_with_capture($summary, $capture_note)
    {
        $chunks = array_filter([trim($summary), trim($capture_note)]);
        return implode("\n\n", $chunks);
    }

    /**
     * Merge multi-select term sets preserving uniqueness
     */
    private function merge_term_sets($existing, $incoming)
    {
        $existing_terms = is_array($existing)
            ? $existing
            : array_filter(array_map('trim', explode(',', (string) $existing)));
        $incoming_terms = is_array($incoming)
            ? $incoming
            : array_filter(array_map('trim', explode(',', (string) $incoming)));

        $existing_terms = array_map('sanitize_key', $existing_terms);
        $incoming_terms = array_map('sanitize_key', $incoming_terms);

        $merged = array_values(array_unique(array_merge($incoming_terms, $existing_terms)));
        return array_filter($merged);
    }

    /**
     * Infer industry tags from post sector/keywords
     */
    private function infer_industries_from_post(array $post)
    {
        $terms = [];

        if (!empty($post['sector'])) {
            $terms[] = $post['sector'];
        }

        $keyword_terms = $this->extract_keyword_terms_from_post($post);
        $text = strtolower(implode(' ', $keyword_terms) . ' ' . ($post['content'] ?? '') . ' ' . ($post['role_title'] ?? '') . ' ' . ($post['company'] ?? '') . ' ' . ($post['sector'] ?? ''));
        $industry_map = [
            'private equity' => 'private_equity',
            'private-equity' => 'private_equity',
            'investment banking' => 'investment_banking',
            'investment-banking' => 'investment_banking',
            'ibd' => 'investment_banking',
            'm&a' => 'investment_banking',
            'mergers and acquisitions' => 'investment_banking',
            'venture capital' => 'venture_capital',
            'venture-capital' => 'venture_capital',
            ' vc ' => 'venture_capital',
            'asset management' => 'asset_management',
            'investment management' => 'investment_management',
            'wealth management' => 'wealth_management',
            'hedge fund' => 'hedge_funds',
            'family office' => 'family_office',
            'consulting' => 'consulting',
            'strategy consultant' => 'consulting',
            'corporate finance' => 'corporate_finance',
            'accounting' => 'accounting',
            'audit' => 'accounting',
            'technology' => 'technology',
            'fintech' => 'fintech',
            'boutique' => 'boutique',
            'real estate' => 'real_estate',
            'infrastructure' => 'infrastructure',
            'capital markets' => 'capital_markets'
        ];

        foreach ($industry_map as $needle => $slug) {
            if ($needle && strpos($text, $needle) !== false) {
                $terms[] = $slug;
            }
        }

        return $this->sanitize_hr_multi_values($terms);
    }

    /**
     * Build skill tags combining structured skills + keywords
     */
    private function build_hr_skill_tags(array $post)
    {
        $skills = $this->sanitize_hr_multi_values($post['skills_mentioned'] ?? []);
        $keywords = $this->extract_keyword_terms_from_post($post);
        $skills = array_merge($skills, $keywords);
        $haystack = strtolower(wp_strip_all_tags(implode(' ', array_filter([
            $post['role_title'] ?? '',
            $post['sector'] ?? '',
            $post['content'] ?? '',
            implode(' ', $keywords),
        ]))));

        $skill_map = [
            'financial analysis' => ['financial_analysis', 'finance analysis'],
            'equity research' => ['equity_research'],
            'financial modeling' => ['financial_modeling', 'financial modelling', 'modeling', 'modelling'],
            'valuation' => ['valuation', 'dcf', 'comps', 'precedents'],
            'excel' => ['excel', 'advanced excel'],
            'powerpoint' => ['powerpoint', 'presentation', 'pitchbook', 'pitch book'],
            'risk analysis' => ['risk analysis', 'market risk', 'credit risk'],
            'portfolio management' => ['portfolio management'],
            'due diligence' => ['due diligence'],
            'm&a analysis' => ['m&a', 'mergers and acquisitions'],
            'lbo modeling' => ['lbo'],
            'credit analysis' => ['credit analysis'],
            'market research' => ['market research'],
            'bloomberg terminal' => ['bloomberg'],
            'capital iq' => ['capital iq', 'cap iq'],
            'factset' => ['factset'],
            'pitchbook' => ['pitchbook', 'pitch book'],
            'accounting knowledge' => ['accounting'],
            'attention to detail' => ['attention to detail'],
            'analytical thinking' => ['analytical'],
            'communication skills' => ['communication'],
            'teamwork' => ['teamwork', 'team work'],
            'time management' => ['time management'],
            'coachable' => ['coachable', 'growth mindset'],
            'strong work ethic' => ['work ethic'],
            'problem solving' => ['problem solving'],
            'client facing skills' => ['client facing', 'client-facing'],
            'python' => ['python'],
            'sql' => ['sql'],
            'vba' => ['vba', 'macros'],
            'industry knowledge' => ['industry knowledge'],
        ];

        foreach ($skill_map as $label => $needles) {
            foreach ($needles as $needle) {
                if ($needle !== '' && strpos($haystack, $needle) !== false) {
                    $skills[] = $label;
                    break;
                }
            }
        }

        return array_values(array_unique(array_filter($skills)));
    }

    private function normalize_hr_process_terms($values)
    {
        $terms = [];
        $raw_terms = $this->sanitize_hr_multi_values($values);

        $map = [
            'resume' => 'cv',
            'candidate_profile' => 'cv',
            'phone_screen' => 'phone_screening',
            'phone' => 'phone_screening',
            'screening' => 'phone_screening',
            'video' => 'video_interview',
            'assessment' => 'video_interview',
            'technical' => 'technical_tests',
            'test' => 'technical_tests',
            'case' => 'case_study',
            'financial_modeling' => 'case_study',
            'financial_modelling' => 'case_study',
            'modeling' => 'case_study',
            'market' => 'market_analysis',
            'pitch_book' => 'market_analysis',
            'pitchbook' => 'market_analysis',
            'psychometric' => 'psychometric_testing',
            'assessment_centre' => 'assessment_center',
            'interview' => 'interview_rounds',
            'references' => 'reference_checks',
            'background' => 'background_screening',
        ];

        foreach ($raw_terms as $term) {
            $terms[] = $map[$term] ?? $term;
        }

        if (empty($terms)) {
            $terms[] = 'application';
            $terms[] = 'cv';
        }

        return array_values(array_unique(array_filter($terms)));
    }

    private function infer_hr_hiring_flags_from_post(array $post)
    {
        $haystack = strtolower(wp_strip_all_tags(implode(' ', array_filter([
            $post['role_title'] ?? '',
            $post['seniority'] ?? '',
            $post['duration'] ?? '',
            $post['content'] ?? '',
        ]))));

        $flags = [
            'hire_interns' => 0,
            'hire_graduates' => 0,
            'hire_analysts' => 0,
            'hire_associates' => 0,
            'hire_seniors' => 0,
            'hire_private_equity_candidates' => 0,
            'hire_expats' => 0,
            'hire_cfa_holders' => 0,
            'hire_mba' => 0,
            'hire_visa_sponsorship' => 0,
            'hire_arabic_speakers' => 0,
            'hire_bilingual' => 0,
            'hire_trainee' => 0,
            'hire_placement' => 0,
        ];

        if (preg_match('/\b(intern|internship|summer analyst|placement|trainee)\b/', $haystack)) {
            $flags['hire_interns'] = 1;
            $flags['hire_trainee'] = strpos($haystack, 'trainee') !== false ? 1 : 0;
            $flags['hire_placement'] = strpos($haystack, 'placement') !== false ? 1 : 0;
        }

        if (preg_match('/\b(graduate|grad scheme|graduate scheme|entry level|entry-level)\b/', $haystack)) {
            $flags['hire_graduates'] = 1;
        }

        if (preg_match('/\b(analyst|senior analyst|junior)\b/', $haystack)) {
            $flags['hire_analysts'] = 1;
        }

        if (preg_match('/\b(associate|associate director|director|senior director)\b/', $haystack)) {
            $flags['hire_associates'] = 1;
        }

        if (preg_match('/\b(vp|vice president|svp|evp|executive director|senior manager|manager)\b/', $haystack)) {
            $flags['hire_seniors'] = 1;
        }

        if (preg_match('/\b(mba|managing director|partner|c-suite|chief|head of)\b/', $haystack)) {
            $flags['hire_mba'] = 1;
        }

        if (preg_match('/\b(private_equity|gcc|private equity|uae|dubai|abu dhabi|riyadh|saudi|qatar|doha|kuwait|bahrain|oman)\b/', $haystack)) {
            $flags['hire_private_equity_candidates'] = 1;
        }

        if (preg_match('/\b(expat|international|relocation|global candidate|overseas)\b/', $haystack)) {
            $flags['hire_expats'] = 1;
        }

        if (preg_match('/\b(cfa|chartered financial analyst)\b/', $haystack)) {
            $flags['hire_cfa_holders'] = 1;
        }

        if (preg_match('/\b(visa sponsorship|sponsorship|work permit)\b/', $haystack)) {
            $flags['hire_visa_sponsorship'] = 1;
        }

        if (preg_match('/\b(arabic)\b/', $haystack)) {
            $flags['hire_arabic_speakers'] = 1;
        }

        if (preg_match('/\b(bilingual|english\/arabic|english and arabic)\b/', $haystack)) {
            $flags['hire_bilingual'] = 1;
        }

        if (!array_filter($flags)) {
            $flags['hire_interns'] = 1;
        }

        return $flags;
    }

    private function map_post_prep_urls_for_hr_outreach(array $post)
    {
        return [
            'interview_questions_url' => $this->find_post_material_url_for_hr($post, ['interview', 'question', 'case', 'assessment']) ?: ($post['case_study_pdf'] ?? ''),
            'cv_template_url' => $post['cv_template_docx'] ?? $this->find_post_material_url_for_hr($post, ['cv', 'resume', 'template']),
            'cover_letter_url' => $post['cover_letter_docx'] ?? $this->find_post_material_url_for_hr($post, ['cover', 'letter', 'positioning']),
        ];
    }

    private function find_post_material_url_for_hr(array $post, array $needles)
    {
        $materials = $post['materials'] ?? [];
        if (!is_array($materials)) {
            return '';
        }

        foreach ($materials as $material) {
            if (!is_array($material) || empty($material['url'])) {
                continue;
            }

            $label = strtolower(trim(implode(' ', array_filter([
                $material['label'] ?? '',
                $material['file_type'] ?? '',
                $material['description'] ?? '',
            ]))));

            foreach ($needles as $needle) {
                if ($needle !== '' && strpos($label, strtolower($needle)) !== false) {
                    return esc_url_raw($material['url']);
                }
            }
        }

        return '';
    }

    /**
     * Extract sanitized keyword tokens from CRM post data
     */
    private function extract_keyword_terms_from_post(array $post)
    {
        $keywords_field = $post['keywords'] ?? '';
        if (!$keywords_field) {
            return [];
        }

        if (is_array($keywords_field)) {
            $items = $keywords_field;
        } elseif (is_string($keywords_field)) {
            $decoded = json_decode($keywords_field, true);
            if (is_array($decoded)) {
                $items = $decoded;
            } else {
                $items = preg_split('/[,;\n]+/', $keywords_field) ?: [];
            }
        } else {
            $items = [(string) $keywords_field];
        }

        $normalized = [];

        foreach ($items as $item) {
            if (is_array($item)) {
                $preferred_value = '';
                foreach (['label', 'term', 'name', 'value'] as $key) {
                    if (!empty($item[$key]) && is_scalar($item[$key])) {
                        $preferred_value = (string) $item[$key];
                        break;
                    }
                }

                if ($preferred_value === '') {
                    continue;
                }

                $clean = $this->normalize_keyword_token($preferred_value);
            } else {
                $clean = $this->normalize_keyword_token($item);
            }

            if ($clean) {
                $normalized[] = $clean;
            }
        }

        return array_values(array_unique($normalized));
    }

    /**
     * Normalize keywords pulled from CRM posts so prefixes like "Label" are removed
     */
    private function normalize_keyword_token($token)
    {
        if (!is_string($token)) {
            return '';
        }

        $token = strtolower(trim($token));

        if ($token === '') {
            return '';
        }

        // Strip unicode multiplication sign and other stray glyphs
        $token = preg_replace('/[×•·]+/u', '', $token);

        // Remove textual prefixes commonly found in source data
        $token = preg_replace('/^(label|type|priority|category)\s*/', '', $token);

        // Tokens that only described metadata can be ignored
        if (in_array($token, ['label', 'type', 'priority', 'skill', 'value', 'category'], true)) {
            return '';
        }

        // Remove anything that isn't alphanumeric or common separators
        $token = preg_replace('/[^a-z0-9\s\-\/]+/u', '', $token);

        if ($token === '') {
            return '';
        }

        return sanitize_key($token);
    }

    /**
     * Merge an existing HR outreach entry with new archive data
     */
    private function merge_hr_outreach_entry(array $existing_entry, array $post, array $new_data)
    {
        $merged = $existing_entry;

        $merged['id'] = $existing_entry['id'];
        $merged['last_hire_proof'] = $new_data['last_hire_proof'];
        foreach (
            [
                'hire_interns',
                'hire_graduates',
                'hire_analysts',
                'hire_associates',
                'hire_seniors',
                'hire_private_equity_candidates',
                'hire_expats',
                'hire_cfa_holders',
                'hire_mba',
                'hire_visa_sponsorship',
                'hire_arabic_speakers',
                'hire_bilingual',
                'hire_trainee',
                'hire_placement',
            ] as $flag
        ) {
            $merged[$flag] = !empty($existing_entry[$flag]) || !empty($new_data[$flag]) ? 1 : 0;
        }

        $capture_note = $this->build_hr_capture_note($post);
        $summary = $this->build_hr_outreach_notes($post);
        $new_notes_block = $this->combine_notes_with_capture($summary, $capture_note);
        $existing_notes = (string) ($merged['notes'] ?? '');
        if ($new_notes_block !== '' && strpos($existing_notes, $capture_note) === false) {
            $merged['notes'] = $existing_notes
                ? trim($new_notes_block . "\n\n" . $existing_notes)
                : $new_notes_block;
        }

        // If we previously lacked basic recruiter/contact info, fill it
        $fields_to_backfill = [
            'contact_email',
            'contact_phone',
            'contact_linkedin',
            'contact_photo',
            'company_logo',
            'company_url',
            'interview_questions_url',
            'cv_template_url',
            'cover_letter_url',
            'company_intel_url'
        ];

        foreach ($fields_to_backfill as $field) {
            if (empty($merged[$field]) && !empty($new_data[$field])) {
                $merged[$field] = $new_data[$field];
            }
        }

        if (empty($merged['team_contacts']) && !empty($new_data['team_contacts'])) {
            $merged['team_contacts'] = $new_data['team_contacts'];
        }

        if (empty($merged['location']) && !empty($new_data['location'])) {
            $merged['location'] = $new_data['location'];
            $merged['regions'] = $new_data['regions'];
        }

        if (empty($merged['role_focus']) && !empty($new_data['role_focus'])) {
            $merged['role_focus'] = $new_data['role_focus'];
        }

        $merged['skills'] = $this->merge_term_sets($merged['skills'] ?? [], $new_data['skills'] ?? []);
        $merged['program_types'] = $this->merge_term_sets($merged['program_types'] ?? [], $new_data['program_types'] ?? []);
        $merged['process'] = $this->merge_term_sets($merged['process'] ?? [], $new_data['process'] ?? []);
        $merged['industry'] = $this->merge_term_sets($merged['industry'] ?? [], $new_data['industry'] ?? []);

        if (empty($merged['company_name']) && !empty($new_data['company_name'])) {
            $merged['company_name'] = $new_data['company_name'];
        }

        if (empty($merged['contact_name']) && !empty($new_data['contact_name'])) {
            $merged['contact_name'] = $new_data['contact_name'];
        }

        if (empty($merged['contact_title']) && !empty($new_data['contact_title'])) {
            $merged['contact_title'] = $new_data['contact_title'];
        }

        if (empty($merged['source_context'])) {
            $merged['source_context'] = $new_data['source_context'] ?? 'active_recruiter';
        }

        return $merged;
    }

    /**
     * Infer program type tags based on the post contents
     */
    private function infer_program_types_from_post(array $post)
    {
        $types = [];
        $haystack = strtolower(($post['role_title'] ?? '') . ' ' . wp_strip_all_tags($post['content'] ?? ''));

        if (strpos($haystack, 'intern') !== false || strpos($haystack, 'analyst') !== false || strpos($haystack, 'junior') !== false) {
            $types[] = 'analyst';
        }

        if (strpos($haystack, 'associate') !== false || strpos($haystack, 'mid-level') !== false) {
            $types[] = 'associate';
        }

        if (strpos($haystack, 'vp') !== false || strpos($haystack, 'vice president') !== false || strpos($haystack, 'director') !== false || strpos($haystack, 'senior') !== false) {
            $types[] = 'senior';
        }

        if (strpos($haystack, 'managing director') !== false || strpos($haystack, ' md') !== false || strpos($haystack, 'partner') !== false || strpos($haystack, 'c-level') !== false) {
            $types[] = 'executive';
        }

        if (strpos($haystack, 'analyst') !== false) {
            $types[] = 'analyst_program';
        }

        if (strpos($haystack, 'associate') !== false) {
            $types[] = 'associate_program';
        }

        if (!empty($post['seniority'])) {
            $types[] = sanitize_key($post['seniority']);
        }

        return array_values(array_unique(array_filter($types)));
    }

    /**
     * Build helpful notes so the HR outreach entry references the prior post
     */
    private function build_hr_outreach_notes(array $post)
    {
        $notes = [];

        if (!empty($post['role_title'])) {
            $notes[] = sprintf(__('Role: %s', 'senna-finance'), $post['role_title']);
        }

        if (!empty($post['company'])) {
            $notes[] = sprintf(__('Company: %s', 'senna-finance'), $post['company']);
        }

        if (!empty($post['location'])) {
            $notes[] = sprintf(__('Location: %s', 'senna-finance'), $post['location']);
        }

        if (!empty($post['application_url'])) {
            $notes[] = sprintf(__('Original application: %s', 'senna-finance'), esc_url_raw($post['application_url']));
        }

        if (!empty($post['posted_at'])) {
            $notes[] = sprintf(__('Posted: %s', 'senna-finance'), date_i18n(get_option('date_format'), strtotime($post['posted_at'])));
        }

        if (!empty($post['content'])) {
            $notes[] = wp_trim_words(wp_strip_all_tags($post['content']), 60, '...');
        }

        return implode("\n\n", array_filter($notes));
    }

    /**
     * Attempt to locate an existing HR outreach entry for the same contact
     */
    private function locate_existing_hr_outreach_entry($company_name, $contact_email, $contact_name, $contact_linkedin = '', $allow_company_fallback = true)
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_hr_outreach';

        if (!empty($contact_email)) {
            $existing = $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE contact_email = %s LIMIT 1", $contact_email));
            if ($existing) {
                return (int) $existing;
            }
        }

        if (!empty($contact_linkedin)) {
            $existing = $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE contact_linkedin = %s LIMIT 1", $contact_linkedin));
            if ($existing) {
                return (int) $existing;
            }
        }

        if (!empty($company_name) && !empty($contact_name)) {
            $existing = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE LOWER(company_name) = LOWER(%s) AND LOWER(contact_name) = LOWER(%s) LIMIT 1",
                $company_name,
                $contact_name
            ));

            if ($existing) {
                return (int) $existing;
            }
        }

        if ($allow_company_fallback && !empty($company_name)) {
            $existing = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$table} WHERE LOWER(company_name) = LOWER(%s) LIMIT 1",
                $company_name
            ));

            if ($existing) {
                return (int) $existing;
            }
        }

        return 0;
    }

    // =========================================================================
    // Admin AJAX Handlers
    // =========================================================================

    /**
     * Verify admin AJAX request
     */
    private function verify_admin_ajax()
    {
        if (!check_ajax_referer('sffc_crm_admin_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        return true;
    }

    public static function get_embed_test_result($url, $provider = '', $headers = [])
    {
        $url = trim((string) $url);
        $provider = strtolower(trim((string) $provider));
        $host = strtolower((string) wp_parse_url($url, PHP_URL_HOST));
        $result = [
            'status' => 'unknown',
            'label' => __('Embed unknown', 'senna-finance'),
            'class' => 'is-unknown',
            'detail' => __('No reliable embed signal was detected yet.', 'senna-finance'),
        ];

        if ($url === '' || !preg_match('#^https?://#i', $url)) {
            $result['status'] = 'missing';
            $result['label'] = __('No embed link', 'senna-finance');
            $result['class'] = 'is-default';
            $result['detail'] = __('Add a valid https application URL before testing embed support.', 'senna-finance');
            return $result;
        }

        $x_frame_options = strtolower(trim((string) ($headers['x-frame-options'] ?? '')));
        $content_security_policy = strtolower(trim((string) ($headers['content-security-policy'] ?? '')));
        if ($x_frame_options !== '' && preg_match('/\b(?:deny|sameorigin)\b/i', $x_frame_options)) {
            $result['status'] = 'blocked';
            $result['label'] = __('Embed blocked', 'senna-finance');
            $result['class'] = 'is-blocked';
            $result['detail'] = sprintf(__('The page sends X-Frame-Options: %s.', 'senna-finance'), $x_frame_options);
            return $result;
        }
        if ($content_security_policy !== '' && preg_match('/frame-ancestors\s+([^;]+)/i', $content_security_policy, $matches)) {
            $ancestors = trim((string) ($matches[1] ?? ''));
            if ($ancestors !== '' && !preg_match('/\*|joinsenna\.com|senna/i', $ancestors)) {
                $result['status'] = 'blocked';
                $result['label'] = __('Embed blocked', 'senna-finance');
                $result['class'] = 'is-blocked';
                $result['detail'] = sprintf(__('The page restricts iframe parents with CSP frame-ancestors: %s.', 'senna-finance'), $ancestors);
                return $result;
            }
        }

        $clean_provider = str_replace(['_', '-'], ' ', $provider);
        $known_blocked_provider = in_array($clean_provider, [
            'ashby',
            'smartrecruiters',
            'oracle cx',
            'oracle hcm',
            'phenom',
            'bayt careers',
            'talentbrew',
            'michael page',
            'mubadala takafo',
            'takafo',
            'delta executive search',
            'venture search',
            'workday',
        ], true);

        $is_successfactors_embedded_apply = (
            preg_match('/(?:successfactors\.(?:com|eu)|sapsf\.com)$/', $host) &&
            preg_match('/[?&]career_ns=job_application\b/i', $url)
        );

        if (
            preg_match('/(?:job-boards|boards)(?:\.eu)?\.greenhouse\.io$/', $host) ||
            preg_match('/apply\.workable\.com$/', $host) ||
            preg_match('/jobs\.lever\.co$/', $host) ||
            $is_successfactors_embedded_apply
        ) {
            $result['status'] = 'embeddable';
            $result['label'] = __('Embeddable', 'senna-finance');
            $result['class'] = 'is-embeddable';
            $result['detail'] = __('This application route is likely to work inside the Senna chat iframe.', 'senna-finance');
            return $result;
        }

        if (
            $known_blocked_provider ||
            preg_match('/(?:ashbyhq|recruitee|teamtailor|smartrecruiters|comeet|oraclecloud|oracle|phenompeople|myworkdayjobs)\.com$/', $host) ||
            preg_match('/(?:jobs\.adnoc\.ae|bayt\.com|careers\.(?:alrajhibank|gib|riyadbank|kafd)\.|talentbrew\.com|careers\.blackrock\.com|fishercareers\.com|michaelpage\.|mubadala\.com|takafo\.ai|deltaexec\.com|venturesearch\.com)$/', $host)
        ) {
            $result['status'] = 'blocked';
            $result['label'] = __('Embed blocked', 'senna-finance');
            $result['class'] = 'is-blocked';
            $result['detail'] = __('This provider usually refuses cross-site iframes, so use external apply or worker testing instead.', 'senna-finance');
            return $result;
        }

        if (!empty($headers)) {
            $result['status'] = 'likely';
            $result['label'] = __('Likely embeddable', 'senna-finance');
            $result['class'] = 'is-likely';
            $result['detail'] = __('No obvious iframe-blocking headers were returned. Use the preview to confirm visually.', 'senna-finance');
        }

        return $result;
    }

    public function ajax_test_embed_url()
    {
        $this->verify_admin_ajax();

        $url = esc_url_raw((string) ($_POST['url'] ?? ''));
        $provider = sanitize_text_field((string) ($_POST['provider'] ?? ''));
        if ($url === '') {
            wp_send_json_error(['message' => __('Add a URL first.', 'senna-finance')], 400);
        }

        $headers = [];
        $response = wp_remote_head($url, [
            'timeout' => 10,
            'redirection' => 5,
            'user-agent' => 'Mozilla/5.0 Senna Embed Tester',
        ]);

        if (is_wp_error($response)) {
            $response = wp_remote_get($url, [
                'timeout' => 10,
                'redirection' => 5,
                'user-agent' => 'Mozilla/5.0 Senna Embed Tester',
            ]);
        }

        if (!is_wp_error($response)) {
            $header_names = ['x-frame-options', 'content-security-policy'];
            foreach ($header_names as $header_name) {
                $value = wp_remote_retrieve_header($response, $header_name);
                if (is_array($value)) {
                    $value = implode(' ', array_map('strval', $value));
                }
                if (trim((string) $value) !== '') {
                    $headers[$header_name] = trim((string) $value);
                }
            }
        }

        $result = self::get_embed_test_result($url, $provider, $headers);
        $result['url'] = $url;
        $result['headers'] = $headers;
        if (is_wp_error($response)) {
            $result['detail'] .= ' ' . sprintf(__('Header check failed: %s', 'senna-finance'), $response->get_error_message());
        }

        wp_send_json_success($result);
    }

    private function get_free_digest_build_payload($state, $result = [])
    {
        $state = is_array($state) ? $state : [];
        $checked = (int) ($state['checked'] ?? 0);
        $total = max(0, (int) ($state['total_users'] ?? 0));
        $queued = (int) ($state['queued'] ?? 0);
        $percent = $total > 0 ? min(100, max(0, (int) round(($checked / $total) * 100))) : 0;
        $status = sanitize_key($state['status'] ?? 'idle');

        return [
            'status' => $status ?: 'idle',
            'status_label' => $status === 'running'
                ? __('Running', 'senna-finance')
                : ($status === 'paused'
                    ? __('Paused', 'senna-finance')
                    : ($status === 'completed' ? __('Completed', 'senna-finance') : __('Idle', 'senna-finance'))),
            'checked' => $checked,
            'total' => $total,
            'queued' => $queued,
            'percent' => $percent,
            'cycle_key' => sanitize_text_field($state['cycle_key'] ?? ''),
            'completed_at' => !empty($state['completed_at']) ? date_i18n(get_option('date_format') . ' ' . get_option('time_format'), strtotime($state['completed_at'])) : '',
            'chunk_checked' => (int) ($result['chunk_checked'] ?? $result['checked'] ?? 0),
            'chunk_queued' => (int) ($result['chunk_queued'] ?? $result['queued'] ?? 0),
        ];
    }

    private function get_free_digest_process_payload($state, $result = [])
    {
        $state = is_array($state) ? $state : [];
        $processed = (int) ($state['processed'] ?? 0);
        $total = max(0, (int) ($state['total_jobs'] ?? 0));
        $sent = (int) ($state['sent'] ?? 0);
        $failed = (int) ($state['failed'] ?? 0);
        $percent = $total > 0 ? min(100, max(0, (int) round(($processed / $total) * 100))) : 0;
        $status = sanitize_key($state['status'] ?? 'idle');

        return [
            'status' => $status ?: 'idle',
            'status_label' => $status === 'running'
                ? __('Running', 'senna-finance')
                : ($status === 'paused'
                    ? __('Paused', 'senna-finance')
                    : ($status === 'completed' ? __('Completed', 'senna-finance') : __('Idle', 'senna-finance'))),
            'processed' => $processed,
            'total' => $total,
            'sent' => $sent,
            'failed' => $failed,
            'percent' => $percent,
            'completed_at' => !empty($state['completed_at']) ? date_i18n(get_option('date_format') . ' ' . get_option('time_format'), strtotime($state['completed_at'])) : '',
            'chunk_processed' => (int) ($result['processed'] ?? 0),
            'chunk_sent' => (int) ($result['sent'] ?? 0),
            'chunk_failed' => (int) ($result['failed'] ?? 0),
        ];
    }

    public function ajax_process_free_digest_build()
    {
        $this->verify_admin_ajax();

        if (function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled()) {
            wp_send_json_error(['message' => __('Role alerts are disabled.', 'senna-finance')], 403);
        }

        if (!class_exists('SFFC_CRM_Free_Alert_Digest')) {
            wp_send_json_error(['message' => __('Free digest build service is not available.', 'senna-finance')], 500);
        }

        $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
        $result = $digest->process_build_queue();
        $state = $digest->get_build_state();

        wp_send_json_success($this->get_free_digest_build_payload($state, $result));
    }

    public function ajax_process_free_digest_send()
    {
        $this->verify_admin_ajax();

        if (function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled()) {
            wp_send_json_error(['message' => __('Role alerts are disabled.', 'senna-finance')], 403);
        }

        if (!class_exists('SFFC_CRM_Free_Alert_Digest')) {
            wp_send_json_error(['message' => __('Free digest processing service is not available.', 'senna-finance')], 500);
        }

        $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
        $result = $digest->process_queue();
        $state = $digest->get_processing_state();

        wp_send_json_success($this->get_free_digest_process_payload($state, $result));
    }

    /**
     * AJAX: Approve post
     */
    public function ajax_approve_post()
    {
        $this->verify_admin_ajax();

        $post_id = intval($_POST['post_id'] ?? 0);

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID required'], 400);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_posts';

        $result = $wpdb->update(
            $table,
            ['admin_approved' => 1, 'updated_at' => current_time('mysql')],
            ['id' => $post_id],
            ['%d', '%s'],
            ['%d']
        );

        if ($result !== false) {
            $this->sync_to_jobs_post_cpt($post_id);
            wp_send_json_success(['message' => 'Post approved']);
        }

        wp_send_json_error(['message' => 'Failed to approve post'], 500);
    }

    /**
     * AJAX: Reject post
     */
    public function ajax_reject_post()
    {
        $this->verify_admin_ajax();

        $post_id = intval($_POST['post_id'] ?? 0);
        $reason = sanitize_text_field($_POST['reason'] ?? '');

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID required'], 400);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_posts';

        $result = $wpdb->update(
            $table,
            [
                'is_active' => 0,
                'admin_approved' => 0,
                'updated_at' => current_time('mysql'),
            ],
            ['id' => $post_id],
            ['%d', '%d', '%s'],
            ['%d']
        );

        if ($result !== false) {
            $this->sync_to_jobs_post_cpt($post_id);
            // Log rejection reason if provided
            if ($reason) {
                update_post_meta($post_id, '_crm_rejection_reason', $reason);
            }
            wp_send_json_success(['message' => 'Post rejected']);
        }

        wp_send_json_error(['message' => 'Failed to reject post'], 500);
    }

    /**
     * AJAX: Delete post
     */
    public function ajax_delete_post()
    {
        $this->verify_admin_ajax();

        $post_id = intval($_POST['post_id'] ?? 0);

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID required'], 400);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_posts';

        $result = $wpdb->delete($table, ['id' => $post_id], ['%d']);

        if ($result) {
            $this->delete_jobs_post_cpt($post_id, true);
            wp_send_json_success(['message' => 'Post deleted']);
        }

        wp_send_json_error(['message' => 'Failed to delete post'], 500);
    }

    /**
     * AJAX: Archive a post to HR Outreach (optionally deleting original)
     */
    public function ajax_archive_post_to_hr()
    {
        $this->verify_admin_ajax();

        $post_id = intval($_POST['post_id'] ?? 0);
        $delete_original = !empty($_POST['delete_original']);

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID required'], 400);
        }

        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get($post_id);

        if (!$post) {
            wp_send_json_error(['message' => 'Post not found'], 404);
        }

        if (!class_exists('SFFC_CRM_HR_Outreach')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-outreach.php';
        }

        $recruiter = null;
        if (!empty($post['recruiter_id'])) {
            if (!class_exists('SFFC_CRM_Recruiter')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-recruiter.php';
            }
            $recruiter_model = new SFFC_CRM_Recruiter();
            $recruiter = $recruiter_model->get($post['recruiter_id']);
        }

        $hr_data = $this->map_post_to_hr_outreach_data($post, $recruiter);

        if (is_wp_error($hr_data)) {
            wp_send_json_error(['message' => $hr_data->get_error_message()], 400);
        }

        $hr_model = new SFFC_CRM_HR_Outreach();
        $existing_id = $this->locate_existing_hr_outreach_entry(
            $hr_data['company_name'],
            $hr_data['contact_email'],
            $hr_data['contact_name'],
            $hr_data['contact_linkedin']
        );

        $existing_entry = null;
        if ($existing_id) {
            $existing_entry = $hr_model->get($existing_id);
            if ($existing_entry) {
                $hr_data = $this->merge_hr_outreach_entry($existing_entry, $post, $hr_data);
            }
            $hr_data['id'] = $existing_id;
        }

        $hr_id = $hr_model->save($hr_data);

        if (is_wp_error($hr_id) || !$hr_id) {
            $message = is_wp_error($hr_id) ? $hr_id->get_error_message() : __('Unable to save HR outreach contact.', 'senna-finance');
            wp_send_json_error(['message' => $message], 500);
        }

        $deleted = false;
        if ($delete_original) {
            global $wpdb;
            $deleted = (bool) $wpdb->delete($wpdb->prefix . 'sffc_crm_posts', ['id' => $post_id], ['%d']);
            if ($deleted) {
                $this->delete_jobs_post_cpt($post_id, true);
            }
        }

        $message = $existing_id
            ? __('HR outreach contact updated from post details.', 'senna-finance')
            : __('HR outreach contact created from post details.', 'senna-finance');

        if ($deleted) {
            $message .= ' ' . __('Original post deleted.', 'senna-finance');
        }

        wp_send_json_success([
            'message' => $message,
            'hr_id' => (int) $hr_id,
            'existing' => (bool) $existing_id,
            'deleted' => $deleted,
        ]);
    }

    /**
     * AJAX: Bulk action
     */
    public function ajax_bulk_action()
    {
        $this->verify_admin_ajax();

        $action = sanitize_text_field($_POST['bulk_action'] ?? '');
        $post_ids = array_map('intval', (array) ($_POST['post_ids'] ?? []));

        if (empty($post_ids)) {
            wp_send_json_error(['message' => 'No posts selected'], 400);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_posts';
        $count = 0;

        switch ($action) {
            case 'approve':
                foreach ($post_ids as $post_id) {
                    $result = $wpdb->update(
                        $table,
                        ['admin_approved' => 1, 'updated_at' => current_time('mysql')],
                        ['id' => $post_id],
                        ['%d', '%s'],
                        ['%d']
                    );
                    if ($result !== false) {
                        $this->sync_to_jobs_post_cpt($post_id);
                        $count++;
                    }
                }
                break;

            case 'reject':
                foreach ($post_ids as $post_id) {
                    $result = $wpdb->update(
                        $table,
                        ['is_active' => 0, 'admin_approved' => 0, 'updated_at' => current_time('mysql')],
                        ['id' => $post_id],
                        ['%d', '%d', '%s'],
                        ['%d']
                    );
                    if ($result !== false) {
                        $this->sync_to_jobs_post_cpt($post_id);
                        $count++;
                    }
                }
                break;

            case 'delete':
                foreach ($post_ids as $post_id) {
                    $result = $wpdb->delete($table, ['id' => $post_id], ['%d']);
                    if ($result) {
                        $this->delete_jobs_post_cpt($post_id, true);
                        $count++;
                    }
                }
                break;

            case 'rewrite_claude':
                $post_model = new SFFC_CRM_Post();
                foreach ($post_ids as $post_id) {
                    $post = $post_model->get($post_id);
                    if (!$post) {
                        continue;
                    }

                    $rewritten = $this->rewrite_crm_post_content_with_claude([
                        'role_title' => (string) ($post['role_title'] ?? ''),
                        'company' => (string) ($post['company'] ?? ''),
                        'location' => (string) ($post['location'] ?? ''),
                        'sector' => (string) ($post['sector'] ?? ''),
                        'seniority' => (string) ($post['seniority'] ?? ''),
                        'recruiter_title' => (string) ($post['recruiter_title'] ?? ''),
                        'recruiter_firm' => (string) ($post['recruiter_firm'] ?? ''),
                        'content' => (string) ($post['content'] ?? ''),
                    ]);

                    if ($rewritten === '') {
                        continue;
                    }

                    $result = $post_model->update($post_id, [
                        'content' => $rewritten,
                        'updated_at' => current_time('mysql'),
                    ]);

                    if ($result !== false) {
                        $this->sync_to_jobs_post_cpt($post_id);
                        $count++;
                    }
                }
                break;

            default:
                wp_send_json_error(['message' => 'Invalid action'], 400);
        }

        wp_send_json_success([
            'message' => $action === 'rewrite_claude'
                ? sprintf('%d posts rewritten with Claude', $count)
                : sprintf('%d posts processed', $count),
            'count' => $count,
        ]);
    }

