    public function ajax_search_recruiters()
    {
        $this->verify_admin_ajax();

        global $wpdb;

        $query = sanitize_text_field(wp_unslash($_POST['query'] ?? ''));
        $query = trim($query);

        if (strlen($query) < 2) {
            wp_send_json_success(['results' => []]);
        }

        $like = '%' . $wpdb->esc_like($query) . '%';
        $results = [];

        $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
        $recruiters = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT id, name, title, firm, photo_url, email, phone, linkedin_url, default_company, default_company_logo
                 FROM {$recruiters_table}
                 WHERE name LIKE %s
                    OR firm LIKE %s
                    OR email LIKE %s
                    OR default_company LIKE %s
                 ORDER BY total_posts DESC, id DESC
                 LIMIT 12",
                $like,
                $like,
                $like,
                $like
            ),
            ARRAY_A
        );

        foreach ((array) $recruiters as $row) {
            $results[] = [
                'source' => 'recruiter',
                'id' => (int) ($row['id'] ?? 0),
                'name' => sanitize_text_field($row['name'] ?? ''),
                'title' => sanitize_text_field($row['title'] ?? ''),
                'firm' => sanitize_text_field($row['firm'] ?? ''),
                'email' => sanitize_email($row['email'] ?? ''),
                'phone' => sanitize_text_field($row['phone'] ?? ''),
                'linkedin' => esc_url_raw($row['linkedin_url'] ?? ''),
                'photo' => esc_url_raw($row['photo_url'] ?? ''),
                'company' => sanitize_text_field($row['default_company'] ?? ''),
                'company_logo' => esc_url_raw($row['default_company_logo'] ?? ''),
            ];
        }

        $hr_table = $wpdb->prefix . 'sffc_crm_hr_outreach';
        $hr_contacts = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT id, contact_name, contact_title, company_name, contact_email, contact_phone, contact_linkedin, contact_photo
                 FROM {$hr_table}
                 WHERE contact_name LIKE %s
                    OR company_name LIKE %s
                    OR contact_email LIKE %s
                 ORDER BY id DESC
                 LIMIT 12",
                $like,
                $like,
                $like
            ),
            ARRAY_A
        );

        foreach ((array) $hr_contacts as $row) {
            $results[] = [
                'source' => 'hr_outreach',
                'id' => (int) ($row['id'] ?? 0),
                'name' => sanitize_text_field($row['contact_name'] ?? ''),
                'title' => sanitize_text_field($row['contact_title'] ?? ''),
                'firm' => sanitize_text_field($row['company_name'] ?? ''),
                'email' => sanitize_email($row['contact_email'] ?? ''),
                'phone' => sanitize_text_field($row['contact_phone'] ?? ''),
                'linkedin' => esc_url_raw($row['contact_linkedin'] ?? ''),
                'photo' => esc_url_raw($row['contact_photo'] ?? ''),
                'company' => sanitize_text_field($row['company_name'] ?? ''),
                'company_logo' => '',
            ];
        }

        $seen = [];
        $normalized = [];
        foreach ($results as $item) {
            $key = strtolower(trim(($item['source'] ?? '') . '|' . ($item['id'] ?? 0) . '|' . ($item['email'] ?? '') . '|' . ($item['name'] ?? '')));
            if (isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;
            $normalized[] = $item;
            if (count($normalized) >= 20) {
                break;
            }
        }

        wp_send_json_success(['results' => $normalized]);
    }

