            'new_recruiter_title' => sanitize_text_field($_POST['new_recruiter_title'] ?? ''),
            'new_recruiter_firm' => sanitize_text_field($_POST['new_recruiter_firm'] ?? ''),
            'new_recruiter_email' => sanitize_email($_POST['new_recruiter_email'] ?? ''),
            'new_recruiter_phone' => sanitize_text_field($_POST['new_recruiter_phone'] ?? ''),
            'new_recruiter_linkedin' => esc_url_raw($_POST['new_recruiter_linkedin'] ?? ''),
            'source_url' => esc_url_raw($_POST['source_url'] ?? ''),
