            'company_logo' => sanitize_text_field($_POST['company_logo'] ?? ''),
            'content' => wp_unslash($_POST['content'] ?? ''),
        ];

        list($input) = $this->hydrate_crm_post_intake_input($input);

        $content = wp_unslash($input['content'] ?? '');
        if (strlen(trim(wp_strip_all_tags($content))) < 50) {
