            'recruiter_display_company' => $claude['recruiter_display_company'] ?? ($base['recruiter_display_company'] ?? ''),
            'opening_date' => $claude['opening_date'] ?? ($base['opening_date'] ?? ''),
            'closing_date' => $claude['closing_date'] ?? ($base['closing_date'] ?? ''),
            'starting_date' => $claude['starting_date'] ?? ($base['starting_date'] ?? ''),
            'duration' => $claude['duration'] ?? ($base['duration'] ?? ''),
            'application_process' => $claude['application_process'] ?? ($base['application_process'] ?? []),
        ]);

        $suggestions = $this->build_crm_post_autofill_suggestions($merged_input);

        wp_send_json_success([
            'message' => __('Claude inferred the structured role fields from the pasted job description.', 'senna-finance'),
            'suggestions' => $suggestions,
        ]);
    }

    /**
     * AJAX: Rewrite raw job description with the selected processor.
     */
    public function ajax_rewrite_post_content()
    {
        check_ajax_referer('sffc_crm_post_rewrite', 'nonce');

        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        $processor = sanitize_key((string) ($_POST['processor'] ?? 'claude'));
        if (!in_array($processor, ['senna', 'claude'], true)) {
            $processor = 'claude';
        }

        $content = wp_unslash($_POST['content'] ?? '');
        $context = [
            'role_title' => sanitize_text_field($_POST['role_title'] ?? ''),
            'company' => sanitize_text_field($_POST['company'] ?? ''),
            'location' => sanitize_text_field($_POST['location'] ?? ''),
            'sector' => sanitize_text_field($_POST['sector'] ?? ''),
            'seniority' => sanitize_text_field($_POST['seniority'] ?? ''),
            'recruiter_title' => sanitize_text_field($_POST['new_recruiter_title'] ?? ''),
            'recruiter_firm' => sanitize_text_field($_POST['new_recruiter_firm'] ?? ''),
            'content' => $content,
        ];
        $has_rewrite_metadata = trim((string) $context['role_title']) !== ''
            || trim((string) $context['company']) !== ''
            || trim((string) $context['location']) !== ''
            || trim((string) $context['sector']) !== '';

        if (strlen(trim(wp_strip_all_tags($content))) < 50 && !$has_rewrite_metadata) {
            wp_send_json_error(['message' => 'Add a role title, company, location, sector, or a fuller role brief first.'], 400);
        }

        $source = $processor === 'claude' ? 'claude' : 'senna';
        $rewritten = $processor === 'claude'
            ? $this->rewrite_crm_post_content_with_claude($context)
            : $this->rewrite_crm_post_content_deterministically($context);

        if ($rewritten === '') {
            if ($processor === 'claude') {
                $message = $this->crm_admin_claude_last_error !== ''
                    ? sprintf(__('Claude could not rewrite this role: %s', 'senna-finance'), $this->crm_admin_claude_last_error)
                    : __('Claude is unavailable right now.', 'senna-finance');
            } else {
                $message = __('Senna could not structure this role. Please edit manually or choose a Claude rewrite.', 'senna-finance');
            }

            wp_send_json_error([
                'message' => $message,
            ], 500);
        }

        wp_send_json_success([
            'message' => $source === 'senna'
                ? __('Job description structured with the Senna parser.', 'senna-finance')
                : __('Job description rewritten with Claude.', 'senna-finance'),
            'source' => $source,
            'content' => $rewritten,
        ]);
    }

    /**
     * AJAX: Extract keywords
     */
    public function ajax_extract_keywords()
    {
        check_ajax_referer('sffc_crm_keywords', 'nonce');

        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        $description = wp_unslash($_POST['description'] ?? '');
        $location = sanitize_text_field($_POST['location'] ?? '');
        $role_title = sanitize_text_field($_POST['role_title'] ?? '');
        $company = sanitize_text_field($_POST['company'] ?? '');
        $sector = sanitize_text_field($_POST['sector'] ?? '');
        $seniority = sanitize_text_field($_POST['seniority'] ?? '');
        $experience_years = sanitize_text_field($_POST['experience_years'] ?? '');
        $post_id = intval($_POST['post_id'] ?? 0);
        $force = intval($_POST['force'] ?? 0);

        if (empty($description) || strlen($description) < 50) {
            wp_send_json_error(['message' => 'Description too short. Minimum 50 characters required.']);
        }

        // Check if manual keywords exist and force is not set
        if ($post_id && !$force) {
            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_posts';
            $is_manual = $wpdb->get_var($wpdb->prepare(
                "SELECT keywords_manual FROM $table WHERE id = %d",
                $post_id
            ));

            if ($is_manual == 1) {
                wp_send_json_error(['message' => 'Keywords have been manually edited. Use Regenerate to override.']);
            }
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-keyword-extractor.php';
        $extractor = new SFFC_CRM_Keyword_Extractor();

        $post_data = [
            'location' => $location,
            'role_title' => $role_title,
            'company' => $company,
            'sector' => $sector,
            'seniority' => $seniority,
            'experience_years' => $experience_years,
        ];

        $keywords = $extractor->extract_keywords($description, $post_data);

        if (empty($keywords)) {
            wp_send_json_error(['message' => 'No keywords could be extracted. Try adding more details to the description.']);
        }

        wp_send_json_success([
            'keywords' => $keywords,
            'count' => count($keywords)
        ]);
    }

    /**
     * AJAX: Get keywords for a post
     */
    public function ajax_get_keywords()
    {
        check_ajax_referer('sffc_crm_keywords', 'nonce');

        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        $post_id = intval($_POST['post_id'] ?? 0);

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID required'], 400);
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
        $post_model = new SFFC_CRM_Post();
        $keywords = $post_model->get_keywords($post_id);

        wp_send_json_success([
            'keywords' => $keywords,
            'count' => count($keywords)
        ]);
    }

    /**
     * AJAX: Bulk extract keywords for all posts
     */
    public function ajax_bulk_extract_keywords()
    {
        check_ajax_referer('sffc_crm_bulk_keywords', 'nonce');

        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Unauthorized'], 403);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_posts';

        // Get all posts without keywords or with auto-generated keywords only
        $posts = $wpdb->get_results(
            "SELECT id, content, location, role_title, company, sector, seniority, experience_years
             FROM $table
             WHERE (keywords IS NULL OR keywords = '' OR keywords_manual = 0)
             AND content IS NOT NULL
             AND CHAR_LENGTH(content) >= 50
             ORDER BY created_at DESC",
            ARRAY_A
        );

        if (empty($posts)) {
            wp_send_json_success([
                'message' => 'No posts found that need keyword extraction.',
                'processed' => 0
            ]);
            return;
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-keyword-extractor.php';
        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';

        $extractor = new SFFC_CRM_Keyword_Extractor();
        $post_model = new SFFC_CRM_Post();

        $processed = 0;
        $failed = 0;

        foreach ($posts as $post) {
            $post_data = [
                'location' => $post['location'],
                'role_title' => $post['role_title'],
                'company' => $post['company'],
                'sector' => $post['sector'],
                'seniority' => $post['seniority'],
                'experience_years' => $post['experience_years'],
            ];

            $keywords = $extractor->extract_keywords($post['content'], $post_data);

            if (!empty($keywords)) {
                $success = $post_model->save_keywords($post['id'], $keywords, false);
                if ($success) {
                    $processed++;
                } else {
                    $failed++;
                }
            } else {
                $failed++;
            }

            // Prevent timeout by flushing output periodically
            if ($processed % 10 === 0) {
                if (function_exists('wp_cache_flush')) {
                    wp_cache_flush();
                }
            }
        }

        $total = count($posts);
        $message = sprintf(
            'Keyword extraction complete. Processed: %d/%d posts. Failed: %d posts.',
            $processed,
            $total,
            $failed
        );

        wp_send_json_success([
            'message' => $message,
            'processed' => $processed,
            'failed' => $failed,
            'total' => $total
        ]);
    }

    public function render_member_signup_events_page()
    {
