        if (!$table_exists) {
            echo '<div class="notice notice-warning"><p>' . esc_html__('The signup events table does not exist yet. Run Update Database Schema from CRM Settings > Database Management.', 'senna-finance') . '</p></div>';
            echo '</div>';
            return;
        }

        $where_sql = '';
        $query_args = [];
        if ($search !== '') {
            $like = '%' . $wpdb->esc_like($search) . '%';
            $where_sql = 'WHERE email LIKE %s OR job_title LIKE %s OR apply_url LIKE %s';
            $query_args = [$like, $like, $like];
        }

        $count_sql = "SELECT COUNT(*) FROM {$table_name} {$where_sql}";
        $total_items = $query_args ? (int) $wpdb->get_var($wpdb->prepare($count_sql, ...$query_args)) : (int) $wpdb->get_var($count_sql);
        $offset = ($paged - 1) * $per_page;

        $rows_sql = "SELECT * FROM {$table_name} {$where_sql} ORDER BY created_at DESC, id DESC LIMIT %d OFFSET %d";
        $rows_args = $query_args;
        $rows_args[] = $per_page;
        $rows_args[] = $offset;
        $rows = $wpdb->get_results($wpdb->prepare($rows_sql, ...$rows_args), ARRAY_A);

        echo '<form method="get" action="" style="margin:16px 0;">';
        echo '<input type="hidden" name="page" value="sffc-crm-signup-events">';
        echo '<input type="search" name="s" class="regular-text" value="' . esc_attr($search) . '" placeholder="' . esc_attr__('Search email, job title, or URL', 'senna-finance') . '">';
        echo ' <button type="submit" class="button">' . esc_html__('Search', 'senna-finance') . '</button>';
        if ($search !== '') {
            echo ' <a class="button-link" href="' . esc_url(admin_url('admin.php?page=sffc-crm-signup-events')) . '">' . esc_html__('Clear search', 'senna-finance') . '</a>';
        }
        echo '</form>';

        echo '<p><strong>' . esc_html__('Total events:', 'senna-finance') . '</strong> ' . esc_html(number_format_i18n($total_items)) . '</p>';

        if (empty($rows)) {
            echo '<p>' . esc_html__('No signup events found.', 'senna-finance') . '</p>';
