        echo '<th>' . esc_html__('Route', 'senna-finance') . '</th>';
        echo '<th>' . esc_html__('Job', 'senna-finance') . '</th>';
        echo '<th>' . esc_html__('Email', 'senna-finance') . '</th>';
        echo '<th>' . esc_html__('User ID', 'senna-finance') . '</th>';
        echo '<th>' . esc_html__('Destination', 'senna-finance') . '</th>';
        echo '</tr></thead><tbody>';

        foreach ($rows as $row) {
            $job_label = trim((string) ($row['job_title'] ?? ''));
            if (!empty($row['job_id'])) {
                $job_label .= $job_label !== '' ? ' (#' . (int) $row['job_id'] . ')' : '#' . (int) $row['job_id'];
            }

            echo '<tr>';
