            echo '<td>' . esc_html((string) ($row['route'] ?? 'external_apply')) . '</td>';
            echo '<td>' . esc_html($job_label !== '' ? $job_label : __('Unknown role', 'senna-finance')) . '</td>';
            echo '<td>' . esc_html((string) ($row['email'] ?? '')) . '</td>';
            echo '<td>' . esc_html((string) (absint($row['user_id'] ?? 0) ?: '')) . '</td>';
            echo '<td>';
            if (!empty($row['apply_url'])) {
                echo '<a href="' . esc_url((string) $row['apply_url']) . '" target="_blank" rel="noopener noreferrer">' . esc_html__('Open employer link', 'senna-finance') . '</a>';
            } else {
                echo esc_html__('Unavailable', 'senna-finance');
            }
            echo '</td>';
            echo '</tr>';
        }

        echo '</tbody></table>';

        $total_pages = (int) ceil($total_items / $per_page);
        if ($total_pages > 1) {
            echo '<div class="tablenav"><div class="tablenav-pages" style="margin:16px 0;">';
            echo wp_kses_post(paginate_links([
                'base' => add_query_arg([
                    'page' => 'sffc-crm-signup-events',
                    's' => $search !== '' ? rawurlencode($search) : false,
                    'paged' => '%#%',
