    /**
     * Clear the cached schema snapshot used by the CRM settings page.
     */
    private function clear_settings_schema_snapshot_cache()
    {
        $this->settings_schema_snapshot_cache = null;
        delete_transient('sffc_crm_settings_schema_snapshot_v1');
    }

    /**
     * Build or load a cached schema snapshot for the CRM settings page.
     *
     * This avoids dozens of repeated SHOW TABLES / INFORMATION_SCHEMA lookups
     * when the settings page renders its diagnostics blocks.
     *
     * @param bool $force_refresh Whether to bypass transient cache.
     * @return array{tables: array<string,bool>, columns: array<string,array<string,bool>>}
     */
    private function get_settings_schema_snapshot($force_refresh = false)
    {
        if (!$force_refresh && is_array($this->settings_schema_snapshot_cache)) {
            return $this->settings_schema_snapshot_cache;
        }

        $use_transient = !$force_refresh && empty($_POST);

        if ($use_transient) {
            $cached = get_transient('sffc_crm_settings_schema_snapshot_v1');
            if (is_array($cached) && isset($cached['tables'], $cached['columns'])) {
                $this->settings_schema_snapshot_cache = $cached;
                return $cached;
            }
        }

        global $wpdb;

        $tables_of_interest = [
            $wpdb->prefix . 'sffc_crm_posts',
            $wpdb->prefix . 'sffc_crm_resource_library',
            $wpdb->prefix . 'sffc_crm_mentorship_sessions',
            $wpdb->prefix . 'sffc_crm_newsletters',
            $wpdb->prefix . 'sffc_crm_newsletter_subscriptions',
            $wpdb->prefix . 'sffc_crm_hr_contact_groups',
            $wpdb->prefix . 'sffc_crm_hr_contact_group_relationships',
            $wpdb->prefix . 'sffc_crm_member_signup_events',
            $wpdb->prefix . 'sffc_crm_auto_apply_contacts',
            $wpdb->prefix . 'sffc_crm_hr_outreach',
            $wpdb->prefix . 'sffc_crm_intro_requests',
            $wpdb->prefix . 'sffc_crm_user_criteria_groups',
            $wpdb->prefix . 'sffc_job_applications',
            $wpdb->prefix . 'sffc_crm_company_prep',
            $wpdb->prefix . 'sffc_crm_prep_materials',
            $wpdb->prefix . 'sffc_crm_prep_requests',
            $wpdb->prefix . 'sffc_crm_console_lists',
            $wpdb->prefix . 'sffc_crm_console_list_items',
            $wpdb->prefix . 'sffc_crm_application_packs',
            $wpdb->prefix . 'sffc_contact_capture',
            $wpdb->prefix . 'sffc_crm_prep_library',
            $wpdb->prefix . 'sffc_crm_expert_qa',
            $wpdb->prefix . 'sffc_crm_internship_alert_queue',
            $wpdb->prefix . 'sffc_crm_free_alert_digest_queue',
            $wpdb->prefix . 'sffc_crm_dashboard_insights',
            $wpdb->prefix . 'sffc_crm_recommended_job_interactions',
            $wpdb->prefix . 'sffc_crm_alert_default_profiles',
            $wpdb->prefix . 'sffc_crm_alert_profile_users',
        ];

        $existing_tables = array_fill_keys(array_map('strval', (array) $wpdb->get_col('SHOW TABLES')), true);
        $columns_map = [];

        if (!empty($tables_of_interest)) {
            $table_placeholders = implode(', ', array_fill(0, count($tables_of_interest), '%s'));
            $query = $wpdb->prepare(
                "SELECT TABLE_NAME, COLUMN_NAME
                 FROM INFORMATION_SCHEMA.COLUMNS
                 WHERE TABLE_SCHEMA = %s
                   AND TABLE_NAME IN ({$table_placeholders})",
                array_merge([DB_NAME], $tables_of_interest)
            );

            $rows = $wpdb->get_results($query, ARRAY_A);
            foreach ((array) $rows as $row) {
                $table_name = (string) ($row['TABLE_NAME'] ?? '');
                $column_name = (string) ($row['COLUMN_NAME'] ?? '');
                if ($table_name === '' || $column_name === '') {
                    continue;
                }

                if (!isset($columns_map[$table_name])) {
                    $columns_map[$table_name] = [];
                }

                $columns_map[$table_name][$column_name] = true;
            }
        }

        $snapshot = [
            'tables' => $existing_tables,
            'columns' => $columns_map,
        ];

        if ($use_transient) {
            set_transient('sffc_crm_settings_schema_snapshot_v1', $snapshot, 10 * MINUTE_IN_SECONDS);
        }

        $this->settings_schema_snapshot_cache = $snapshot;

        return $snapshot;
    }

    /**
     * Check whether a settings-page table exists using the cached snapshot.
     */
    private function settings_page_table_exists($table_name, $snapshot = null)
    {
        $snapshot = is_array($snapshot) ? $snapshot : $this->get_settings_schema_snapshot();
        return !empty($snapshot['tables'][(string) $table_name]);
    }

    /**
     * Check whether a settings-page column exists using the cached snapshot.
     */
    private function settings_page_column_exists($table_name, $column_name, $snapshot = null)
    {
        $snapshot = is_array($snapshot) ? $snapshot : $this->get_settings_schema_snapshot();
        return !empty($snapshot['columns'][(string) $table_name][(string) $column_name]);
    }

    /**
     * Return the subset of requested columns that exist in a table.
     *
     * @param string $table_name
     * @param string[] $columns
     * @param array|null $snapshot
     * @return string[]
     */
    private function settings_page_existing_columns($table_name, array $columns, $snapshot = null)
    {
        $snapshot = is_array($snapshot) ? $snapshot : $this->get_settings_schema_snapshot();
        $existing = [];

        foreach ($columns as $column) {
            if (!empty($snapshot['columns'][(string) $table_name][(string) $column])) {
                $existing[] = (string) $column;
            }
        }

        return $existing;
    }

    /**
     * Render settings page
     */
    public function render_settings_page()
    {
        $refresh_schema_snapshot = !empty($_POST);
        if ($refresh_schema_snapshot) {
            $this->clear_settings_schema_snapshot_cache();
        }
        $settings_schema_snapshot = $this->get_settings_schema_snapshot($refresh_schema_snapshot);

        // Handle industry column addition
        if (isset($_POST['sffc_crm_add_industry_column']) && wp_verify_nonce($_POST['crm_industry_column_nonce'], 'sffc_crm_add_industry_column')) {
            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_hr_outreach';

            // Check if column already exists
            $column_exists = $wpdb->get_results($wpdb->prepare(
                "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                 WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = 'industry'",
                DB_NAME,
                $table
            ));

            if (empty($column_exists)) {
                // Add the column
                $result = $wpdb->query("ALTER TABLE `{$table}` ADD COLUMN `industry` varchar(500) DEFAULT NULL AFTER `regions`");

                if ($result !== false) {
                    echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Industry column added successfully to HR Outreach table!', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Failed to add industry column: ', 'senna-finance') . esc_html($wpdb->last_error) . '</p></div>';
                }
            } else {
                echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('Industry column already exists in HR Outreach table.', 'senna-finance') . '</p></div>';
            }
        }

        // Handle process column addition
        if (isset($_POST['sffc_crm_add_process_column']) && wp_verify_nonce($_POST['crm_process_column_nonce'], 'sffc_crm_add_process_column')) {
            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_hr_outreach';

            // Check if column already exists
            $column_exists = $wpdb->get_results($wpdb->prepare(
                "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                 WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = 'process'",
                DB_NAME,
                $table
            ));

            if (empty($column_exists)) {
                // Add the column
                $result = $wpdb->query("ALTER TABLE `{$table}` ADD COLUMN `process` varchar(500) DEFAULT NULL AFTER `program_types`");

                if ($result !== false) {
                    echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Process column added successfully to HR Outreach table!', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Failed to add process column: ', 'senna-finance') . esc_html($wpdb->last_error) . '</p></div>';
                }
            } else {
                echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('Process column already exists in HR Outreach table.', 'senna-finance') . '</p></div>';
            }
        }

        // Handle skills column addition
        if (isset($_POST['sffc_crm_add_skills_column']) && wp_verify_nonce($_POST['crm_skills_column_nonce'], 'sffc_crm_add_skills_column')) {
            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_hr_outreach';

            // Check if column already exists
            $column_exists = $wpdb->get_results($wpdb->prepare(
                "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                 WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = 'skills'",
                DB_NAME,
                $table
            ));

            if (empty($column_exists)) {
                // Add the column
                $result = $wpdb->query("ALTER TABLE `{$table}` ADD COLUMN `skills` varchar(1000) DEFAULT NULL AFTER `hire_placement`");

                if ($result !== false) {
                    echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Skills column added successfully to HR Outreach table!', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Failed to add skills column: ', 'senna-finance') . esc_html($wpdb->last_error) . '</p></div>';
                }
            } else {
                echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('Skills column already exists in HR Outreach table.', 'senna-finance') . '</p></div>';
            }
        }

        // Handle Application Materials columns addition
        if (isset($_POST['sffc_crm_add_materials_columns']) && wp_verify_nonce($_POST['crm_materials_columns_nonce'], 'sffc_crm_add_materials_columns')) {
            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_intro_requests';
            $this->ensure_linkedin_intro_queue_table();
            $result = $this->add_application_materials_columns();
            $added = $result['added'] ?? [];
            $errors = $result['errors'] ?? [];

            // Fix the unique key constraint (critical for Express Interest to work)
            $unique_key_fixed = false;
            $wpdb->query("ALTER TABLE `{$table}` DROP INDEX `unique_user_recruiter`");
            $unique_result = $wpdb->query("ALTER TABLE `{$table}` ADD UNIQUE KEY `unique_user_post` (`user_id`, `post_id`)");
            if ($unique_result !== false) {
                $unique_key_fixed = true;
            }

            if (!empty($added)) {
                echo '<div class="notice notice-success is-dismissible"><p>' . sprintf(esc_html__('Added columns: %s', 'senna-finance'), implode(', ', $added)) . '</p></div>';
            }
            if (!empty($errors)) {
                echo '<div class="notice notice-error is-dismissible"><p>' . sprintf(esc_html__('Column repair errors: %s', 'senna-finance'), implode(', ', $errors)) . '</p></div>';
            }
            if (empty($added) && empty($errors)) {
                echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('Application material columns already exist.', 'senna-finance') . '</p></div>';
            }
            if ($unique_key_fixed) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Fixed unique key constraint (user_id, post_id)', 'senna-finance') . '</p></div>';
            }
