        if (isset($_POST['sffc_crm_bulk_update_applications']) && wp_verify_nonce($_POST['crm_application_bulk_nonce'] ?? '', 'sffc_crm_bulk_update_applications')) {
            global $wpdb;
            $this->ensure_intro_request_application_columns();
            $this->add_intro_request_columns();

            $table = $wpdb->prefix . 'sffc_crm_intro_requests';
            $application_ids = array_values(array_filter(array_map('absint', (array) ($_POST['application_ids'] ?? []))));
            $bulk_status = sanitize_key($_POST['bulk_application_status'] ?? '');
            $bulk_comment = sanitize_textarea_field($_POST['bulk_admin_message'] ?? '');
            $allowed_statuses = ['queued', 'pending_review', 'preparing', 'approved', 'submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted', 'rejected', 'expired', 'cancelled'];
            $now = current_time('mysql');
            $updated_count = 0;

            if (!empty($application_ids)) {
                foreach ($application_ids as $application_id) {
                    $existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $application_id), ARRAY_A);
                    if (!$existing) {
                        continue;
                    }

                    $update_data = ['updated_at' => $now];
                    if ($bulk_status && in_array($bulk_status, $allowed_statuses, true)) {
                        $update_data['status'] = $bulk_status;
                        $update_data['tracking_status'] = $bulk_status;
                        if (in_array($bulk_status, ['submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted', 'rejected'], true) && empty($existing['submitted_at'])) {
                            $update_data['submitted_at'] = $now;
                        }
                        if ($bulk_status === 'confirmation_sent' && empty($existing['confirmation_sent_at'])) {
                            $update_data['confirmation_sent_at'] = $now;
                        }
                        if ($bulk_status === 'cancelled') {
                            $update_data['queue_status'] = 'cancelled';
                        }
                    }
                    if (!empty($_POST['bulk_confirmation_sent']) && empty($existing['confirmation_sent_at'])) {
                        $update_data['confirmation_sent_at'] = $now;
                    }
                    if (!empty($_POST['bulk_resume_sent']) && empty($existing['resume_sent_at'])) {
                        $update_data['resume_sent_at'] = $now;
                    }
                    if (!empty($_POST['bulk_cover_letter_sent']) && empty($existing['cover_letter_sent_at'])) {
                        $update_data['cover_letter_sent_at'] = $now;
                    }
                    if ($bulk_comment !== '') {
                        $update_data['admin_message'] = $bulk_comment;
                    }

                    if (count($update_data) > 1 && $wpdb->update($table, $update_data, ['id' => $application_id]) !== false) {
                        $updated_count++;
                    }
                }
            }

            if ($updated_count > 0) {
                echo '<div class="notice notice-success is-dismissible"><p>' . sprintf(esc_html__('Updated %d application(s).', 'senna-finance'), (int) $updated_count) . '</p></div>';
            } else {
                echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('No applications were updated. Select at least one row and choose an update.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_update_application_tracking']) && wp_verify_nonce($_POST['crm_application_tracking_nonce'], 'sffc_crm_update_application_tracking')) {
            global $wpdb;
            $this->ensure_intro_request_application_columns();
            $this->add_intro_request_columns();

            $application_id = absint($_POST['application_id'] ?? 0);
            if ($application_id) {
                $table = $wpdb->prefix . 'sffc_crm_intro_requests';
                $existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $application_id), ARRAY_A);
                $allowed_statuses = ['queued', 'pending_review', 'preparing', 'approved', 'submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted', 'rejected', 'expired', 'cancelled'];
                $selected_status = sanitize_key($_POST['application_status'] ?? 'pending_review');
                $now = current_time('mysql');

                if ($existing) {
                    $confirmation_checked = !empty($_POST['confirmation_sent']);
                    $resume_checked = !empty($_POST['resume_sent']);
                    $cover_checked = !empty($_POST['cover_letter_sent']);
                    $validated_status = in_array($selected_status, $allowed_statuses, true) ? $selected_status : ($existing['status'] ?? 'queued');
                    $submitted_at = $existing['submitted_at'] ?? null;
                    if (in_array($validated_status, ['submitted', 'sent', 'confirmation_sent', 'assessment_pending', 'awaiting_response', 'interview', 'offer', 'accepted', 'rejected'], true) && empty($submitted_at)) {
                        $submitted_at = $now;
                    }
                    if ($validated_status === 'confirmation_sent') {
                        $confirmation_checked = true;
                    }

                    $updated = $wpdb->update(
                        $table,
                        [
                            'status' => $validated_status,
                            'tracking_status' => $validated_status,
                            'queue_status' => $validated_status === 'cancelled' ? 'cancelled' : ($existing['queue_status'] ?? null),
                            'admin_message' => sanitize_textarea_field($_POST['admin_message'] ?? ''),
                            'resume_url' => esc_url_raw($_POST['resume_url'] ?? ''),
                            'cover_letter_url' => esc_url_raw($_POST['cover_letter_url'] ?? ''),
                            'submitted_at' => $submitted_at,
                            'confirmation_sent_at' => $confirmation_checked ? (!empty($existing['confirmation_sent_at']) ? $existing['confirmation_sent_at'] : $now) : null,
                            'resume_sent_at' => $resume_checked ? (!empty($existing['resume_sent_at']) ? $existing['resume_sent_at'] : $now) : null,
                            'cover_letter_sent_at' => $cover_checked ? (!empty($existing['cover_letter_sent_at']) ? $existing['cover_letter_sent_at'] : $now) : null,
                            'updated_at' => $now,
                        ],
                        ['id' => $application_id]
                    );

                    if ($updated !== false) {
                        echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Application tracking updated.', 'senna-finance') . '</p></div>';
                    } else {
                        echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to update application tracking.', 'senna-finance') . '</p></div>';
                    }
                }
            }
        }

