            } else {
                require_once ABSPATH . 'wp-admin/includes/upgrade.php';
                $charset_collate = $wpdb->get_charset_collate();

                $sql_company_prep = "CREATE TABLE $company_table (
                    id bigint(20) NOT NULL AUTO_INCREMENT,
                    company_name varchar(200) NOT NULL,
                    company_website varchar(500),
                    location varchar(200),
                    regions_covered text,
                    logo_url varchar(500),
                    banner_url varchar(500),
                    is_active tinyint(1) DEFAULT 1,
                    created_at datetime DEFAULT CURRENT_TIMESTAMP,
                    updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    PRIMARY KEY (id),
                    KEY idx_active (is_active),
                    KEY idx_company_name (company_name)
                ) $charset_collate;";

                $sql_prep_materials = "CREATE TABLE $materials_table (
                    id bigint(20) NOT NULL AUTO_INCREMENT,
                    company_id bigint(20) NOT NULL,
                    file_name varchar(255) NOT NULL,
                    file_url varchar(500) NOT NULL,
                    file_type varchar(50),
                    file_size bigint(20),
                    description text,
                    created_at datetime DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (id),
                    KEY idx_company (company_id)
                ) $charset_collate;";

                $sql_prep_requests = "CREATE TABLE $requests_table (
                    id bigint(20) NOT NULL AUTO_INCREMENT,
                    user_id bigint(20) NOT NULL,
                    company_id bigint(20) NOT NULL,
                    status enum('pending','approved','rejected') DEFAULT 'pending',
                    approved_by bigint(20),
                    materials_sent tinyint(1) DEFAULT 0,
                    notes text,
                    requested_at datetime DEFAULT CURRENT_TIMESTAMP,
                    responded_at datetime,
                    PRIMARY KEY (id),
                    UNIQUE KEY unique_user_company (user_id, company_id),
                    KEY idx_user (user_id),
                    KEY idx_company (company_id),
                    KEY idx_status (status)
                ) $charset_collate;";

                @dbDelta($sql_company_prep);
                @dbDelta($sql_prep_materials);
                @dbDelta($sql_prep_requests);
            }

            $company_exists = $wpdb->get_var("SHOW TABLES LIKE '$company_table'") === $company_table;
            $materials_exists = $wpdb->get_var("SHOW TABLES LIKE '$materials_table'") === $materials_table;
            $requests_exists = $wpdb->get_var("SHOW TABLES LIKE '$requests_table'") === $requests_table;

            if ($company_exists && $materials_exists && $requests_exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Company Prep tables are ready! Companies, materials, and requests tables all exist.', 'senna-finance') . '</p></div>';
            } else {
                $missing = [];
                if (!$company_exists) {
                    $missing[] = $company_table;
                }
                if (!$materials_exists) {
                    $missing[] = $materials_table;
                }
                if (!$requests_exists) {
                    $missing[] = $requests_table;
