            global $wpdb;
            $intro_id = absint($_POST['intro_id'] ?? 0);
            $status = sanitize_key($_POST['intro_status'] ?? '');
            $admin_message = sanitize_textarea_field($_POST['admin_message'] ?? '');
            $allowed_statuses = ['pending_review', 'approved', 'sent', 'awaiting_response', 'accepted', 'rejected', 'expired'];

            if ($intro_id && in_array($status, $allowed_statuses, true)) {
                // Get intro request details before updating
                $intro_request = $wpdb->get_row($wpdb->prepare(
                    "SELECT * FROM {$wpdb->prefix}sffc_crm_intro_requests WHERE id = %d",
