            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_hr_outreach';

            $hiring_columns = [
                'hire_analysts',
                'hire_associates',
                'hire_seniors',
                'hire_private_equity_candidates',
                'hire_expats',
                'hire_cfa_holders',
                'hire_mba',
                'hire_visa_sponsorship',
                'hire_arabic_speakers',
                'hire_bilingual'
            ];

            $added = [];
            $errors = [];
            $previous_column = 'process';

            foreach ($hiring_columns as $column) {
                $column_exists = $wpdb->get_results($wpdb->prepare(
                    "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s",
                    DB_NAME,
                    $table,
                    $column
                ));

                if (empty($column_exists)) {
                    $result = $wpdb->query("ALTER TABLE `{$table}` ADD COLUMN `{$column}` tinyint(1) DEFAULT 0 AFTER `{$previous_column}`");
                    if ($result !== false) {
                        $added[] = $column;
                    } else {
                        $errors[] = $column . ': ' . $wpdb->last_error;
                    }
                }

                $previous_column = $column;
            }

            if (!empty($added)) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Successfully added columns: ', 'senna-finance') . esc_html(implode(', ', $added)) . '</p></div>';
            }

            if (!empty($errors)) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Failed to add columns: ', 'senna-finance') . esc_html(implode(', ', $errors)) . '</p></div>';
            }

            if (empty($added) && empty($errors)) {
                echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('All hiring columns already exist in HR Outreach table.', 'senna-finance') . '</p></div>';
            }
        }

