        if (isset($_POST['sffc_crm_send_auto_apply_test_email']) && wp_verify_nonce($_POST['crm_auto_apply_test_nonce'] ?? '', 'sffc_crm_send_auto_apply_test_email')) {
            $admin_email = sanitize_email(wp_unslash((string) ($_POST['sffc_crm_auto_apply_admin_email'] ?? get_option('sffc_crm_auto_apply_admin_email', get_option('admin_email')))));
