            $body =
                '<div style="margin:0;padding:24px;background:#f5f7fa;font-family:Arial,sans-serif;color:#16202d;">' .
                    '<div style="max-width:720px;margin:0 auto;background:#ffffff;border:1px solid #dfe5ec;border-radius:10px;overflow:hidden;">' .
                        '<div style="padding:24px 28px;background:#162d55;color:#ffffff;">' .
                            '<div style="font-size:12px;letter-spacing:0.08em;text-transform:uppercase;opacity:0.85;">' . esc_html__('MENA Careers CRM', 'senna-finance') . '</div>' .
                            '<div style="margin-top:8px;font-size:26px;font-weight:700;line-height:1.2;">' . esc_html__('Auto Apply Contacts test email', 'senna-finance') . '</div>' .
                        '</div>' .
                        '<div style="padding:28px;">' .
                            '<p style="margin:0 0 14px;font-size:16px;line-height:1.7;color:#24303f;">' . esc_html__('This confirms the Auto Apply Contacts admin notification address is working.', 'senna-finance') . '</p>' .
                            '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;border:1px solid #e7ebf0;border-radius:8px;overflow:hidden;">' .
                                '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:180px;font-weight:600;color:#3a4759;">' . esc_html__('Recipient', 'senna-finance') . '</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;">' . esc_html($admin_email) . '</td></tr>' .
                                '<tr><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;width:180px;font-weight:600;color:#3a4759;">' . esc_html__('Sent', 'senna-finance') . '</td><td style="padding:10px 12px;border-bottom:1px solid #e7ebf0;color:#16202d;">' . esc_html($sent_at) . '</td></tr>' .
                                '<tr><td style="padding:10px 12px;width:180px;font-weight:600;color:#3a4759;">' . esc_html__('Source', 'senna-finance') . '</td><td style="padding:10px 12px;color:#16202d;">' . esc_html__('CRM Settings > Auto Apply Contacts', 'senna-finance') . '</td></tr>' .
                            '</table>' .
