            if (empty($test_email)) {
                $test_email = sanitize_email(get_option('admin_email'));
            }

            $instant_sent = false;
            $digest_sent = false;
            if ($test_email) {
                $sample_post = sffc_crm_get_sample_internship_post();
                if (!empty($sample_post)) {
                    $current_user = wp_get_current_user();
                    $alert_user = (object) [
                        'ID' => $current_user->ID,
                        'display_name' => $current_user->display_name ?: 'MENA Careers Admin',
                        'user_email' => $test_email,
                    ];
                    $instant_sent = sffc_crm_send_alert_email($alert_user, $sample_post, [
                        'is_test' => true,
                        'manage_url' => admin_url('admin.php?page=sffc-crm-settings'),
                    ]);

                    $digest_prefs = [
                        'enabled' => true,
                        'sectors' => !empty($sample_post['sector']) ? [$sample_post['sector']] : [],
                        'types' => ['summer', 'off_cycle'],
                        'locations' => !empty($sample_post['location_city']) ? [$sample_post['location_city']] : (!empty($sample_post['location']) ? [$sample_post['location']] : []),
                        'work_modes' => !empty($sample_post['is_remote']) ? ['remote'] : (!empty($sample_post['is_hybrid']) ? ['hybrid'] : ['onsite']),
                        'groups' => [],
                    ];
                    $digest_posts = sffc_crm_get_sample_internship_digest_posts(3);
                    $digest_sent = sffc_crm_send_free_alert_digest_email($alert_user, $digest_posts, $digest_prefs, [
                        'is_test' => true,
                        'total_matches' => max(3, count($digest_posts)),
                        'manage_url' => admin_url('admin.php?page=sffc-crm-settings'),
                        'destination_url' => home_url('/terminal/?tab=matches'),
                        'upgrade_url' => get_option('sffc_registration_url', home_url('/memberships/')),
                        'last_sent_at' => date('Y-m-d H:i:s', current_time('timestamp') - DAY_IN_SECONDS),
                    ]);
                }
            }

            if ($instant_sent || $digest_sent) {
                $parts = [];
                if ($instant_sent) {
                    $parts[] = __('instant alert', 'senna-finance');
                }
                if ($digest_sent) {
                    $parts[] = __('single-role intro alert', 'senna-finance');
                }
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(
