                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to send the test alert emails. Please verify the email address and mail configuration.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_send_sender_identity_tests']) && wp_verify_nonce($_POST['crm_sender_identity_test_nonce'] ?? '', 'sffc_crm_send_sender_identity_tests')) {
            $sender_test_recipients = isset($_POST['sender_identity_test_emails']) && is_array($_POST['sender_identity_test_emails'])
                ? wp_unslash($_POST['sender_identity_test_emails'])
                : [];
            $senders = function_exists('sffc_crm_get_email_senders') ? sffc_crm_get_email_senders() : [];
            $sendgrid = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance() : null;
            $sent = 0;
            $errors = [];
            $used_recipients = [];

            if (!$sendgrid || !$sendgrid->is_configured()) {
                $errors[] = __('SendGrid is not configured.', 'senna-finance');
            } else {
                foreach ($senders as $sender_key => $sender) {
                    if (empty($sender['enabled'])) {
                        continue;
                    }

                    $recipient = sanitize_email($sender_test_recipients[$sender_key] ?? '');
                    if (!$recipient) {
                        continue;
                    }

                    $recipient_key = strtolower($recipient);
                    if (isset($used_recipients[$recipient_key])) {
                        $errors[] = sprintf(
                            __('Skipped %1$s: %2$s is already used by another sender test. Enter a different recipient for each sender.', 'senna-finance'),
                            $sender['label'] ?? $sender_key,
                            $recipient
                        );
                        continue;
                    }
                    $used_recipients[$recipient_key] = true;

                    $subject = sprintf(__('Sender test from %s', 'senna-finance'), $sender['from_email'] ?? $sender_key);
                    $body = '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f6f8fc;padding:28px 14px;font-family:Arial,Helvetica,sans-serif;"><tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" width="620" style="width:100%;max-width:620px;background:#ffffff;border:1px solid #e5eaee;border-radius:14px;"><tr><td style="padding:26px;"><h1 style="margin:0 0 10px;color:#0d353e;font-size:24px;">MENA Careers sender test</h1><p style="margin:0 0 14px;color:#334155;font-size:15px;line-height:1.6;">This message confirms that this SendGrid sender identity can send successfully.</p><p style="margin:0;color:#64748b;font-size:13px;line-height:1.6;"><strong>Sender:</strong> ' . esc_html($sender['from_name'] ?? '') . ' &lt;' . esc_html($sender['from_email'] ?? '') . '&gt;<br><strong>Recipient:</strong> ' . esc_html($recipient) . '<br><strong>Sent:</strong> ' . esc_html(wp_date(get_option('date_format') . ' ' . get_option('time_format'), current_time('timestamp'))) . '</p></td></tr></table></td></tr></table>';
                    $result = $sendgrid->send_email_from_sender(
                        $sender,
                        $subject,
                        $body,
                        $recipient,
                        null,
                        [
                            'sender_test' => '1',
                            'sender_key' => $sender_key,
                        ],
                        ['sender_identity_test']
                    );

                    if (is_wp_error($result)) {
                        $errors[] = sprintf('%s: %s', $sender['label'] ?? $sender_key, $result->get_error_message());
                    } else {
                        $sent++;
                    }
                }
            }

            if ($sent > 0) {
                echo '<div class="notice notice-success is-dismissible"><p>' . sprintf(esc_html__('Sent %d sender identity test email(s).', 'senna-finance'), (int) $sent) . '</p></div>';
            }
            if (!empty($errors)) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html(implode(' ', $errors)) . '</p></div>';
            } elseif ($sent === 0) {
                echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('No sender identity tests were sent. Add at least one recipient email.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_send_custom_email']) && wp_verify_nonce($_POST['crm_custom_email_nonce'] ?? '', 'sffc_crm_send_custom_email')) {
            $subject_template = sanitize_text_field(wp_unslash($_POST['sffc_crm_custom_email_subject'] ?? ''));
            $body_template = $this->prepare_custom_email_body_template(wp_unslash($_POST['sffc_crm_custom_email_body'] ?? ''));
            $recipients = $this->parse_custom_email_recipients($_POST['sffc_crm_custom_email_recipients'] ?? '');
            $csv_recipients = $this->parse_custom_email_csv_recipients($_FILES['sffc_crm_custom_email_csv'] ?? null, [
                'email' => sanitize_text_field(wp_unslash($_POST['sffc_crm_custom_email_csv_email_field'] ?? 'email')),
                'first_name' => sanitize_text_field(wp_unslash($_POST['sffc_crm_custom_email_csv_first_name_field'] ?? 'first_name')),
                'last_name' => sanitize_text_field(wp_unslash($_POST['sffc_crm_custom_email_csv_last_name_field'] ?? 'last_name')),
                'display_name' => sanitize_text_field(wp_unslash($_POST['sffc_crm_custom_email_csv_display_name_field'] ?? 'display_name')),
                'username' => sanitize_text_field(wp_unslash($_POST['sffc_crm_custom_email_csv_username_field'] ?? 'username')),
            ]);
            if (is_wp_error($csv_recipients)) {
                $recipients = [];
                $csv_error = $csv_recipients->get_error_message();
            } else {
                $csv_error = '';
                $recipients = array_merge($recipients, $csv_recipients);
            }
            $selected_group_key = sanitize_key($_POST['sffc_crm_custom_email_group'] ?? '');
            if ($selected_group_key !== '') {
                $recipients = array_merge($recipients, $this->get_custom_email_group_recipients($selected_group_key));
                $recipients = $this->dedupe_custom_email_recipients($recipients);
            }
            $selected_sender_key = sanitize_key($_POST['sffc_crm_custom_email_sender'] ?? '');
            $selected_sender = $selected_sender_key !== '' ? $this->get_custom_email_sender_by_key($selected_sender_key) : [];
            $service = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance() : null;
            $sent = 0;
            $errors = [];

            if (!empty($csv_error)) {
                $errors[] = $csv_error;
            }
            if (!$service || !$service->is_configured()) {
                $errors[] = __('SendGrid API key is missing. Save the SendGrid alert settings first.', 'senna-finance');
            }
            if ($selected_sender_key !== '' && empty($selected_sender)) {
                $errors[] = __('The selected sender is not available in the Custom/manual emails sender pool.', 'senna-finance');
            }
            if ($subject_template === '') {
                $errors[] = __('Add a subject line before sending the custom email.', 'senna-finance');
            }
            if (trim(wp_strip_all_tags($body_template)) === '') {
                $errors[] = __('Add email body content before sending the custom email.', 'senna-finance');
            }
            if (empty($recipients)) {
                $errors[] = __('Add at least one valid recipient email address.', 'senna-finance');
            }

            if (empty($errors)) {
                foreach ($recipients as $recipient) {
                    $resolved_sender = !empty($selected_sender) ? $selected_sender : (method_exists($service, 'resolve_contextual_sender')
                        ? (array) $service->resolve_contextual_sender($recipient, 'custom_email')
                        : []);
                    $subject = $this->replace_custom_email_tags($subject_template, $recipient, false, $resolved_sender);
                    $body = $this->replace_custom_email_tags($body_template, $recipient, true, $resolved_sender);
                    $custom_args = [
                        'custom_email' => '1',
                        'source' => 'crm_settings',
                    ];
                    if (!empty($recipient['user_id'])) {
                        $custom_args['user_id'] = (string) intval($recipient['user_id']);
                    }

                    if (!empty($selected_sender)) {
                        $result = $service->send_email_from_sender(
                            $selected_sender,
                            $subject,
                            $body,
                            $recipient['email'],
                            null,
                            $custom_args,
                            ['custom_email']
                        );
                    } else {
                        $result = $service->send_contextual_email(
                            $subject,
                            $body,
                            $recipient,
                            null,
                            'custom_email',
                            $custom_args,
                            ['custom_email']
                        );
                    }

                    if (is_wp_error($result)) {
                        $errors[] = sprintf('%s: %s', $recipient['email'], $result->get_error_message());
                        if (count($errors) >= 5) {
                            $errors[] = __('Stopped after multiple send errors. Check SendGrid before retrying.', 'senna-finance');
                            break;
                        }
                        continue;
                    }

                    $sent++;
                }
            }

            if ($sent > 0) {
                echo '<div class="notice notice-success is-dismissible"><p>' . sprintf(
                    esc_html__('Custom email sent to %d recipient(s). Duplicate addresses were skipped before sending.', 'senna-finance'),
                    (int) $sent
                ) . '</p></div>';
            }
            if (!empty($errors)) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html(implode(' ', $errors)) . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_send_sendgrid_batch_test']) && wp_verify_nonce($_POST['crm_sendgrid_batch_test_nonce'] ?? '', 'sffc_crm_send_sendgrid_batch_test')) {
            $raw_test_emails = wp_unslash($_POST['sendgrid_batch_test_emails'] ?? '');
            $test_emails = preg_split('/[\s,]+/', $raw_test_emails);
            $test_emails = array_values(array_unique(array_filter(array_map('sanitize_email', (array) $test_emails))));
            $test_emails = array_slice($test_emails, 0, 20);
            $delay_minutes = max(0, min(60, intval($_POST['sendgrid_batch_test_delay_minutes'] ?? 1)));

            $service = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance() : null;
            $submitted = false;
            $result = null;
            $submitted_count = 0;
            $available_posts = [];

            if (!$service || !$service->is_configured()) {
                $result = new WP_Error('sendgrid_not_ready', __('SendGrid API key is missing. Save the SendGrid alert settings first.', 'senna-finance'));
            } elseif (empty($test_emails)) {
                $result = new WP_Error('sendgrid_no_test_emails', __('Add at least one valid test email address.', 'senna-finance'));
            } else {
                $available_posts = sffc_crm_get_sample_internship_digest_posts(3);
                if (count($available_posts) > 1) {
                    shuffle($available_posts);
                }

                if (empty($available_posts)) {
                    $result = new WP_Error('sendgrid_test_payload_failed', __('Unable to load sample role posts for SendGrid testing.', 'senna-finance'));
                } else {
                    $send_at = current_time('timestamp') + ($delay_minutes * MINUTE_IN_SECONDS);
                    $current_user = wp_get_current_user();

                    foreach ($test_emails as $index => $email) {
                        $assigned_post = $available_posts[$index] ?? $available_posts[$index % count($available_posts)] ?? null;
                        if (!$assigned_post) {
                            continue;
                        }

                        $digest_posts = [];
                        $digest_target_count = min(3, max(3, count($available_posts)));
                        for ($offset = 0; $offset < $digest_target_count; $offset++) {
                            $digest_posts[] = $available_posts[($index + $offset) % count($available_posts)];
                        }
                        $digest_posts = array_values(array_unique($digest_posts, SORT_REGULAR));
                        if (empty($digest_posts)) {
                            $digest_posts = [$assigned_post];
                        }

                        $sample_user = (object) [
                            'ID' => $current_user->ID,
                            'display_name' => $current_user->display_name ?: 'MENA Careers Admin',
                            'user_email' => $email,
                        ];

                        $digest_prefs = [
                            'enabled' => true,
                            'sectors' => !empty($assigned_post['sector']) ? [$assigned_post['sector']] : [],
                            'types' => ['summer', 'off_cycle'],
                            'locations' => !empty($assigned_post['location_city']) ? [$assigned_post['location_city']] : (!empty($assigned_post['location']) ? [$assigned_post['location']] : []),
                            'work_modes' => !empty($assigned_post['is_remote']) ? ['remote'] : (!empty($assigned_post['is_hybrid']) ? ['hybrid'] : ['onsite']),
                            'groups' => [],
                        ];

                        $payload = sffc_crm_build_free_alert_digest_email_payload($sample_user, $digest_posts, $digest_prefs, [
                            'is_test' => true,
                            'total_matches' => max(1, count($available_posts)),
                            'manage_url' => admin_url('admin.php?page=sffc-crm-settings'),
                            'destination_url' => home_url('/terminal/?tab=matches'),
                            'upgrade_url' => get_option('sffc_registration_url', home_url('/memberships/')),
                            'last_sent_at' => date('Y-m-d H:i:s', current_time('timestamp') - DAY_IN_SECONDS),
                        ]);

                        if (!$payload) {
                            continue;
                        }

                        $send_result = $service->send_email(
                            $payload['subject'],
                            $payload['body'],
                            $payload['recipient'],
                            $send_at,
                            [
                                'user_id' => (int) $sample_user->ID,
                                'post_id' => (int) ($assigned_post['id'] ?? 0),
                                'batch_test' => '1',
                            ],
                            $payload['categories'] ?? ['internship_alert_digest', 'instant_intro'],
                            'internship_alerts'
                        );

                        if (is_wp_error($send_result)) {
                            $result = $send_result;
                            break;
                        }

                        $submitted_count++;
                    }

                    $submitted = $submitted_count > 0 && !is_wp_error($result);
                    if ($submitted) {
                        $result = [
                            'scheduled_for' => $send_at,
                            'recipient_count' => $submitted_count,
                        ];
                    } elseif (!$result) {
                        $result = new WP_Error('sendgrid_test_payload_failed', __('Unable to submit the SendGrid intro test emails.', 'senna-finance'));
                    }
                }
            }

            if ($submitted) {
                $scheduled_label = date_i18n(get_option('date_format') . ' ' . get_option('time_format'), intval($result['scheduled_for'] ?? current_time('timestamp')));
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(
                        esc_html__('SendGrid intro test submitted for %1$d recipient(s). Scheduled release: %2$s.', 'senna-finance'),
                        (int) ($result['recipient_count'] ?? $submitted_count),
                        esc_html($scheduled_label)
                    ) .
                    '</p></div>';
            } else {
                $error_message = is_wp_error($result) ? $result->get_error_message() : __('Unable to submit the SendGrid batch test.', 'senna-finance');
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html($error_message) . '</p></div>';
            }
        }

        if (
            function_exists('sffc_crm_internship_alerts_disabled')
            && sffc_crm_internship_alerts_disabled()
            && (
                isset($_POST['sffc_crm_queue_free_digests_now'])
                || isset($_POST['sffc_crm_begin_free_digest_build'])
                || isset($_POST['sffc_crm_begin_limited_free_digest_build'])
                || isset($_POST['sffc_crm_pause_free_digest_build'])
                || isset($_POST['sffc_crm_resume_free_digest_build'])
                || isset($_POST['sffc_crm_reset_free_digest_build'])
                || isset($_POST['sffc_crm_begin_free_digest_processing'])
                || isset($_POST['sffc_crm_pause_free_digest_processing'])
                || isset($_POST['sffc_crm_resume_free_digest_processing'])
                || isset($_POST['sffc_crm_process_free_digest_queue_now'])
                || isset($_POST['sffc_crm_schedule_premium_batches_now'])
                || isset($_POST['sffc_crm_enqueue_alerts_for_post'])
            )
            && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops')
        ) {
            echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('Role alerts are disabled. Manual queue operations are unavailable.', 'senna-finance') . '</p></div>';
        }

        if (isset($_POST['sffc_crm_queue_free_digests_now']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
                $start_result = $digest->start_background_build();
                $result = empty($start_result['missing_table']) ? $digest->process_build_queue() : $start_result;
                $state = $digest->get_build_state();

                if (!empty($start_result['missing_table'])) {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('The free alert digest queue table is missing. Create it first before queueing digests.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Free digest build is running in the background. Chunk checked: %1$d users, chunk queued: %2$d jobs. Overall progress: %3$d / %4$d users scanned, %5$d jobs queued for cycle %6$s.', 'senna-finance'),
                            (int) ($result['chunk_checked'] ?? $result['checked'] ?? 0),
                            (int) ($result['chunk_queued'] ?? $result['queued'] ?? 0),
                            (int) ($state['checked'] ?? 0),
                            (int) ($state['total_users'] ?? 0),
                            (int) ($state['queued'] ?? 0),
                            esc_html((string) ($state['cycle_key'] ?? ''))
                        ) .
                        '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_begin_free_digest_build']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
                $start_result = $digest->start_background_build(true);
                $result = empty($start_result['missing_table']) ? $digest->process_build_queue() : $start_result;
                $state = $digest->get_build_state();

                if (!empty($start_result['missing_table'])) {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('The free alert digest queue table is missing. Create it first before starting the digest build.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Free digest build started. Chunk checked: %1$d users, chunk queued: %2$d jobs. Progress: %3$d / %4$d users scanned.', 'senna-finance'),
                            (int) ($result['chunk_checked'] ?? $result['checked'] ?? 0),
                            (int) ($result['chunk_queued'] ?? $result['queued'] ?? 0),
                            (int) ($state['checked'] ?? 0),
                            (int) ($state['total_users'] ?? 0)
                        ) .
                        '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_begin_limited_free_digest_build']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $limit = max(1, min(1000, intval($_POST['sffc_crm_free_digest_test_limit'] ?? 1000)));
                $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
                $start_result = $digest->start_background_build(true, $limit);
                $result = empty($start_result['missing_table']) ? $digest->process_build_queue() : $start_result;
                $state = $digest->get_build_state();

                if (!empty($start_result['missing_table'])) {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('The free alert digest queue table is missing. Create it first before starting the limited test build.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Random limited free digest build started for up to %1$d users. Chunk checked: %2$d users, chunk queued: %3$d jobs. Current queued total: %4$d.', 'senna-finance'),
                            $limit,
                            (int) ($result['chunk_checked'] ?? $result['checked'] ?? 0),
                            (int) ($result['chunk_queued'] ?? $result['queued'] ?? 0),
                            (int) ($state['queued'] ?? 0)
                        ) .
                        '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_pause_free_digest_build']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $state = SFFC_CRM_Free_Alert_Digest::get_instance()->pause_build();
                if (!empty($state['paused'])) {
                    echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('Free digest build paused. Progress has been saved and can be resumed.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('There was no running free digest build to pause.', 'senna-finance') . '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_resume_free_digest_build']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
                $resume_state = $digest->resume_build();
                if (!empty($resume_state['resumed'])) {
                    $result = $digest->process_build_queue();
                    $state = $digest->get_build_state();
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Free digest build resumed. Chunk checked: %1$d users, chunk queued: %2$d jobs. Progress: %3$d / %4$d users scanned.', 'senna-finance'),
                            (int) ($result['chunk_checked'] ?? $result['checked'] ?? 0),
                            (int) ($result['chunk_queued'] ?? $result['queued'] ?? 0),
                            (int) ($state['checked'] ?? 0),
                            (int) ($state['total_users'] ?? 0)
                        ) .
                        '</p></div>';
                } else {
                    echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('There was no paused free digest build to resume.', 'senna-finance') . '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_reset_free_digest_build']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $result = SFFC_CRM_Free_Alert_Digest::get_instance()->reset_build_progress(true);
                $notice = esc_html__('Free digest progress state cleared. Existing queue jobs were preserved to avoid duplicate sends or re-queueing.', 'senna-finance');
                $notice .= ' ' . esc_html__('You can resume or start a fresh build safely.', 'senna-finance');

                echo '<div class="notice notice-success is-dismissible"><p>' . $notice . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_begin_free_digest_processing']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
                $start_state = $digest->start_processing(true);
                $result = empty($start_state['missing_table']) ? $digest->process_queue() : $start_state;
                $state = $digest->get_processing_state();

                if (!empty($start_state['missing_table'])) {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('The free alert digest queue table is missing. Create it first before starting processing.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Free digest processing started. Batch processed: %1$d jobs, sent: %2$d, failed: %3$d. Overall progress: %4$d / %5$d jobs.', 'senna-finance'),
                            (int) ($result['processed'] ?? 0),
                            (int) ($result['sent'] ?? 0),
                            (int) ($result['failed'] ?? 0),
                            (int) ($state['processed'] ?? 0),
                            (int) ($state['total_jobs'] ?? 0)
                        ) .
                        '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_pause_free_digest_processing']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $state = SFFC_CRM_Free_Alert_Digest::get_instance()->pause_processing();
                if (!empty($state['paused'])) {
                    echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('Free digest processing paused. Already-sent jobs are preserved and pending jobs will remain queued.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('There was no running free digest processing job to pause.', 'senna-finance') . '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_resume_free_digest_processing']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $digest = SFFC_CRM_Free_Alert_Digest::get_instance();
                $resume_state = $digest->resume_processing();
                if (!empty($resume_state['resumed'])) {
                    $result = $digest->process_queue();
                    $state = $digest->get_processing_state();
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Free digest processing resumed. Batch processed: %1$d jobs, sent: %2$d, failed: %3$d. Overall progress: %4$d / %5$d jobs.', 'senna-finance'),
                            (int) ($result['processed'] ?? 0),
                            (int) ($result['sent'] ?? 0),
                            (int) ($result['failed'] ?? 0),
                            (int) ($state['processed'] ?? 0),
                            (int) ($state['total_jobs'] ?? 0)
                        ) .
                        '</p></div>';
                } else {
                    echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('There was no paused free digest processing job to resume.', 'senna-finance') . '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_process_free_digest_queue_now']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                $result = SFFC_CRM_Free_Alert_Digest::get_instance()->process_queue();
                if (!empty($result['missing_table'])) {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('The free alert digest queue table is missing. Create it first before processing digests.', 'senna-finance') . '</p></div>';
                } elseif (!empty($result['locked'])) {
                    echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('The free alert digest worker is already running. Wait a moment and try again.', 'senna-finance') . '</p></div>';
                } elseif (!empty($result['empty'])) {
                    echo '<div class="notice notice-info is-dismissible"><p>' . esc_html__('No queued free digest jobs were ready to process.', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-success is-dismissible"><p>' .
                        sprintf(
                            esc_html__('Free digest queue processed. %1$d jobs checked, %2$d sent, %3$d failed.', 'senna-finance'),
                            (int) ($result['processed'] ?? 0),
                            (int) ($result['sent'] ?? 0),
                            (int) ($result['failed'] ?? 0)
                        ) .
                        '</p></div>';
                }
            }
        }

        if (isset($_POST['sffc_crm_schedule_premium_batches_now']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            if (class_exists('SFFC_CRM_Internship_Alert_Queue')) {
                $result = SFFC_CRM_Internship_Alert_Queue::get_instance()->schedule_pending_batches();
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(
                        esc_html__('Premium pending batches scheduled. Submitted %1$d recipients across %2$d batch requests.', 'senna-finance'),
                        (int) ($result['submitted'] ?? 0),
                        (int) ($result['batches'] ?? 0)
                    ) .
                    '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_enqueue_alerts_for_post']) && wp_verify_nonce($_POST['crm_alert_manual_ops_nonce'] ?? '', 'sffc_crm_alert_manual_ops') && !(function_exists('sffc_crm_internship_alerts_disabled') && sffc_crm_internship_alerts_disabled())) {
            $manual_post_id = max(0, intval($_POST['sffc_crm_manual_alert_post_id'] ?? 0));
            if ($manual_post_id <= 0) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Enter a valid CRM post ID before enqueueing alerts.', 'senna-finance') . '</p></div>';
            } elseif (class_exists('SFFC_CRM_Internship_Alert_Queue')) {
                $result = SFFC_CRM_Internship_Alert_Queue::get_instance()->enqueue_post_alerts($manual_post_id);
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(
                        esc_html__('Post %1$d re-queued for alerts. %2$d users matched, %3$d premium recipients queued, %4$d free users marked for digest flow.', 'senna-finance'),
                        $manual_post_id,
                        (int) ($result['matched'] ?? 0),
                        (int) ($result['queued'] ?? 0),
                        (int) ($result['digest_matched'] ?? 0)
                    ) .
                    '</p></div>';
            }
        }

        // Handle HR Outreach prep columns addition
        if (isset($_POST['sffc_crm_add_hr_outreach_columns']) && wp_verify_nonce($_POST['crm_hr_outreach_columns_nonce'], 'sffc_crm_add_hr_outreach_columns')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();

            // Call create_tables() which will run migrations and add new columns
            $schema->create_tables();

            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('HR Outreach prep columns added successfully! Database schema has been updated.', 'senna-finance') . '</p></div>';
        }

        // Handle Post prep material columns addition
        if (isset($_POST['sffc_crm_add_post_prep_columns']) && wp_verify_nonce($_POST['crm_post_prep_columns_nonce'], 'sffc_crm_add_post_prep_columns')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();

            // Force the repair so missing columns are added even on installs already marked up to date.
            $schema->force_schema_update();

            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Post prep material columns and resource library case study fields updated successfully.', 'senna-finance') . '</p></div>';
        }

        if (isset($_POST['sffc_crm_create_prep_library_table']) && wp_verify_nonce($_POST['crm_prep_library_nonce'] ?? '', 'sffc_crm_manage_prep_library')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_prep_library_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_prep_library';
            $table_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;

            if ($table_exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Prep library table created successfully.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the prep library table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_resource_library_table']) && wp_verify_nonce($_POST['crm_resource_library_nonce'] ?? '', 'sffc_crm_manage_resource_library')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_resource_library_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_resource_library';
            $table_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;
            $case_study_column_exists = false;

            if ($table_exists) {
                $case_study_column_exists = (bool) $wpdb->get_var($wpdb->prepare(
                    "SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = %s
                       AND TABLE_NAME = %s
                       AND COLUMN_NAME = %s",
                    DB_NAME,
                    $table,
                    'is_case_study'
                ));
            }

            if ($table_exists && $case_study_column_exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Resource library table updated successfully, including the case study flag column.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create or repair the resource library table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_expert_qa_table']) && wp_verify_nonce($_POST['crm_expert_qa_nonce'] ?? '', 'sffc_crm_create_expert_qa_table')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_expert_qa_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_expert_qa';
            $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;

            if ($exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Expert Q&A table ready. You can now capture questions from the dashboard.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the Expert Q&A table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_internship_alert_queue_table']) && wp_verify_nonce($_POST['crm_internship_alert_queue_nonce'] ?? '', 'sffc_crm_create_internship_alert_queue_table')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_internship_alert_queue_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_internship_alert_queue';
            $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;

            if ($exists) {
                if (class_exists('SFFC_CRM_Internship_Alert_Queue')) {
                    $queue = SFFC_CRM_Internship_Alert_Queue::get_instance();
                    $queue->schedule_cron();
                    if (get_option('sffc_crm_internship_alert_transport', 'sendgrid_api') === 'sendgrid_api' && !get_option('sffc_crm_internship_alert_queue_paused', false)) {
                        $queue->schedule_pending_batches();
                    }
                }
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Role alert queue table created successfully.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the internship alert queue table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_free_alert_digest_queue_table']) && wp_verify_nonce($_POST['crm_free_alert_digest_queue_nonce'] ?? '', 'sffc_crm_create_free_alert_digest_queue_table')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_free_alert_digest_queue_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_free_alert_digest_queue';
            $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;

            if ($exists) {
                if (class_exists('SFFC_CRM_Free_Alert_Digest')) {
                    SFFC_CRM_Free_Alert_Digest::get_instance()->schedule_event();
                }
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Free alert digest queue table created successfully.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the free alert digest queue table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_dashboard_insights_table']) && wp_verify_nonce($_POST['crm_dashboard_insights_table_nonce'] ?? '', 'sffc_crm_create_dashboard_insights_table')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_dashboard_insights_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_dashboard_insights';
            $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;

            if ($exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Dashboard insights table created successfully. Claude-backed home insight cards can now persist daily results in the database.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the dashboard insights table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_recommended_job_interactions_table']) && wp_verify_nonce($_POST['crm_recommended_job_interactions_table_nonce'] ?? '', 'sffc_crm_create_recommended_job_interactions_table')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_recommended_job_interactions_table();

            global $wpdb;
            $table = $wpdb->prefix . 'sffc_crm_recommended_job_interactions';
            $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) === $table;

            if ($exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Recommended jobs interaction table created successfully. Logged-in recommendation history can now be stored in the database.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the recommended jobs interaction table. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_create_alert_default_profile_tables']) && wp_verify_nonce($_POST['crm_alert_default_profile_tables_nonce'] ?? '', 'sffc_crm_create_alert_default_profile_tables')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-database-schema.php';
            $schema = SFFC_CRM_Database_Schema::get_instance();
            $schema->create_alert_default_profile_tables();

            global $wpdb;
            $profiles_table = $wpdb->prefix . 'sffc_crm_alert_default_profiles';
            $assignments_table = $wpdb->prefix . 'sffc_crm_alert_profile_users';
            $profiles_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $profiles_table)) === $profiles_table;
            $assignments_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $assignments_table)) === $assignments_table;

            if ($profiles_exists && $assignments_exists) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Default alert profile tables created successfully.', 'senna-finance') . '</p></div>';
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to create the default alert profile tables. Please check database permissions.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_save_alert_default_profile']) && wp_verify_nonce($_POST['crm_alert_default_profile_nonce'] ?? '', 'sffc_crm_save_alert_default_profile')) {
            $profile_id = intval($_POST['alert_default_profile_id'] ?? 0);
            $result = sffc_crm_save_alert_default_profile($profile_id, [
                'name' => wp_unslash($_POST['alert_default_profile_name'] ?? ''),
                'description' => wp_unslash($_POST['alert_default_profile_description'] ?? ''),
                'enabled' => !empty($_POST['alert_default_profile_enabled']),
                'sectors' => isset($_POST['alert_default_profile_sectors']) ? (array) $_POST['alert_default_profile_sectors'] : [],
                'types' => isset($_POST['alert_default_profile_types']) ? (array) $_POST['alert_default_profile_types'] : [],
                'locations' => wp_unslash($_POST['alert_default_profile_locations'] ?? ''),
                'work_modes' => isset($_POST['alert_default_profile_work_modes']) ? (array) $_POST['alert_default_profile_work_modes'] : [],
                'groups' => isset($_POST['alert_default_profile_groups']) ? (array) $_POST['alert_default_profile_groups'] : [],
                'is_active' => !empty($_POST['alert_default_profile_is_active']),
            ]);

            if (is_wp_error($result)) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html($result->get_error_message()) . '</p></div>';
            } else {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Default alert profile saved successfully.', 'senna-finance') . '</p></div>';
                $_GET['alert_profile_id'] = (string) intval($result);
            }
        }

        if (isset($_POST['sffc_crm_test_alert_default_profile']) && wp_verify_nonce($_POST['crm_alert_default_profile_nonce'] ?? '', 'sffc_crm_save_alert_default_profile')) {
            $raw_test_emails = wp_unslash($_POST['alert_default_profile_test_emails'] ?? '');
            $test_emails = preg_split('/[\s,]+/', $raw_test_emails);
            $test_emails = array_values(array_unique(array_filter(array_map('sanitize_email', (array) $test_emails))));
            $test_emails = array_slice($test_emails, 0, 10);

            if (empty($test_emails)) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Add at least one valid test email address in the profile editor test field.', 'senna-finance') . '</p></div>';
            } else {
                $profile_prefs = sffc_crm_normalize_alert_preferences([
                    'enabled' => !empty($_POST['alert_default_profile_enabled']),
                    'sectors' => isset($_POST['alert_default_profile_sectors']) ? (array) $_POST['alert_default_profile_sectors'] : [],
                    'types' => isset($_POST['alert_default_profile_types']) ? (array) $_POST['alert_default_profile_types'] : [],
                    'locations' => wp_unslash($_POST['alert_default_profile_locations'] ?? ''),
                    'work_modes' => isset($_POST['alert_default_profile_work_modes']) ? (array) $_POST['alert_default_profile_work_modes'] : [],
                    'groups' => isset($_POST['alert_default_profile_groups']) ? (array) $_POST['alert_default_profile_groups'] : [],
                ]);

                $matches = sffc_crm_get_matching_internship_posts_for_alerts($profile_prefs, [
                    'limit' => 6,
                    'scan_limit' => 300,
                    'max_digest_repeats' => 2,
                ]);

                if (empty($matches['posts'])) {
                    echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('No active roles currently match this default alert profile, so no test emails were sent.', 'senna-finance') . '</p></div>';
                } else {
                    $digest_sent = 0;
                    $instant_sent = 0;
                    $test_posts = array_values((array) $matches['posts']);
                    if (count($test_posts) > 1) {
                        shuffle($test_posts);
                    }

                    foreach ($test_emails as $index => $test_email) {
                        $test_user = (object) [
                            'ID' => get_current_user_id(),
                            'display_name' => 'MENA Careers Test User',
                            'user_email' => $test_email,
                        ];
                        $assigned_post = $test_posts[$index] ?? null;
                        if (!$assigned_post && !empty($test_posts)) {
                            $assigned_post = $test_posts[$index % count($test_posts)];
                        }
                        if (!$assigned_post) {
                            continue;
                        }

                        if (sffc_crm_send_free_alert_digest_email($test_user, [$assigned_post], $profile_prefs, [
                            'is_test' => true,
                            'total_matches' => (int) ($matches['total'] ?? count($matches['posts'])),
                            'manage_url' => admin_url('admin.php?page=sffc-crm-settings'),
                            'destination_url' => sffc_crm_get_alert_digest_destination_url(),
                            'upgrade_url' => sffc_crm_get_alert_membership_upgrade_url(),
                            'last_sent_at' => date('Y-m-d H:i:s', current_time('timestamp') - DAY_IN_SECONDS),
                        ])) {
                            $digest_sent++;
                        }

                        if (sffc_crm_send_alert_email($test_user, $assigned_post, [
                            'is_test' => true,
                            'manage_url' => admin_url('admin.php?page=sffc-crm-settings'),
                        ])) {
                            $instant_sent++;
                        }
                    }

                    if ($digest_sent > 0 || $instant_sent > 0) {
                        echo '<div class="notice notice-success is-dismissible"><p>' .
                            sprintf(
                                esc_html__('Profile test sent. Single-role intro emails: %1$d. Instant alert emails: %2$d.', 'senna-finance'),
                                $digest_sent,
                                $instant_sent
                            ) .
                            '</p></div>';
                    } else {
                        echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('The profile test emails could not be sent. Check the email addresses and mail configuration.', 'senna-finance') . '</p></div>';
                    }
                }
            }
        }

        if (isset($_POST['sffc_crm_delete_alert_default_profile']) && wp_verify_nonce($_POST['crm_delete_alert_default_profile_nonce'] ?? '', 'sffc_crm_delete_alert_default_profile')) {
            $deleted = sffc_crm_delete_alert_default_profile(intval($_POST['alert_default_profile_id'] ?? 0));
            if ($deleted) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Default alert profile deleted successfully.', 'senna-finance') . '</p></div>';
                unset($_GET['alert_profile_id']);
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to delete the default alert profile.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_assign_alert_default_profile']) && wp_verify_nonce($_POST['crm_assign_alert_default_profile_nonce'] ?? '', 'sffc_crm_assign_alert_default_profile')) {
            $profile_id = intval($_POST['bulk_alert_default_profile_id'] ?? 0);
            $user_ids = array_filter(array_map('intval', (array) ($_POST['alert_default_profile_user_ids'] ?? [])));
            $processed = sffc_crm_assign_alert_default_profile_to_users($profile_id, $user_ids, get_current_user_id());

            if ($processed > 0) {
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(esc_html__('%d user(s) were assigned to the selected default alert profile.', 'senna-finance'), $processed) .
                    '</p></div>';
            } else {
                echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('No users were assigned. Select at least one user and a valid default profile.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_assign_alert_default_profile_all']) && wp_verify_nonce($_POST['crm_assign_alert_default_profile_nonce'] ?? '', 'sffc_crm_assign_alert_default_profile')) {
            $profile_id = intval($_POST['bulk_alert_default_profile_id'] ?? 0);
            $user_ids = get_users([
                'fields' => 'ids',
            ]);
            $processed = sffc_crm_assign_alert_default_profile_to_users($profile_id, $user_ids, get_current_user_id());

            if ($processed > 0) {
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(esc_html__('%d user(s) were assigned to the selected default alert profile across the full platform.', 'senna-finance'), $processed) .
                    '</p></div>';
            } else {
                echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('No users were assigned. Choose a valid default profile before using assign to all users.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_clear_alert_default_profile']) && wp_verify_nonce($_POST['crm_assign_alert_default_profile_nonce'] ?? '', 'sffc_crm_assign_alert_default_profile')) {
            $user_ids = array_filter(array_map('intval', (array) ($_POST['alert_default_profile_user_ids'] ?? [])));
            $processed = sffc_crm_clear_alert_default_profiles_for_users($user_ids);

            if ($processed > 0) {
                echo '<div class="notice notice-success is-dismissible"><p>' .
                    sprintf(esc_html__('%d user assignment(s) were cleared.', 'senna-finance'), $processed) .
                    '</p></div>';
            } else {
                echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('No user assignments were cleared. Select at least one assigned user.', 'senna-finance') . '</p></div>';
            }
        }

        if (isset($_POST['sffc_crm_save_email_user_groups']) && wp_verify_nonce($_POST['crm_email_user_groups_nonce'] ?? '', 'sffc_crm_email_user_groups')) {
            $groups = $this->get_email_user_groups();
            $submitted_groups = isset($_POST['sffc_crm_email_user_groups']) && is_array($_POST['sffc_crm_email_user_groups'])
                ? wp_unslash($_POST['sffc_crm_email_user_groups'])
                : [];
            $updated_groups = [];

            foreach ($submitted_groups as $group) {
                $old_key = sanitize_key($group['old_key'] ?? '');
                $key = sanitize_key($group['key'] ?? '');
                $name = sanitize_text_field($group['name'] ?? '');
                $description = sanitize_textarea_field($group['description'] ?? '');

                if (!empty($group['delete'])) {
                    continue;
                }
                if ($key === '' && $name !== '') {
                    $key = sanitize_key($name);
                }
                if ($key === '' || $name === '') {
                    continue;
                }

                $existing = $groups[$old_key] ?? $groups[$key] ?? [];
                $updated_groups[$key] = [
                    'key' => $key,
                    'name' => $name,
                    'description' => $description,
                    'user_ids' => array_values(array_unique(array_filter(array_map('intval', (array) ($existing['user_ids'] ?? []))))),
                ];
            }

            update_option('sffc_crm_email_user_groups', $updated_groups, false);
            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Email user groups saved.', 'senna-finance') . '</p></div>';
        }

        if (isset($_POST['sffc_crm_update_email_group_users']) && wp_verify_nonce($_POST['crm_email_group_users_nonce'] ?? '', 'sffc_crm_email_group_users')) {
            $group_key = sanitize_key($_POST['sffc_crm_email_group_key'] ?? '');
            $action = sanitize_key($_POST['sffc_crm_email_group_action'] ?? 'add');
            $apply_to_all_users = !empty($_POST['sffc_crm_email_group_all_users']);
            $user_ids = array_values(array_unique(array_filter(array_map('intval', (array) ($_POST['sffc_crm_email_group_user_ids'] ?? [])))));
            $groups = $this->get_email_user_groups();

            if ($apply_to_all_users) {
                $user_ids = array_values(array_filter(array_map('intval', (array) get_users([
                    'fields' => 'ID',
                ]))));
            }

            if ($group_key === '' || empty($groups[$group_key])) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Choose a valid email group before updating users.', 'senna-finance') . '</p></div>';
            } elseif (empty($user_ids)) {
                echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__($apply_to_all_users ? 'No users were found to update in this email group.' : 'Select at least one user before updating the email group.', 'senna-finance') . '</p></div>';
            } else {
                $current_user_ids = array_values(array_unique(array_filter(array_map('intval', (array) ($groups[$group_key]['user_ids'] ?? [])))));
                if ($action === 'remove') {
                    $groups[$group_key]['user_ids'] = array_values(array_diff($current_user_ids, $user_ids));
                    $message = $apply_to_all_users
                        ? sprintf(esc_html__('Removed all %1$d user(s) from %2$s.', 'senna-finance'), count($user_ids), $groups[$group_key]['name'])
                        : sprintf(esc_html__('Removed %1$d selected user(s) from %2$s.', 'senna-finance'), count($user_ids), $groups[$group_key]['name']);
                } else {
                    $groups[$group_key]['user_ids'] = array_values(array_unique(array_merge($current_user_ids, $user_ids)));
                    $message = $apply_to_all_users
                        ? sprintf(esc_html__('Added all %1$d user(s) to %2$s.', 'senna-finance'), count($user_ids), $groups[$group_key]['name'])
                        : sprintf(esc_html__('Added %1$d selected user(s) to %2$s.', 'senna-finance'), count($user_ids), $groups[$group_key]['name']);
                }

                update_option('sffc_crm_email_user_groups', $groups, false);
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html($message) . '</p></div>';
            }
        }

        // Handle Live Expert Chat tables creation
        if (isset($_POST['sffc_crm_create_live_expert_tables']) && wp_verify_nonce($_POST['crm_live_expert_tables_nonce'], 'sffc_crm_create_live_expert_tables')) {
            if (class_exists('SFFC_Live_Expert_Messaging')) {
                $messaging = SFFC_Live_Expert_Messaging::get_instance();
                $messaging->maybe_create_tables();

                global $wpdb;
                $conversations_table = $wpdb->prefix . 'sffc_live_conversations';
                $messages_table = $wpdb->prefix . 'sffc_live_messages';

                $conv_exists = $wpdb->get_var("SHOW TABLES LIKE '$conversations_table'") === $conversations_table;
                $msg_exists = $wpdb->get_var("SHOW TABLES LIKE '$messages_table'") === $messages_table;

                if ($conv_exists && $msg_exists) {
                    echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Live Expert Chat tables created successfully!', 'senna-finance') . '</p></div>';
                } else {
                    echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Failed to create Live Expert Chat tables. Error: ', 'senna-finance') . esc_html($wpdb->last_error) . '</p></div>';
                }
            } else {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Live Expert Messaging class not found. Please ensure the plugin files are loaded correctly.', 'senna-finance') . '</p></div>';
            }
        }

        // Handle form submission
        if (isset($_POST['sffc_crm_save_settings']) && wp_verify_nonce($_POST['crm_settings_nonce'], 'sffc_crm_settings')) {
            $this->save_crm_settings();
            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Settings saved successfully!', 'senna-finance') . '</p></div>';
        }

        // Get current settings
        $settings = get_option('sffc_crm_header_settings', []);
        $defaults = [
            'logo_url' => '',
            'title' => 'MENA Careers Recruiter Match CRM',
            'show_user_dropdown' => true,
            'menu_items' => [
                ['label' => 'Profile', 'url' => '/profile/', 'icon' => 'user'],
                ['label' => 'MENA Careers AI', 'url' => '/senna-ai/', 'icon' => 'cpu'],
            ],
        ];
        $settings = wp_parse_args($settings, $defaults);
        $console_search_style_settings = [
            'sffc_crm_console_landing_bg' => ['label' => __('Terminal Landing Background', 'senna-finance'), 'default' => '#0D353E'],
            'sffc_crm_console_search_mode_bg' => ['label' => __('Mode Dropdown Background', 'senna-finance'), 'default' => 'transparent'],
            'sffc_crm_console_search_mode_text' => ['label' => __('Mode Dropdown Text', 'senna-finance'), 'default' => '#ffffff'],
            'sffc_crm_console_search_mode_border' => ['label' => __('Mode Dropdown Border', 'senna-finance'), 'default' => 'rgba(255, 255, 255, 0.34)'],
            'sffc_crm_console_search_field_bg' => ['label' => __('Field Background', 'senna-finance'), 'default' => '#ffffff'],
            'sffc_crm_console_search_field_border' => ['label' => __('Field Divider Border', 'senna-finance'), 'default' => '#d8dee7'],
            'sffc_crm_console_search_field_radius' => ['label' => __('Field Radius', 'senna-finance'), 'default' => '8px'],
            'sffc_crm_console_search_label_color' => ['label' => __('Field Label Text', 'senna-finance'), 'default' => '#5f6671'],
            'sffc_crm_console_search_input_color' => ['label' => __('Field Value Text', 'senna-finance'), 'default' => '#111827'],
            'sffc_crm_console_search_dropdown_bg' => ['label' => __('Dropdown Surface', 'senna-finance'), 'default' => '#ffffff'],
            'sffc_crm_console_search_dropdown_text' => ['label' => __('Dropdown Text', 'senna-finance'), 'default' => '#111827'],
            'sffc_crm_console_search_dropdown_hover_bg' => ['label' => __('Dropdown Hover Background', 'senna-finance'), 'default' => '#f3f6fb'],
            'sffc_crm_console_search_dropdown_border' => ['label' => __('Dropdown Border', 'senna-finance'), 'default' => 'rgba(17, 24, 39, 0.12)'],
            'sffc_crm_console_search_dropdown_radius' => ['label' => __('Dropdown Radius', 'senna-finance'), 'default' => '8px'],
            'sffc_crm_console_search_dropdown_shadow' => ['label' => __('Dropdown Shadow', 'senna-finance'), 'default' => '0 18px 45px rgba(15, 23, 42, 0.18)'],
            'sffc_crm_console_search_button_bg' => ['label' => __('Search Button Background', 'senna-finance'), 'default' => '#9AF2BD'],
            'sffc_crm_console_search_button_hover_bg' => ['label' => __('Search Button Hover Background', 'senna-finance'), 'default' => '#7CE6A9'],
            'sffc_crm_console_search_button_text' => ['label' => __('Search Button Text', 'senna-finance'), 'default' => '#0D353E'],
            'sffc_crm_console_search_secondary_bg' => ['label' => __('Add/Save Button Background', 'senna-finance'), 'default' => '#ffffff'],
            'sffc_crm_console_search_secondary_text' => ['label' => __('Add/Save Button Text', 'senna-finance'), 'default' => '#111827'],
        ];

        // Enqueue media uploader
        wp_enqueue_media();
        wp_enqueue_style('wp-color-picker');
        wp_enqueue_script('wp-color-picker');
        $gmail_client_id = get_option('sffc_crm_gmail_client_id', '');
        $gmail_client_secret = get_option('sffc_crm_gmail_client_secret', '');
        $outlook_client_id = get_option('sffc_crm_outlook_client_id', '');
        $outlook_client_secret = get_option('sffc_crm_outlook_client_secret', '');
        $outlook_tenant = get_option('sffc_crm_outlook_tenant', 'common');
        $email_mode = get_option('sffc_crm_email_mode', 'oauth');
        $internship_alert_transport = get_option('sffc_crm_internship_alert_transport', 'sendgrid_api');
        $sendgrid_alert_api_key = get_option('sffc_crm_sendgrid_alert_api_key', '');
        $sendgrid_alert_from_email = get_option('sffc_crm_sendgrid_alert_from_email', 'support.team@joinsenna.com');
        $sendgrid_alert_from_name = get_option('sffc_crm_sendgrid_alert_from_name', 'MENA Careers');
        $email_senders = function_exists('sffc_crm_get_email_senders') ? sffc_crm_get_email_senders() : [];
        $email_sender_contexts = function_exists('sffc_crm_get_email_sender_contexts') ? sffc_crm_get_email_sender_contexts() : [];
        $email_sender_context_labels = function_exists('sffc_crm_get_email_sender_context_labels') ? sffc_crm_get_email_sender_context_labels() : [];
        $internship_alert_batch_size = (int) get_option('sffc_crm_internship_alert_batch_size', 25);
        $internship_alert_spacing_minutes = (int) get_option('sffc_crm_internship_alert_spacing_minutes', 5);
        $internship_alert_initial_delay_minutes = (int) get_option('sffc_crm_internship_alert_initial_delay_minutes', 0);
        $internship_alert_max_attempts = (int) get_option('sffc_crm_internship_alert_max_attempts', 5);
        $premium_match_instant_threshold = (int) get_option('sffc_crm_premium_match_instant_threshold', 85);
        $premium_match_digest_threshold = (int) get_option('sffc_crm_premium_match_digest_threshold', 65);
        $premium_match_scan_limit = (int) get_option('sffc_crm_premium_match_scan_limit', 100);
        $internship_alert_queue_paused = (bool) get_option('sffc_crm_internship_alert_queue_paused', false);
        $alert_email_sending_disabled = (bool) get_option('sffc_crm_alert_email_sending_disabled', false);
        $top_match_email_disabled = (bool) get_option('sffc_crm_top_match_email_disabled', false);
        $excluded_users_raw = (string) get_option('sffc_crm_excluded_users', '');
        $exit_discount_coupon_code = get_option('sffc_crm_exit_discount_coupon_code', '');
        $exit_discount_rate = (int) get_option('sffc_crm_exit_discount_rate', 20);
        $internship_alert_stats = [
            'queue_exists' => false,
            'events_exists' => false,
            'counts' => [
                'pending' => 0,
                'retry' => 0,
                'processing' => 0,
                'scheduled' => 0,
                'sent' => 0,
                'failed' => 0,
                'skipped' => 0,
            ],
            'delivery_counts' => [
                'scheduled' => 0,
                'processed' => 0,
                'delivered' => 0,
                'deferred' => 0,
                'opened' => 0,
                'clicked' => 0,
                'bounced' => 0,
                'dropped' => 0,
                'spamreport' => 0,
                'unsubscribed' => 0,
            ],
            'total' => 0,
        ];
        $internship_alert_recent_batches = [];
        $internship_alert_recent_events = [];
        $internship_alert_last_queue_run = get_option('sffc_crm_last_internship_alert_queue_run', []);
        $internship_alert_last_submission = get_option('sffc_crm_last_internship_alert_submission', []);
        $internship_alert_last_processed = get_option('sffc_crm_last_internship_alert_processed_at', '');
        $internship_alert_last_webhook_received = get_option('sffc_crm_last_sendgrid_webhook_received_at', '');
        $internship_alert_last_delivery_event = get_option('sffc_crm_last_sendgrid_delivery_event', []);
        $direct_apply_followup_last_submission = get_option('sffc_crm_last_direct_apply_followup_submission', []);
        $direct_apply_followup_last_error = get_option('sffc_crm_last_direct_apply_followup_error', []);
        $free_digest_build_state = class_exists('SFFC_CRM_Free_Alert_Digest') ? SFFC_CRM_Free_Alert_Digest::get_instance()->get_build_state() : [];
        $free_digest_process_state = class_exists('SFFC_CRM_Free_Alert_Digest') ? SFFC_CRM_Free_Alert_Digest::get_instance()->get_processing_state() : [];
        $free_digest_build_checked = (int) ($free_digest_build_state['checked'] ?? 0);
        $free_digest_build_total = max(0, (int) ($free_digest_build_state['total_users'] ?? 0));
        $free_digest_build_percent = $free_digest_build_total > 0 ? min(100, max(0, (int) round(($free_digest_build_checked / $free_digest_build_total) * 100))) : 0;
        $free_digest_process_processed = (int) ($free_digest_process_state['processed'] ?? 0);
        $free_digest_process_total = max(0, (int) ($free_digest_process_state['total_jobs'] ?? 0));
        $free_digest_process_percent = $free_digest_process_total > 0 ? min(100, max(0, (int) round(($free_digest_process_processed / $free_digest_process_total) * 100))) : 0;
        $internship_alert_next_cron = wp_next_scheduled('sffc_crm_process_internship_alert_queue');
        $sendgrid_ready = class_exists('SFFC_CRM_SendGrid_Service') ? SFFC_CRM_SendGrid_Service::get_instance()->is_configured() : false;
        $sendgrid_webhook = class_exists('SFFC_CRM_SendGrid_Webhook') ? SFFC_CRM_SendGrid_Webhook::get_instance() : null;
        $sendgrid_webhook_url = $sendgrid_webhook ? $sendgrid_webhook->get_webhook_url() : '';
        $sendgrid_webhook_token = $sendgrid_webhook ? $sendgrid_webhook->get_webhook_token() : '';
        $alert_default_profiles = function_exists('sffc_crm_get_alert_default_profiles') ? sffc_crm_get_alert_default_profiles() : [];
        $email_user_groups = $this->get_email_user_groups();
        $editing_alert_profile_id = intval($_GET['alert_profile_id'] ?? 0);
        $editing_alert_profile = $editing_alert_profile_id > 0 ? sffc_crm_get_alert_default_profile($editing_alert_profile_id) : null;
        $alert_default_profile_draft = $editing_alert_profile ?: [
            'id' => 0,
            'name' => '',
            'description' => '',
            'enabled' => true,
            'sectors' => [],
            'types' => [],
            'locations' => [],
            'work_modes' => [],
            'groups' => [],
            'is_active' => true,
        ];
        $alert_default_user_search = sanitize_text_field($_GET['alert_default_user_search'] ?? '');
        $alert_default_user_page = max(1, intval($_GET['alert_default_user_page'] ?? 1));
        $alert_default_users_per_page = 100;

        global $wpdb;
        $internship_alert_queue_table = $wpdb->prefix . 'sffc_crm_internship_alert_queue';
        $internship_alert_events_table = $wpdb->prefix . 'sffc_crm_sendgrid_events';
        $alert_default_profiles_table = $wpdb->prefix . 'sffc_crm_alert_default_profiles';
        $alert_profile_users_table = $wpdb->prefix . 'sffc_crm_alert_profile_users';
        $internship_alert_stats['queue_exists'] = $this->settings_page_table_exists($internship_alert_queue_table, $settings_schema_snapshot);
        $internship_alert_stats['events_exists'] = $this->settings_page_table_exists($internship_alert_events_table, $settings_schema_snapshot);
        $alert_default_profiles_tables_ready = (
            $this->settings_page_table_exists($alert_default_profiles_table, $settings_schema_snapshot) &&
            $this->settings_page_table_exists($alert_profile_users_table, $settings_schema_snapshot)
        );
        if ($internship_alert_stats['queue_exists']) {
            $status_rows = $wpdb->get_results(
                "SELECT status, COUNT(*) as total
                 FROM {$internship_alert_queue_table}
                 GROUP BY status",
                ARRAY_A
            );

            foreach ((array) $status_rows as $row) {
                $status_key = sanitize_key($row['status'] ?? '');
                if (array_key_exists($status_key, $internship_alert_stats['counts'])) {
                    $internship_alert_stats['counts'][$status_key] = (int) $row['total'];
                    $internship_alert_stats['total'] += (int) $row['total'];
                }
            }

            $delivery_rows = $wpdb->get_results(
                "SELECT delivery_status, COUNT(*) as total
                 FROM {$internship_alert_queue_table}
                 WHERE delivery_status IS NOT NULL AND delivery_status <> ''
                 GROUP BY delivery_status",
                ARRAY_A
            );

            foreach ((array) $delivery_rows as $row) {
                $delivery_key = sanitize_key($row['delivery_status'] ?? '');
                if (array_key_exists($delivery_key, $internship_alert_stats['delivery_counts'])) {
                    $internship_alert_stats['delivery_counts'][$delivery_key] = (int) $row['total'];
                }
            }

            $internship_alert_recent_batches = $wpdb->get_results(
                "SELECT
                    COALESCE(NULLIF(provider_reference, ''), CONCAT('manual-', DATE_FORMAT(submitted_at, '%Y%m%d%H%i%s'), '-', post_id)) AS batch_reference,
                    delivery_transport,
                    submitted_at,
                    scheduled_for,
                    post_id,
                    COUNT(*) AS recipients
                 FROM {$internship_alert_queue_table}
                 WHERE submitted_at IS NOT NULL
                 GROUP BY batch_reference, delivery_transport, submitted_at, scheduled_for, post_id
                 ORDER BY submitted_at DESC
                 LIMIT 10",
                ARRAY_A
            ) ?: [];
        }

        if ($internship_alert_stats['events_exists']) {
            $internship_alert_recent_events = $wpdb->get_results(
                "SELECT
                    id,
                    queue_id,
                    post_id,
                    user_id,
                    email,
                    event_type,
                    event_at,
                    provider_reference,
                    reason
                 FROM {$internship_alert_events_table}
                 ORDER BY event_at DESC, id DESC
                 LIMIT 15",
                ARRAY_A
            ) ?: [];
        }

        $alert_default_user_query_args = [
            'number' => $alert_default_users_per_page,
            'paged' => $alert_default_user_page,
            'orderby' => 'display_name',
            'order' => 'ASC',
            'count_total' => true,
        ];
        if ($alert_default_user_search !== '') {
            $alert_default_user_query_args['search'] = '*' . $alert_default_user_search . '*';
            $alert_default_user_query_args['search_columns'] = ['user_login', 'user_email', 'display_name'];
        }
        $alert_default_users_query = new WP_User_Query($alert_default_user_query_args);
        $alert_default_users = $alert_default_users_query->get_results();
        $alert_default_total_users = intval($alert_default_users_query->get_total());
        $alert_default_total_pages = max(1, (int) ceil($alert_default_total_users / $alert_default_users_per_page));
        $alert_default_user_ids = array_map(function ($user) {
            return (int) $user->ID;
        }, (array) $alert_default_users);
        $alert_default_user_assignments = [];

        if (!empty($alert_default_user_ids) && $alert_default_profiles_tables_ready) {
            $placeholders = implode(',', array_fill(0, count($alert_default_user_ids), '%d'));
            $assignment_rows = $wpdb->get_results($wpdb->prepare(
                "SELECT apu.user_id, apu.profile_id, p.name
                 FROM {$alert_profile_users_table} apu
                 INNER JOIN {$alert_default_profiles_table} p ON p.id = apu.profile_id
                 WHERE apu.user_id IN ({$placeholders})",
                $alert_default_user_ids
            ), ARRAY_A);

            foreach ((array) $assignment_rows as $assignment_row) {
                $alert_default_user_assignments[(int) $assignment_row['user_id']] = [
                    'profile_id' => (int) $assignment_row['profile_id'],
                    'profile_name' => sanitize_text_field($assignment_row['name'] ?? ''),
                ];
            }
        }

        $alert_default_user_pagination_base = add_query_arg([
            'page' => 'sffc-crm-settings',
            'alert_default_user_search' => $alert_default_user_search,
            'alert_default_user_page' => '%#%',
        ], admin_url('admin.php'));
        $alert_default_user_pagination = '';
        if ($alert_default_total_pages > 1) {
            $alert_default_user_pagination = paginate_links([
                'base' => $alert_default_user_pagination_base,
                'format' => '',
                'current' => $alert_default_user_page,
                'total' => $alert_default_total_pages,
                'prev_text' => __('&laquo;', 'senna-finance'),
                'next_text' => __('&raquo;', 'senna-finance'),
            ]);
        }

    ?>
