            <script>
                (function() {
                    var csvInput = document.getElementById('sffc_crm_custom_email_csv');
                    var preview = document.querySelector('[data-sffc-custom-email-csv-preview]');
                    var mapFields = Array.prototype.slice.call(document.querySelectorAll('[data-sffc-csv-map-field]'));
                    var templateSelect = document.querySelector('[data-sffc-custom-email-template]');
                    var subjectInput = document.getElementById('sffc_crm_custom_email_subject');
                    var bodyTextarea = document.getElementById('sffc_crm_custom_email_body_editor');
                    var recipientsTextarea = document.getElementById('sffc_crm_custom_email_recipients');
                    var currentCsvRows = [];
                    var currentCsvHeaders = [];
                    var templates = {
                        gmail: {
                            subject: 'Following up from MENA Careers',
                            body: '<p>Hi {first_name},</p>' +
                                '<p>I hope you are doing well.</p>' +
                                '<p>I wanted to reach out because MENA Careers is helping finance candidates keep track of relevant roles, recruiter contacts, and application support in one place.</p>' +
                                '<p>If you are currently looking, or open to hearing about opportunities that fit your background, reply here and I can point you in the right direction.</p>' +
                                '<p>Best wishes,<br>{sender_first_name}</p>'
                        },
                        basic: {
                            subject: 'A quick MENA Careers update for {first_name}',
                            body: '<p>Hi {first_name},</p>' +
                                '<p>We wanted to let you know about MENA Careers support for finance careers, including role alerts, recruiter intros, Career Assessment, and application support.</p>' +
                                '<p>You can use MENA Careers to keep track of relevant opportunities and get more structured support around your next move.</p>' +
                                '<p>Best,<br>{sender_name}</p>'
                        },
                        professional_editorial: {
                            subject: '{first_name}, a focused note from MENA Careers',
                            body: '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f6f7f5;padding:28px 14px;font-family:Georgia,Times,serif;color:#111827;">' +
                                '<tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" width="640" style="width:100%;max-width:640px;background:#fffdf8;border:1px solid #e5e0d7;">' +
                                '<tr><td style="padding:30px 32px;">' +
                                '<p style="margin:0 0 14px;font:700 12px Arial,Helvetica,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:#0d1d42;">MENA Careers</p>' +
                                '<h1 style="margin:0 0 18px;font-size:28px;line-height:1.08;font-weight:500;color:#111827;">A more targeted route into finance opportunities</h1>' +
                                '<p style="margin:0 0 16px;font-size:17px;line-height:1.65;">Hi {first_name},</p>' +
                                '<p style="margin:0 0 16px;font-size:17px;line-height:1.65;">We are working with candidates who want more than a generic jobs board: sharper role discovery, better recruiter visibility, and support with the application process.</p>' +
                                '<p style="margin:0 0 16px;font-size:17px;line-height:1.65;">MENA Careers helps surface relevant finance roles, recruiter contacts, and follow-up actions so your search becomes more deliberate.</p>' +
                                '<p style="margin:22px 0 0;font-size:16px;line-height:1.6;">Best,<br>{sender_name}</p>' +
                                '</td></tr></table></td></tr></table>'
                        },
                        professional_card: {
                            subject: 'MENA Careers career support for {first_name}',
                            body: '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#eef2f5;padding:30px 14px;font-family:Arial,Helvetica,sans-serif;color:#172033;">' +
                                '<tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" width="620" style="width:100%;max-width:620px;background:#ffffff;border:1px solid #d8e0e8;border-radius:16px;overflow:hidden;">' +
                                '<tr><td style="background:#0d1d42;padding:22px 28px;color:#ffffff;">' +
                                '<p style="margin:0;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#8effd1;">MENA Careers</p>' +
                                '<h1 style="margin:10px 0 0;font-size:26px;line-height:1.15;color:#ffffff;">Finance career support that is more targeted</h1>' +
                                '</td></tr>' +
                                '<tr><td style="padding:26px 28px;">' +
                                '<p style="margin:0 0 14px;font-size:16px;line-height:1.6;">Hi {first_name},</p>' +
                                '<p style="margin:0 0 14px;font-size:16px;line-height:1.6;">MENA Careers helps finance candidates move faster by combining role alerts, recruiter discovery, CV positioning, and application support in one place.</p>' +
                                '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="margin:18px 0;border-collapse:collapse;">' +
                                '<tr><td style="padding:12px;border:1px solid #e5e7eb;background:#f9fafb;font-size:14px;line-height:1.5;">Recruiter intros</td><td style="padding:12px;border:1px solid #e5e7eb;background:#f9fafb;font-size:14px;line-height:1.5;">Smart applications</td></tr>' +
                                '<tr><td style="padding:12px;border:1px solid #e5e7eb;background:#f9fafb;font-size:14px;line-height:1.5;">Career Assessment</td><td style="padding:12px;border:1px solid #e5e7eb;background:#f9fafb;font-size:14px;line-height:1.5;">Targeted alerts</td></tr>' +
                                '</table>' +
                                '<p style="margin:0 0 18px;font-size:16px;line-height:1.6;">If you want a more structured route into your next finance role, this is worth reviewing.</p>' +
                                '<p style="margin:0;font-size:15px;line-height:1.6;color:#475569;">Best,<br>{sender_name}<br>{sender_email}</p>' +
                                '</td></tr></table></td></tr></table>'
                        }
                    };

                    function setEditorBody(value) {
                        if (window.tinyMCE && window.tinyMCE.get('sffc_crm_custom_email_body_editor')) {
                            window.tinyMCE.get('sffc_crm_custom_email_body_editor').setContent(value);
                        }
                        if (bodyTextarea) {
                            bodyTextarea.value = value;
                        }
                    }

                    if (templateSelect && subjectInput) {
                        templateSelect.addEventListener('change', function() {
                            var template = templates[templateSelect.value];
                            if (!template) {
                                return;
                            }
                            subjectInput.value = template.subject;
                            setEditorBody(template.body);
                        });
                    }

                    var customEmailForm = templateSelect ? templateSelect.closest('form') : null;
                    if (customEmailForm) {
                        customEmailForm.addEventListener('submit', function() {
                            if (window.tinyMCE && typeof window.tinyMCE.triggerSave === 'function') {
                                window.tinyMCE.triggerSave();
                            }
                        });
                    }

                    if (!csvInput || !preview || !mapFields.length) {
                        return;
                    }

                    function escapeHtml(value) {
                        return String(value == null ? '' : value)
                            .replace(/&/g, '&amp;')
                            .replace(/</g, '&lt;')
                            .replace(/>/g, '&gt;')
                            .replace(/"/g, '&quot;')
                            .replace(/'/g, '&#039;');
                    }

                    function normalizeHeader(value) {
                        return String(value || '')
                            .trim()
                            .toLowerCase()
                            .replace(/[^a-z0-9]+/g, '_')
                            .replace(/^_+|_+$/g, '');
                    }

                    function parseCsv(text) {
                        var rows = [];
                        var row = [];
                        var cell = '';
                        var inQuotes = false;

                        for (var i = 0; i < text.length; i++) {
                            var char = text[i];
                            var next = text[i + 1];

                            if (char === '"') {
                                if (inQuotes && next === '"') {
                                    cell += '"';
                                    i++;
                                } else {
                                    inQuotes = !inQuotes;
                                }
                                continue;
                            }

                            if (char === ',' && !inQuotes) {
                                row.push(cell);
                                cell = '';
                                continue;
                            }

                            if ((char === '\n' || char === '\r') && !inQuotes) {
                                if (char === '\r' && next === '\n') {
                                    i++;
                                }
                                row.push(cell);
                                if (row.some(function(value) { return String(value).trim() !== ''; })) {
                                    rows.push(row);
                                }
                                row = [];
                                cell = '';
                                continue;
                            }

                            cell += char;
                        }

                        row.push(cell);
                        if (row.some(function(value) { return String(value).trim() !== ''; })) {
                            rows.push(row);
                        }

                        return rows;
                    }

                    function findBestHeader(headers, preferred, fallbacks) {
                        var candidates = [preferred].concat(fallbacks || []).map(normalizeHeader);
                        var normalizedHeaders = headers.map(normalizeHeader);
                        for (var i = 0; i < candidates.length; i++) {
                            var index = normalizedHeaders.indexOf(candidates[i]);
                            if (index !== -1) {
                                return headers[index];
                            }
                        }
                        return preferred;
                    }

                    function refreshCustomTags(headers) {
                        var mapped = {};
                        mapFields.forEach(function(select) {
                            mapped[normalizeHeader(select.value)] = true;
                        });

                        var tags = headers
                            .map(normalizeHeader)
                            .filter(function(tag) {
                                return tag && !mapped[tag];
                            });

                        var tagHtml = tags.length
                            ? tags.map(function(tag) { return '<code>{' + escapeHtml(tag) + '}</code>'; }).join(' ')
                            : '<em>No extra custom tags. All columns are mapped to core fields.</em>';

                        var tagTarget = preview.querySelector('[data-sffc-csv-custom-tags]');
                        if (tagTarget) {
                            tagTarget.innerHTML = tagHtml;
                        }
                    }

                    function getEmailMapSelect() {
                        return mapFields.find(function(select) {
                            return select.name === 'sffc_crm_custom_email_csv_email_field';
                        });
                    }

                    function extractEmailsFromMappedCsv() {
                        var emailSelect = getEmailMapSelect();
                        var selectedHeader = emailSelect ? emailSelect.value : '';
                        var emailIndex = currentCsvHeaders.indexOf(selectedHeader);
                        if (emailIndex < 0) {
                            return [];
                        }

                        var seen = {};
                        return currentCsvRows.slice(1).map(function(row) {
                            return String(row[emailIndex] || '').trim();
                        }).filter(function(email) {
                            var valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
                            var key = email.toLowerCase();
                            if (!valid || seen[key]) {
                                return false;
                            }
                            seen[key] = true;
                            return true;
                        });
                    }

                    function syncRecipientsFromCsv() {
                        if (!recipientsTextarea || !currentCsvRows.length || !currentCsvHeaders.length) {
                            return;
                        }

                        var csvEmails = extractEmailsFromMappedCsv();
                        if (!csvEmails.length) {
                            return;
                        }

                        var existing = String(recipientsTextarea.value || '')
                            .split(/[\s,;]+/)
                            .map(function(value) { return value.trim(); })
                            .filter(Boolean);
                        var seen = {};
                        var merged = existing.concat(csvEmails).filter(function(email) {
                            var key = email.toLowerCase();
                            if (seen[key]) {
                                return false;
                            }
                            seen[key] = true;
                            return true;
                        });

                        recipientsTextarea.value = merged.join("\n");
                    }

                    function populateMapping(headers) {
                        var fallbackMap = {
                            sffc_crm_custom_email_csv_email_field: ['email_address', 'user_email', 'recipient_email'],
                            sffc_crm_custom_email_csv_first_name_field: ['first', 'firstname'],
                            sffc_crm_custom_email_csv_last_name_field: ['last', 'lastname', 'surname'],
                            sffc_crm_custom_email_csv_display_name_field: ['name', 'full_name'],
                            sffc_crm_custom_email_csv_username_field: ['user_login']
                        };

                        mapFields.forEach(function(select) {
                            var preferred = select.getAttribute('data-sffc-default-field') || select.value || '';
                            var best = findBestHeader(headers, preferred, fallbackMap[select.name] || []);
                            select.innerHTML = '<option value="">Do not map</option>' + headers.map(function(header) {
                                return '<option value="' + escapeHtml(header) + '">' + escapeHtml(header) + '</option>';
                            }).join('');
                            select.value = best;
                            if (!select.value && select.name === 'sffc_crm_custom_email_csv_email_field' && headers.length) {
                                select.value = headers[0];
                            }
                        });

                        mapFields.forEach(function(select) {
                            select.addEventListener('change', function() {
                                refreshCustomTags(headers);
                                if (select.name === 'sffc_crm_custom_email_csv_email_field') {
                                    syncRecipientsFromCsv();
                                }
                            }, { once: false });
                        });
                    }

                    function renderPreview(rows) {
                        var headers = rows[0] || [];
                        var sampleRows = rows.slice(1, 6);
                        currentCsvRows = rows;
                        currentCsvHeaders = headers;
                        if (!headers.length) {
                            preview.style.display = 'block';
                            preview.innerHTML = '<strong style="color:#d63638;">No CSV headers found.</strong>';
                            return;
                        }

                        populateMapping(headers);

                        var headerHtml = headers.map(function(header) {
                            return '<th style="padding:6px 8px;border-bottom:1px solid #dcdcde;text-align:left;">' + escapeHtml(header) + '</th>';
                        }).join('');
                        var rowsHtml = sampleRows.map(function(row) {
                            return '<tr>' + headers.map(function(header, index) {
                                return '<td style="padding:6px 8px;border-bottom:1px solid #eee;">' + escapeHtml(row[index] || '') + '</td>';
                            }).join('') + '</tr>';
                        }).join('');

                        preview.style.display = 'block';
                        preview.innerHTML =
                            '<div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:10px;">' +
                                '<div><strong>CSV preview</strong><p class="description" style="margin:4px 0 0;">Detected ' + rows.length + ' row(s), including the header. Showing up to 5 sample recipients.</p></div>' +
                                '<div><strong>Custom tags:</strong><div data-sffc-csv-custom-tags style="margin-top:4px;"></div></div>' +
                            '</div>' +
                            '<div style="max-width:100%;overflow:auto;background:#fff;border:1px solid #dcdcde;">' +
                                '<table class="widefat striped" style="min-width:720px;margin:0;"><thead><tr>' + headerHtml + '</tr></thead><tbody>' + rowsHtml + '</tbody></table>' +
                            '</div>';
                        refreshCustomTags(headers);
                        syncRecipientsFromCsv();
                    }

                    csvInput.addEventListener('change', function() {
                        var file = csvInput.files && csvInput.files[0];
                        if (!file) {
                            preview.style.display = 'none';
                            preview.innerHTML = '';
                            return;
                        }

                        var reader = new FileReader();
                        reader.onload = function(event) {
                            var rows = parseCsv(String(event.target.result || ''));
                            renderPreview(rows);
                        };
                        reader.onerror = function() {
                            preview.style.display = 'block';
                            preview.innerHTML = '<strong style="color:#d63638;">Could not read this CSV in the browser.</strong>';
                        };
                        reader.readAsText(file);
                    });
                })();
            </script>

