                    $btn.prop('disabled', true).text('<?php esc_html_e('Processing...', 'senna-finance'); ?>');
                    $progress.show();
                    $progressBar.css('width', '0%');
                    $progressText.text('0%');
                    $status.text('<?php esc_html_e('Fetching posts...', 'senna-finance'); ?>');

                    $.ajax({
                        url: ajaxurl,
                        type: 'POST',
                        data: {
                            action: 'sffc_crm_bulk_extract_keywords',
                            nonce: '<?php echo wp_create_nonce('sffc_crm_bulk_keywords'); ?>'
                        },
                        success: function(response) {
                            if (response.success) {
                                $progressBar.css('width', '100%');
                                $progressText.text('100%');
                                $status.html('<strong style="color: #00a32a;">' + response.data.message + '</strong>');
