                            $btn.prop('disabled', false).text('<?php esc_html_e('Extract Keywords for All Posts', 'senna-finance'); ?>');
                        },
                        xhr: function() {
                            var xhr = new window.XMLHttpRequest();
                            // Monitor progress if server sends progress updates
