    private function get_email_user_groups()
    {
        $stored = get_option('sffc_crm_email_user_groups', []);
        $groups = [];

        foreach ((array) $stored as $group) {
            $key = sanitize_key($group['key'] ?? '');
            $name = sanitize_text_field($group['name'] ?? '');
            if ($key === '' || $name === '') {
                continue;
            }

            $groups[$key] = [
                'key' => $key,
                'name' => $name,
                'description' => sanitize_textarea_field($group['description'] ?? ''),
                'user_ids' => array_values(array_unique(array_filter(array_map('intval', (array) ($group['user_ids'] ?? []))))),
            ];
        }

        return $groups;
    }

    private function build_custom_email_recipient_from_user($user)
    {
        if (!$user instanceof WP_User) {
            return null;
        }

        $email = sanitize_email($user->user_email);
        if (!$email) {
            return null;
        }

        $first_name = (string) get_user_meta($user->ID, 'first_name', true);
        $last_name = (string) get_user_meta($user->ID, 'last_name', true);
        $display_name = (string) $user->display_name;

        if ($first_name === '' && $display_name !== '') {
            $name_parts = preg_split('/\s+/', trim($display_name));
            $first_name = (string) ($name_parts[0] ?? '');
            if ($last_name === '' && count($name_parts) > 1) {
                $last_name = (string) end($name_parts);
            }
        }

        return [
            'email' => $email,
            'user_id' => (int) $user->ID,
            'first_name' => $first_name,
            'last_name' => $last_name,
            'display_name' => $display_name !== '' ? $display_name : $email,
            'username' => (string) $user->user_login,
        ];
    }

    private function get_custom_email_group_recipients($group_key)
    {
        $groups = $this->get_email_user_groups();
        $group_key = sanitize_key($group_key);
        if ($group_key === '' || empty($groups[$group_key])) {
            return [];
        }

        $user_ids = array_values(array_unique(array_filter(array_map('intval', (array) ($groups[$group_key]['user_ids'] ?? [])))));
        if (empty($user_ids)) {
            return [];
        }

        $users = get_users([
            'include' => $user_ids,
            'orderby' => 'display_name',
            'order' => 'ASC',
        ]);

        $recipients = [];
        foreach ((array) $users as $user) {
            $recipient = $this->build_custom_email_recipient_from_user($user);
            if ($recipient) {
                $recipients[] = $recipient;
            }
        }

        return $recipients;
    }

    private function get_custom_email_sender_by_key($sender_key)
    {
        $sender_key = sanitize_key($sender_key);
        if ($sender_key === '' || !function_exists('sffc_crm_get_email_senders') || !function_exists('sffc_crm_get_email_sender_contexts')) {
            return [];
        }

        $senders = sffc_crm_get_email_senders();
        $contexts = sffc_crm_get_email_sender_contexts();
        $custom_sender_keys = $contexts['custom_email'] ?? [];
        if (!is_array($custom_sender_keys)) {
            $custom_sender_keys = [$custom_sender_keys];
        }

        if (!in_array($sender_key, array_map('sanitize_key', $custom_sender_keys), true) || empty($senders[$sender_key])) {
            return [];
        }

        return (array) $senders[$sender_key];
    }

    private function normalize_custom_email_csv_tag_key($value)
    {
        $value = strtolower(trim((string) $value));
        $value = preg_replace('/[^a-z0-9]+/', '_', $value);
        $value = trim((string) $value, '_');

        return $value !== '' ? $value : '';
    }

    private function resolve_custom_email_csv_column_index(array $normalized_headers, $mapped_header, array $fallbacks = [])
    {
        $candidates = array_merge([(string) $mapped_header], $fallbacks);
        foreach ($candidates as $candidate) {
            $key = $this->normalize_custom_email_csv_tag_key($candidate);
            if ($key !== '' && array_key_exists($key, $normalized_headers)) {
                return (int) $normalized_headers[$key];
            }
        }

        return null;
    }

    private function parse_custom_email_csv_recipients($file, array $field_map)
    {
        if (empty($file) || !is_array($file) || empty($file['tmp_name'])) {
            return [];
        }

        $error_code = (int) ($file['error'] ?? UPLOAD_ERR_OK);
        if ($error_code === UPLOAD_ERR_NO_FILE) {
            return [];
        }
        if ($error_code !== UPLOAD_ERR_OK) {
            return new WP_Error('sffc_custom_email_csv_upload_failed', __('The CSV upload failed. Please choose a valid CSV and try again.', 'senna-finance'));
        }

        $file_name = sanitize_file_name((string) ($file['name'] ?? ''));
        $extension = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));
        if ($extension !== 'csv') {
            return new WP_Error('sffc_custom_email_csv_invalid_type', __('Upload a .csv file for custom email recipients.', 'senna-finance'));
        }

        $handle = fopen((string) $file['tmp_name'], 'r');
        if (!$handle) {
            return new WP_Error('sffc_custom_email_csv_unreadable', __('The uploaded CSV could not be read.', 'senna-finance'));
        }

        $headers = fgetcsv($handle);
        if (empty($headers) || !is_array($headers)) {
            fclose($handle);
            return new WP_Error('sffc_custom_email_csv_missing_header', __('The CSV must include a header row.', 'senna-finance'));
        }

        $normalized_headers = [];
        $original_headers = [];
        foreach ($headers as $index => $header) {
            $header = trim((string) $header);
            $key = $this->normalize_custom_email_csv_tag_key($header);
            if ($key === '') {
                continue;
            }
            if (!isset($normalized_headers[$key])) {
                $normalized_headers[$key] = (int) $index;
                $original_headers[$key] = $header;
            }
        }

        $email_index = $this->resolve_custom_email_csv_column_index($normalized_headers, $field_map['email'] ?? 'email', ['email_address', 'user_email', 'recipient_email']);
        if ($email_index === null) {
            fclose($handle);
            return new WP_Error('sffc_custom_email_csv_missing_email', __('Map the CSV email column before sending.', 'senna-finance'));
        }

        $field_indexes = [
            'first_name' => $this->resolve_custom_email_csv_column_index($normalized_headers, $field_map['first_name'] ?? 'first_name', ['first', 'firstname']),
            'last_name' => $this->resolve_custom_email_csv_column_index($normalized_headers, $field_map['last_name'] ?? 'last_name', ['last', 'lastname', 'surname']),
            'display_name' => $this->resolve_custom_email_csv_column_index($normalized_headers, $field_map['display_name'] ?? 'display_name', ['name', 'full_name']),
            'username' => $this->resolve_custom_email_csv_column_index($normalized_headers, $field_map['username'] ?? 'username', ['user_login']),
        ];

        $mapped_indexes = array_filter(array_merge([$email_index], $field_indexes), static function ($value) {
            return $value !== null;
        });
        $mapped_indexes = array_map('intval', $mapped_indexes);

        $recipients = [];
        $row_count = 0;
        while (($row = fgetcsv($handle)) !== false) {
            $row_count++;
            if ($row_count > 1000) {
                break;
            }

            $email = sanitize_email($row[$email_index] ?? '');
            if (!$email) {
                continue;
            }

            $recipient = [
                'email' => $email,
                'user_id' => 0,
                'first_name' => $field_indexes['first_name'] !== null ? sanitize_text_field((string) ($row[$field_indexes['first_name']] ?? '')) : '',
                'last_name' => $field_indexes['last_name'] !== null ? sanitize_text_field((string) ($row[$field_indexes['last_name']] ?? '')) : '',
                'display_name' => $field_indexes['display_name'] !== null ? sanitize_text_field((string) ($row[$field_indexes['display_name']] ?? '')) : '',
                'username' => $field_indexes['username'] !== null ? sanitize_text_field((string) ($row[$field_indexes['username']] ?? '')) : '',
                'custom_tags' => [],
            ];

            if ($recipient['display_name'] === '') {
                $name_parts = array_filter([$recipient['first_name'], $recipient['last_name']]);
                $recipient['display_name'] = !empty($name_parts) ? implode(' ', $name_parts) : $email;
            }

            foreach ($normalized_headers as $tag_key => $index) {
                if (in_array((int) $index, $mapped_indexes, true)) {
                    continue;
                }
                $recipient['custom_tags'][$tag_key] = sanitize_text_field((string) ($row[$index] ?? ''));
            }

            $recipients[] = $recipient;
        }
        fclose($handle);

        return $this->dedupe_custom_email_recipients($recipients);
    }

    private function dedupe_custom_email_recipients(array $recipients)
    {
        $deduped = [];
        $seen = [];

        foreach ($recipients as $recipient) {
            $email = sanitize_email($recipient['email'] ?? '');
            if (!$email) {
                continue;
            }

            $email_key = strtolower($email);
            if (isset($seen[$email_key])) {
                continue;
            }

            $seen[$email_key] = true;
            $recipient['email'] = $email;
            $deduped[] = $recipient;
        }

        return $deduped;
    }

    private function parse_custom_email_recipients($raw_value)
    {
        $tokens = preg_split('/[\s,;]+/', (string) wp_unslash($raw_value));
        $tokens = array_values(array_filter(array_map('trim', (array) $tokens)));
        $recipients = [];
        $seen = [];

        foreach ($tokens as $token) {
            $email = sanitize_email($token);
            if (!$email) {
                continue;
            }

            $email_key = strtolower($email);
            if (isset($seen[$email_key])) {
                continue;
            }
            $seen[$email_key] = true;

            $user = get_user_by('email', $email);
            if ($user instanceof WP_User) {
                $recipient = $this->build_custom_email_recipient_from_user($user);
                if ($recipient) {
                    $recipients[] = $recipient;
                }
            } else {
                $recipients[] = [
                    'email' => $email,
                    'user_id' => 0,
                    'first_name' => '',
                    'last_name' => '',
                    'display_name' => $email,
                    'username' => '',
                ];
            }

            if (count($recipients) >= 1000) {
                break;
            }
        }

        return $this->dedupe_custom_email_recipients($recipients);
    }

    private function prepare_custom_email_body_template($raw_body)
    {
        $body = (string) $raw_body;
        $body = html_entity_decode($body, ENT_QUOTES | ENT_HTML5, get_bloginfo('charset') ?: 'UTF-8');
        $body = preg_replace('/<div\b([^>]*)>\s*/i', '<div$1>', $body);
        $body = preg_replace('/\s*<\/div>\s*$/i', '</div>', $body);
        $body = wp_kses_post($body);

        $has_layout_html = (bool) preg_match('/<(p|br|div|table|tr|td|ul|ol|li|h[1-6]|blockquote)\b/i', $body);
        if (!$has_layout_html) {
            $body = wpautop($body);
        } elseif (strpos($body, "\n") !== false && !preg_match('/<(table|p|br|div|tr|td)\b/i', $body)) {
            $body = nl2br($body);
        }

        return trim($body);
    }

    private function replace_custom_email_tags($content, array $recipient, $is_html = true, array $sender = [])
    {
        $sender_name = trim((string) ($sender['from_name'] ?? ''));
        $sender_email = trim((string) ($sender['from_email'] ?? ''));
        $sender_first_name = '';
        $sender_last_name = '';
        if ($sender_name !== '') {
            $sender_name_parts = preg_split('/\s+/', $sender_name);
            $sender_name_parts = array_values(array_filter(array_map('trim', (array) $sender_name_parts)));
            if (!empty($sender_name_parts)) {
                $sender_first_name = $sender_name_parts[0];
                if (count($sender_name_parts) > 1) {
                    $sender_last_name = implode(' ', array_slice($sender_name_parts, 1));
                }
            }
        }

        $recipient_email = (string) ($recipient['email'] ?? '');
        $display_name = trim((string) ($recipient['display_name'] ?? ''));
        $first_name = trim((string) ($recipient['first_name'] ?? ''));
        $last_name = trim((string) ($recipient['last_name'] ?? ''));
        if ($first_name === '' && $display_name !== '' && $display_name !== $recipient_email) {
            $name_parts = preg_split('/\s+/', $display_name);
            $first_name = (string) ($name_parts[0] ?? '');
            if ($last_name === '' && count($name_parts) > 1) {
                $last_name = (string) end($name_parts);
            }
        }
        if ($first_name === '' && $recipient_email !== '') {
            $first_name = ucfirst((string) strtok($recipient_email, '@'));
        }

        $values = [
            'first_name' => $first_name,
            'last_name' => $last_name,
            'display_name' => $display_name !== '' ? $display_name : $recipient_email,
            'email' => $recipient_email,
            'username' => $recipient['username'] ?? '',
            'sender_name' => $sender_name,
            'sender_first_name' => $sender_first_name !== '' ? $sender_first_name : $sender_name,
            'sender_last_name' => $sender_last_name,
            'sender_email' => $sender_email,
        ];

        foreach ((array) ($recipient['custom_tags'] ?? []) as $tag_key => $tag_value) {
            $tag_key = $this->normalize_custom_email_csv_tag_key($tag_key);
            if ($tag_key === '') {
                continue;
            }
            $values[$tag_key] = $tag_value;
        }

        foreach ($values as $tag_key => $value) {
            $replacement = $is_html ? esc_html((string) $value) : sanitize_text_field((string) $value);
            $content = preg_replace('/\{\s*' . preg_quote((string) $tag_key, '/') . '\s*\}/i', $replacement, (string) $content);
        }

        return preg_replace('/\{\s*[a-z0-9_]+\s*\}/i', '', (string) $content);
    }

    /**
     * Save CRM settings
     */
    private function save_crm_settings()
    {
        $settings = [
            'logo_url' => esc_url_raw($_POST['crm_logo_url'] ?? ''),
            'title' => sanitize_text_field($_POST['crm_title'] ?? 'MENA Careers Recruiter Match CRM'),
            'show_user_dropdown' => !empty($_POST['crm_show_user_dropdown']),
            'menu_items' => [],
        ];

        // Process menu items
        if (!empty($_POST['crm_menu_items']) && is_array($_POST['crm_menu_items'])) {
            foreach ($_POST['crm_menu_items'] as $item) {
                $label = sanitize_text_field($item['label'] ?? '');
                $url = esc_url_raw($item['url'] ?? '');
                $icon = sanitize_text_field($item['icon'] ?? 'user');

                if (!empty($label) && !empty($url)) {
                    $settings['menu_items'][] = [
                        'label' => $label,
                        'url' => $url,
                        'icon' => $icon,
                    ];
                }
            }
        }

        update_option('sffc_crm_header_settings', $settings);

        $console_search_style_keys = [
            'sffc_crm_console_search_mode_bg',
            'sffc_crm_console_search_mode_text',
            'sffc_crm_console_search_mode_border',
            'sffc_crm_console_search_field_bg',
            'sffc_crm_console_search_field_border',
            'sffc_crm_console_search_field_radius',
            'sffc_crm_console_search_label_color',
            'sffc_crm_console_search_input_color',
            'sffc_crm_console_search_dropdown_bg',
            'sffc_crm_console_search_dropdown_text',
            'sffc_crm_console_search_dropdown_hover_bg',
            'sffc_crm_console_search_dropdown_border',
            'sffc_crm_console_search_dropdown_radius',
            'sffc_crm_console_search_dropdown_shadow',
            'sffc_crm_console_search_button_bg',
            'sffc_crm_console_search_button_hover_bg',
            'sffc_crm_console_search_button_text',
            'sffc_crm_console_search_secondary_bg',
            'sffc_crm_console_search_secondary_text',
            'sffc_crm_console_landing_bg',
        ];

        foreach ($console_search_style_keys as $style_key) {
            update_option($style_key, sanitize_text_field(wp_unslash($_POST[$style_key] ?? '')));
        }

        // Save email integration settings
        update_option('sffc_crm_gmail_client_id', sanitize_text_field($_POST['sffc_crm_gmail_client_id'] ?? ''));
        update_option('sffc_crm_gmail_client_secret', sanitize_text_field($_POST['sffc_crm_gmail_client_secret'] ?? ''));
        update_option('sffc_crm_outlook_client_id', sanitize_text_field($_POST['sffc_crm_outlook_client_id'] ?? ''));
        update_option('sffc_crm_outlook_client_secret', sanitize_text_field($_POST['sffc_crm_outlook_client_secret'] ?? ''));
        update_option('sffc_crm_outlook_tenant', sanitize_text_field($_POST['sffc_crm_outlook_tenant'] ?? 'common'));
        $email_mode = isset($_POST['sffc_crm_email_mode']) && $_POST['sffc_crm_email_mode'] === 'mailto' ? 'mailto' : 'oauth';
        update_option('sffc_crm_email_mode', $email_mode);
        $alert_transport = sanitize_key($_POST['sffc_crm_internship_alert_transport'] ?? 'sendgrid_api');
        if (!in_array($alert_transport, ['sendgrid_api', 'wp_mail'], true)) {
            $alert_transport = 'sendgrid_api';
        }
        update_option('sffc_crm_internship_alert_transport', $alert_transport);
        update_option('sffc_crm_sendgrid_alert_api_key', sanitize_text_field($_POST['sffc_crm_sendgrid_alert_api_key'] ?? ''));
        update_option('sffc_crm_sendgrid_alert_from_email', sanitize_email($_POST['sffc_crm_sendgrid_alert_from_email'] ?? 'support.team@joinsenna.com'));
        update_option('sffc_crm_sendgrid_alert_from_name', sanitize_text_field($_POST['sffc_crm_sendgrid_alert_from_name'] ?? 'MENA Careers'));
        if (function_exists('sffc_crm_sanitize_email_senders') && function_exists('sffc_crm_sanitize_email_sender_contexts')) {
            $email_senders = sffc_crm_sanitize_email_senders($_POST['sffc_crm_email_senders'] ?? []);
            $email_sender_contexts = sffc_crm_sanitize_email_sender_contexts($_POST['sffc_crm_email_sender_contexts'] ?? [], $email_senders);
            update_option('sffc_crm_email_senders', $email_senders);
            update_option('sffc_crm_email_sender_contexts', $email_sender_contexts);
        }
        update_option('sffc_crm_internship_alert_batch_size', max(1, min(1000, intval($_POST['sffc_crm_internship_alert_batch_size'] ?? 25))));
        update_option('sffc_crm_exit_discount_coupon_code', strtoupper(sanitize_text_field($_POST['sffc_crm_exit_discount_coupon_code'] ?? '')));
        update_option('sffc_crm_exit_discount_rate', max(1, min(100, intval($_POST['sffc_crm_exit_discount_rate'] ?? 20))));

        $spacing_minutes = intval($_POST['sffc_crm_internship_alert_spacing_minutes'] ?? 5);
        if (!in_array($spacing_minutes, [1, 5, 10, 15], true)) {
            $spacing_minutes = 5;
        }
        update_option('sffc_crm_internship_alert_spacing_minutes', $spacing_minutes);
        update_option('sffc_crm_internship_alert_initial_delay_minutes', max(0, min(1440, intval($_POST['sffc_crm_internship_alert_initial_delay_minutes'] ?? 0))));
        update_option('sffc_crm_internship_alert_max_attempts', max(1, min(10, intval($_POST['sffc_crm_internship_alert_max_attempts'] ?? 5))));
        update_option('sffc_crm_premium_match_instant_threshold', max(50, min(100, intval($_POST['sffc_crm_premium_match_instant_threshold'] ?? 85))));
        update_option('sffc_crm_premium_match_digest_threshold', max(30, min(100, intval($_POST['sffc_crm_premium_match_digest_threshold'] ?? 65))));
        update_option('sffc_crm_premium_match_scan_limit', max(10, min(500, intval($_POST['sffc_crm_premium_match_scan_limit'] ?? 100))));
        update_option('sffc_crm_alert_email_sending_disabled', !empty($_POST['sffc_crm_alert_email_sending_disabled']) ? '1' : '0');
        update_option('sffc_crm_top_match_email_disabled', !empty($_POST['sffc_crm_top_match_email_disabled']) ? '1' : '0');
        update_option('sffc_crm_internship_alert_queue_paused', !empty($_POST['sffc_crm_internship_alert_queue_paused']) ? '1' : '0');
        update_option('sffc_crm_excluded_users', $this->sanitize_excluded_users_input($_POST['sffc_crm_excluded_users'] ?? ''));

        if (class_exists('SFFC_CRM_Internship_Alert_Queue')) {
            $queue = SFFC_CRM_Internship_Alert_Queue::get_instance();
            $queue->schedule_cron();
            if ($alert_transport === 'sendgrid_api' && empty($_POST['sffc_crm_internship_alert_queue_paused']) && empty($_POST['sffc_crm_alert_email_sending_disabled'])) {
                $queue->schedule_pending_batches();
            }
        }

        // Save expert outreach limits
        if (isset($_POST['expert_outreach_limits']) && is_array($_POST['expert_outreach_limits'])) {
            $expert_limits = [];
            foreach ($_POST['expert_outreach_limits'] as $tier => $limit) {
                $tier = sanitize_key($tier);
                $limit = intval($limit);
                // Allow -1 (unlimited), 0 (no access), or positive numbers
                if ($limit >= -1) {
                    $expert_limits[$tier] = $limit;
                }
            }
            update_option('sffc_crm_expert_outreach_limits', $expert_limits);
        }
    }

    private function sanitize_excluded_users_input($raw_value)
    {
        $tokens = preg_split('/[\r\n,]+/', (string) wp_unslash($raw_value));
        $tokens = array_values(array_filter(array_map('trim', (array) $tokens)));
        if (empty($tokens)) {
            return '';
        }

        $clean = [];
        foreach ($tokens as $token) {
            if ($token === '') {
                continue;
            }

            if (ctype_digit($token)) {
                $clean[] = (string) (int) $token;
                continue;
            }

            $email = sanitize_email($token);
            if ($email !== '') {
                $clean[] = $email;
            }
        }

        $clean = array_values(array_unique(array_filter($clean)));
        return implode("\n", $clean);
    }

    private function ensure_linkedin_intro_queue_table()
    {
        global $wpdb;

        $table_name = $wpdb->prefix . 'sffc_crm_intro_requests';
        if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name) {
            return;
        }

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';
        $charset_collate = $wpdb->get_charset_collate();

        $sql = "CREATE TABLE {$table_name} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            post_id bigint(20) NOT NULL,
            recruiter_id bigint(20) NOT NULL,
            recruiter_name varchar(255) DEFAULT NULL,
            recruiter_email varchar(255) DEFAULT NULL,
            recruiter_linkedin varchar(500) DEFAULT NULL,
            company_name varchar(255) DEFAULT NULL,
            role_title varchar(255) DEFAULT NULL,
            status varchar(50) DEFAULT 'pending_review',
            admin_message text DEFAULT NULL,
            recruiter_reply text DEFAULT NULL,
            tracking_status varchar(50) DEFAULT 'applied',
            materials_requested text DEFAULT NULL,
            materials_status varchar(50) DEFAULT 'not_requested',
            cover_letter_url text DEFAULT NULL,
            resume_url text DEFAULT NULL,
            email_template text DEFAULT NULL,
            criteria_id bigint(20) DEFAULT NULL,
            cv_file_id bigint(20) DEFAULT NULL,
            cover_letter_file_id bigint(20) DEFAULT NULL,
            application_url text DEFAULT NULL,
            source_action varchar(80) DEFAULT NULL,
            queue_status varchar(50) DEFAULT NULL,
            queue_position int(11) DEFAULT 0,
            submitted_at datetime DEFAULT NULL,
            user_queue_confirmation_sent_at datetime DEFAULT NULL,
            user_queue_digest_scheduled_at datetime DEFAULT NULL,
            user_queue_digest_sent_at datetime DEFAULT NULL,
            confirmation_sent_at datetime DEFAULT NULL,
            resume_sent_at datetime DEFAULT NULL,
            cover_letter_sent_at datetime DEFAULT NULL,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime NULL,
            PRIMARY KEY (id),
            UNIQUE KEY unique_user_post (user_id, post_id),
            KEY idx_user (user_id),
            KEY idx_post (post_id),
            KEY idx_criteria (criteria_id),
            KEY idx_status (status),
            KEY idx_tracking_status (tracking_status),
            KEY idx_queue_status (queue_status)
        ) {$charset_collate};";

        dbDelta($sql);
    }

    private function add_application_queue_columns()
    {
        global $wpdb;

        $table = $wpdb->prefix . 'sffc_crm_intro_requests';
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
        if (!$table_exists) {
            return [
                'added' => [],
                'errors' => [__('Application queue table does not exist.', 'senna-finance')],
            ];
        }

        $columns_to_add = [
            'criteria_id' => "ALTER TABLE `{$table}` ADD COLUMN `criteria_id` bigint(20) DEFAULT NULL AFTER `email_template`",
            'cv_file_id' => "ALTER TABLE `{$table}` ADD COLUMN `cv_file_id` bigint(20) DEFAULT NULL AFTER `criteria_id`",
            'cover_letter_file_id' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_file_id` bigint(20) DEFAULT NULL AFTER `cv_file_id`",
            'application_url' => "ALTER TABLE `{$table}` ADD COLUMN `application_url` text DEFAULT NULL AFTER `cover_letter_file_id`",
            'source_action' => "ALTER TABLE `{$table}` ADD COLUMN `source_action` varchar(80) DEFAULT NULL AFTER `application_url`",
            'queue_status' => "ALTER TABLE `{$table}` ADD COLUMN `queue_status` varchar(50) DEFAULT NULL AFTER `source_action`",
            'queue_position' => "ALTER TABLE `{$table}` ADD COLUMN `queue_position` int(11) DEFAULT 0 AFTER `queue_status`",
            'submitted_at' => "ALTER TABLE `{$table}` ADD COLUMN `submitted_at` datetime DEFAULT NULL AFTER `queue_position`",
            'user_queue_confirmation_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `user_queue_confirmation_sent_at` datetime DEFAULT NULL AFTER `submitted_at`",
            'user_queue_digest_scheduled_at' => "ALTER TABLE `{$table}` ADD COLUMN `user_queue_digest_scheduled_at` datetime DEFAULT NULL AFTER `user_queue_confirmation_sent_at`",
            'user_queue_digest_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `user_queue_digest_sent_at` datetime DEFAULT NULL AFTER `user_queue_digest_scheduled_at`",
        ];

        $added = [];
        $errors = [];
        $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");

        foreach ($columns_to_add as $column_name => $sql) {
            if (in_array($column_name, $existing_columns, true)) {
                continue;
            }

            $result = $wpdb->query($sql);
            if ($result === false) {
                $errors[] = $column_name . ': ' . $wpdb->last_error;
                continue;
            }

            $added[] = $column_name;
            $existing_columns[] = $column_name;
        }

        if (in_array('queue_status', $existing_columns, true) && in_array('source_action', $existing_columns, true)) {
            $wpdb->query("ALTER TABLE `{$table}` ALTER COLUMN `queue_status` SET DEFAULT NULL");
            $wpdb->query("UPDATE `{$table}` SET `queue_status` = NULL WHERE `queue_status` = 'queued' AND (`source_action` IS NULL OR `source_action` = '')");
        }

        $this->maybe_add_application_queue_index($table, 'idx_criteria', 'criteria_id', $added, $errors);
        $this->maybe_add_application_queue_index($table, 'idx_queue_status', 'queue_status', $added, $errors);

        return [
            'added' => $added,
            'errors' => $errors,
        ];
    }

