        $errors = [];
        $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");

        foreach ($columns_to_add as $column_name => $sql) {
            if (in_array($column_name, $existing_columns, true)) {
                continue;
            }

            $result = $wpdb->query($sql);
            if ($result === false) {
                $errors[] = $column_name . ': ' . $wpdb->last_error;
                continue;
            }

            $added[] = $column_name;
            $existing_columns[] = $column_name;
        }

        if (in_array('request_type', $existing_columns, true)) {
            $wpdb->query("UPDATE `{$table}` SET `request_type` = 'intro' WHERE `request_type` IS NULL OR `request_type` = ''");
        }

        return [
            'added' => $added,
            'errors' => $errors,
        ];
    }

    private function parse_campaign_reached_recruiters($value)
    {
        if (!is_string($value) || trim($value) === '') {
            return [];
        }

        $decoded = json_decode($value, true);
        return is_array($decoded) ? $decoded : [];
    }

    private function sanitize_campaign_reached_recruiters($raw_contacts)
    {
        if (!is_array($raw_contacts)) {
            return [];
        }

        $contacts = [];
        foreach ($raw_contacts as $contact) {
            $contact = is_array($contact) ? $contact : [];
            $name = sanitize_text_field(wp_unslash($contact['name'] ?? ''));
            $title = sanitize_text_field(wp_unslash($contact['title'] ?? ''));
            $email = sanitize_email(wp_unslash($contact['email'] ?? ''));
            $linkedin = esc_url_raw(wp_unslash($contact['linkedin'] ?? ''));
            $company = sanitize_text_field(wp_unslash($contact['company'] ?? ''));
            $company_info = sanitize_textarea_field(wp_unslash($contact['company_info'] ?? ''));
            $avatar_url = esc_url_raw(wp_unslash($contact['avatar_url'] ?? ''));
            $message_subject = sanitize_text_field(wp_unslash($contact['message_subject'] ?? ''));
            $message_body = sanitize_textarea_field(wp_unslash($contact['message_body'] ?? ''));
            $attachment_urls = sanitize_textarea_field(wp_unslash($contact['attachment_urls'] ?? ''));
            $sent_at = sanitize_text_field(wp_unslash($contact['sent_at'] ?? ''));

            if ($name === '' && $email === '' && $linkedin === '' && $company === '' && $message_subject === '' && $message_body === '') {
                continue;
            }

            $contacts[] = [
                'name' => $name,
                'title' => $title,
                'email' => $email,
                'linkedin' => $linkedin,
                'company' => $company,
                'company_info' => $company_info,
                'avatar_url' => $avatar_url,
                'message_subject' => $message_subject,
                'message_body' => $message_body,
                'attachment_urls' => $attachment_urls,
                'sent_at' => $sent_at,
            ];
        }

        return $contacts;
    }

    private function maybe_add_application_queue_index($table, $index_name, $column_name, &$added, &$errors = [])
    {
        global $wpdb;

        $safe_table = sanitize_key((string) $table);
        $safe_index_name = preg_replace('/[^A-Za-z0-9_]/', '', (string) $index_name);
        $safe_column_name = preg_replace('/[^A-Za-z0-9_]/', '', (string) $column_name);

        if ($safe_table === '' || $safe_index_name === '' || $safe_column_name === '') {
            $errors[] = sprintf(
                __('Skipped invalid application queue index request (%1$s on %2$s).', 'senna-finance'),
                (string) $index_name,
                (string) $column_name
            );
            return;
        }

        $column_exists = $wpdb->get_var($wpdb->prepare(
            "SELECT COLUMN_NAME
             FROM INFORMATION_SCHEMA.COLUMNS
             WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s
             LIMIT 1",
            DB_NAME,
            $safe_table,
            $safe_column_name
        ));

        if (!$column_exists) {
            $errors[] = sprintf(
                __('Skipped index %1$s because column %2$s does not exist yet.', 'senna-finance'),
                $safe_index_name,
                $safe_column_name
            );
            return;
        }

        $index_exists = $wpdb->get_var($wpdb->prepare(
            "SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND INDEX_NAME = %s LIMIT 1",
            DB_NAME,
            $safe_table,
            $safe_index_name
        ));

        if ($index_exists) {
            return;
        }

        $result = $wpdb->query("ALTER TABLE `{$safe_table}` ADD INDEX `{$safe_index_name}` (`{$safe_column_name}`)");
        if ($result !== false) {
            $added[] = $safe_index_name;
            return;
        }

        $errors[] = $safe_index_name . ': ' . $wpdb->last_error;
    }

    public function add_intro_request_columns()
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_intro_requests';

        $columns_to_add = [
            'admin_message' => "ALTER TABLE `{$table}` ADD COLUMN `admin_message` text DEFAULT NULL AFTER `status`",
            'recruiter_reply' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_reply` text DEFAULT NULL AFTER `admin_message`",
        ];

        $added = [];
        $errors = [];

        foreach ($columns_to_add as $column_name => $sql) {
            $column_exists = $wpdb->get_results($wpdb->prepare(
                "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                 WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s",
                DB_NAME,
                $table,
                $column_name
            ));

            if (empty($column_exists)) {
                $result = $wpdb->query($sql);
                if ($result !== false) {
                    $added[] = $column_name;
                } else {
                    $errors[] = $column_name . ': ' . $wpdb->last_error;
                }
            }
        }

        return [
            'added' => $added,
            'errors' => $errors
        ];
    }

