    private function create_console_list_tables()
    {
        global $wpdb;

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';

        $charset_collate = $wpdb->get_charset_collate();
        $lists_table = $wpdb->prefix . 'sffc_crm_console_lists';
        $items_table = $wpdb->prefix . 'sffc_crm_console_list_items';

        $sql_lists = "CREATE TABLE {$lists_table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            list_name varchar(200) NOT NULL,
            description text,
            item_count int(11) DEFAULT 0,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY idx_user (user_id),
            KEY idx_updated (updated_at)
        ) {$charset_collate};";

        $sql_items = "CREATE TABLE {$items_table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            list_id bigint(20) NOT NULL,
            user_id bigint(20) NOT NULL,
            post_id bigint(20) DEFAULT 0,
            recruiter_id bigint(20) DEFAULT 0,
            recruiter_name varchar(200),
            recruiter_title varchar(200),
            recruiter_email varchar(255),
            recruiter_linkedin varchar(500),
            recruiter_firm varchar(200),
            recruiter_photo varchar(500),
            role_title varchar(255),
            company varchar(255),
            location varchar(255),
            company_logo varchar(500),
            match_score int(11) DEFAULT 0,
            reasons longtext,
            insight text,
            url varchar(500),
            status varchar(50) DEFAULT 'saved',
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            UNIQUE KEY unique_list_match (list_id, post_id, recruiter_id),
            KEY idx_user (user_id),
            KEY idx_list (list_id),
            KEY idx_recruiter (recruiter_id),
            KEY idx_post (post_id)
        ) {$charset_collate};";

        dbDelta($sql_lists);
        dbDelta($sql_items);

        $lists_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($lists_table))) === $lists_table;
        $items_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($items_table))) === $items_table;

        if ($lists_exists && $items_exists) {
            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Console list tables are ready.', 'senna-finance') . '</p></div>';
        } else {
            echo '<div class="notice notice-error is-dismissible"><p>' . esc_html__('Unable to verify Console list tables.', 'senna-finance') . '</p></div>';
        }
    }

    private function create_application_pack_tables($show_notice = true, $force_repair = false)
    {
        global $wpdb;

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';

        $table = $wpdb->prefix . 'sffc_crm_application_packs';
        $charset_collate = $wpdb->get_charset_collate();

        $sql = "CREATE TABLE {$table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) DEFAULT 0,
            user_name varchar(200) DEFAULT NULL,
            user_email varchar(255) DEFAULT NULL,
            post_id bigint(20) DEFAULT 0,
            recruiter_id bigint(20) DEFAULT 0,
            recruiter_name varchar(200) DEFAULT NULL,
            recruiter_email varchar(255) DEFAULT NULL,
            recruiter_linkedin varchar(500) DEFAULT NULL,
            role_title varchar(255) DEFAULT NULL,
            company_name varchar(255) DEFAULT NULL,
            location varchar(255) DEFAULT NULL,
            criteria_id bigint(20) DEFAULT 0,
            criteria_name varchar(255) DEFAULT NULL,
            pack_items text DEFAULT NULL,
            cv_label varchar(255) DEFAULT NULL,
            cv_url text DEFAULT NULL,
            cv_id varchar(100) DEFAULT NULL,
            cover_label varchar(255) DEFAULT NULL,
            cover_url text DEFAULT NULL,
            application_type varchar(50) DEFAULT 'standard',
            status varchar(50) DEFAULT 'requested',
            admin_notes text DEFAULT NULL,
            delivered_at datetime DEFAULT NULL,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY idx_user (user_id),
            KEY idx_post (post_id),
            KEY idx_status (status),
            KEY idx_created (created_at),
            KEY idx_app_type (application_type)
        ) {$charset_collate};";

        dbDelta($sql);
        $repair = $this->repair_application_pack_table_columns();

        if (!$show_notice) {
            return $repair;
        }

        $exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($table))) === $table;
        if ($exists && empty($repair['errors'])) {
            $message = $force_repair
                ? __('Application Pack table repaired successfully.', 'senna-finance')
                : __('Application Pack table is ready.', 'senna-finance');
            if (!empty($repair['added'])) {
                $message .= ' ' . sprintf(__('Added columns/indexes: %s', 'senna-finance'), implode(', ', $repair['added']));
            }
            echo '<div class="notice notice-success is-dismissible"><p>' . esc_html($message) . '</p></div>';
        } else {
            $error_message = !empty($repair['errors'])
                ? sprintf(__('Unable to repair Application Pack table: %s', 'senna-finance'), implode(', ', $repair['errors']))
                : __('Unable to verify Application Pack table.', 'senna-finance');
            echo '<div class="notice notice-error is-dismissible"><p>' . esc_html($error_message) . '</p></div>';
        }
    }

    private function repair_application_pack_table_columns()
    {
        global $wpdb;

        $table = $wpdb->prefix . 'sffc_crm_application_packs';
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($table))) === $table;
        if (!$table_exists) {
            return ['added' => [], 'errors' => []];
        }

        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");
        $columns = is_array($columns) ? $columns : [];
        $added = [];
        $errors = [];
        $column_definitions = [
            'recruiter_linkedin' => "ALTER TABLE {$table} ADD COLUMN recruiter_linkedin varchar(500) DEFAULT NULL AFTER recruiter_email",
            'cv_id' => "ALTER TABLE {$table} ADD COLUMN cv_id varchar(100) DEFAULT NULL AFTER cv_url",
            'application_type' => "ALTER TABLE {$table} ADD COLUMN application_type varchar(50) DEFAULT 'standard' AFTER cover_url",
            'admin_notes' => "ALTER TABLE {$table} ADD COLUMN admin_notes text DEFAULT NULL AFTER status",
            'delivered_at' => "ALTER TABLE {$table} ADD COLUMN delivered_at datetime DEFAULT NULL AFTER admin_notes",
        ];

        foreach ($column_definitions as $column => $sql) {
            if (!in_array($column, $columns, true)) {
                $result = $wpdb->query($sql);
                if ($result === false) {
                    $errors[] = $column;
                } else {
                    $added[] = $column;
                }
            }
        }

        $indexes = $wpdb->get_results("SHOW INDEX FROM {$table}", ARRAY_A);
        $has_application_type_index = false;
        if (is_array($indexes)) {
            foreach ($indexes as $index) {
                if (($index['Column_name'] ?? '') === 'application_type') {
                    $has_application_type_index = true;
                    break;
                }
            }
        }

        if (!$has_application_type_index && in_array('application_type', $columns, true)) {
            $result = $wpdb->query("ALTER TABLE {$table} ADD KEY idx_app_type (application_type)");
            if ($result === false) {
                $last_error = (string) $wpdb->last_error;
                if (stripos($last_error, 'Duplicate key name') === false && stripos($last_error, 'Duplicate') === false) {
                    $errors[] = 'idx_app_type';
                }
            } else {
                $added[] = 'idx_app_type';
            }
        }

        return ['added' => $added, 'errors' => $errors];
    }

    public function sffc_crm_rewrite_scanned_post_content(array $context, $processor = 'claude')
    {
        $processor = sanitize_key((string) $processor);
        if ($processor === 'claude') {
            return $this->rewrite_crm_post_content_with_claude($context);
        }

        return $this->rewrite_crm_post_content_deterministically($context);
    }

    public function sffc_crm_infer_scanned_post_fields(array $context, array $fallback = [])
    {
        return $this->infer_crm_post_autofill_with_claude($context, $fallback);
    }

