    }

    public function sffc_crm_finalize_promoted_job_draft($crm_post_id, array $post_data, array $group_ids = [])
    {
        $crm_post_id = (int) $crm_post_id;
        if ($crm_post_id <= 0) {
            return false;
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post-group.php';
        $group_model = new SFFC_CRM_Post_Group();
        $group_ids = array_slice(array_values(array_unique(array_filter(array_map('intval', $group_ids)))), 0, 1);

        if (!empty($group_ids)) {
            $group_model->remove_all_groups($crm_post_id);
            $group_model->assign_post($crm_post_id, (int) $group_ids[0]);
        } else {
            $suggested_group_ids = array_slice(array_values(array_unique(array_filter(array_map('intval', $group_model->suggest_groups_for_post($post_data, 1))))), 0, 1);
            if (!empty($suggested_group_ids)) {
                $group_model->remove_all_groups($crm_post_id);
                $group_model->assign_post($crm_post_id, (int) $suggested_group_ids[0]);
            } else {
                $group_model->remove_all_groups($crm_post_id);
                $auto_group_assignment = $this->determine_crm_auto_post_group($post_data);
                if (!empty($auto_group_assignment['name']) && !empty($auto_group_assignment['slug'])) {
                    $auto_group_id = $this->ensure_crm_auto_post_group(
                        $auto_group_assignment['name'],
                        $auto_group_assignment['slug'],
                        $auto_group_assignment['description'] ?? '',
                        (int) ($auto_group_assignment['display_order'] ?? 50)
                    );
                    if ($auto_group_id > 0) {
                        $group_model->assign_post($crm_post_id, $auto_group_id);
                    }
                } else {
                    $default_group_id = $this->ensure_default_post_group();
                    if ($default_group_id > 0) {
                        $group_model->assign_post($crm_post_id, $default_group_id);
                    }
                }
            }
        }

        $post_model = new SFFC_CRM_Post();
        $post_model->extract_keywords_for_post($crm_post_id, true);
        $this->sync_to_jobs_post_cpt($crm_post_id, $post_data);

        if (function_exists('sffc_crm_dispatch_internship_alerts')) {
            sffc_crm_dispatch_internship_alerts($crm_post_id);
        }

        return true;
    }
}

